INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91a3ba5-cd49-4fa0-876c-19f4435c2071', '登樂遊原', '登乐游原', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["園廟何年廢，登臨有故丘。","孤村連日靜，多雨及霖休。","常與秦山對，曾經漢主遊。","豈知千載後，萬事水東流。"]', '["园廟何年廢，登臨有故丘。","孤村連日静，多雨及霖休。","常與秦山对，曾經漢主游。","豈知千載後，万事水东流。"]', '诗', 'shi', '', NULL, '登樂遊原 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47a1058-7706-4f5b-b110-c5078de3abd6', '題惟幹上人房', '題惟幹上人房', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["繩牀茅屋下，獨坐味閑安。","苦行無童子，忘機避宰官。","是非齊已久，夏臘比應難。","更悟真如性，塵心稍自寬。"]', '["繩牀茅屋下，独坐味闲安。","苦行無童子，忘機避宰官。","是非齊已久，夏臘比應难。","更悟真如性，塵心稍自寬。"]', '诗', 'shi', '', NULL, '題惟幹上人房 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c82c67-0a34-4739-9fa6-6044377e75f4', '會鳳翔張少尹南亭', '會鳳翔張少尹南亭', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遠過張正見，詩興自依依。","西府軍城暮，南庭吏事稀。","草簷宜日過，花圃任煙歸。","更料重關外，羣僚候啟扉。"]', '["远過張正见，诗兴自依依。","西府軍城暮，南庭吏事稀。","草簷宜日過，花圃任煙归。","更料重关外，羣僚候啟扉。"]', '诗', 'shi', '', NULL, '會鳳翔張少尹南亭 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0fbc143-5b37-4eb0-a44d-543527754497', '早春宴高陵滑少府', '早春宴高陵滑少府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["且寬沈簿領，應賴酒如澠。","春夜霜猶下，東城月未昇。","清言饒醉客，亂舞避寒燈。","名字書仙籍，諸生病未能。"]', '["且寬沈簿領，應賴酒如澠。","春夜霜猶下，东城月未昇。","清言饒醉客，亂舞避寒灯。","名字书仙籍，諸生病未能。"]', '诗', 'shi', '', NULL, '早春宴高陵滑少府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86232f7-8794-4b8e-8e40-e84b329e6720', '寒蜂採菊蕊', '寒蜂採菊蕊', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遊颺下晴空，尋芳到菊叢。","帶聲來蕊上，連影在香中。","去住霑餘霧，高低順過風。","終慙異蝴蝶，不與夢魂通。"]', '["游颺下晴空，尋芳到菊叢。","带声来蕊上，連影在香中。","去住霑餘霧，高低順過风。","終慙異蝴蝶，不與梦魂通。"]', '诗', 'shi', '', NULL, '寒蜂採菊蕊 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fdeec56-ef6e-4d64-895c-1ab3ea90125d', '題楊著別業', '題楊著別業', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["柳巷向陂斜，回陽噪亂鵶。","農桑子雲業，書籍蔡邕家。","暮葉初飜砌，寒池轉露沙。","如何守儒行，寂寞過年華。"]', '["柳巷向陂斜，回陽噪亂鵶。","農桑子云業，书籍蔡邕家。","暮葉初飜砌，寒池轉露沙。","如何守儒行，寂寞過年华。"]', '诗', 'shi', '', NULL, '題楊著別業 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa2d3278-87d8-4be7-a9be-eaa04c23cd6a', '送太僕寺李丞赴都到桃林塞', '送太僕寺李丞赴都到桃林塞', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遠過桃林塞，休年自昔聞。","曲河隨暮草，重阜接閑雲。","造父爲周御，詹嘉守晉軍。","應多懷古思，落葉又紛紛。"]', '["远過桃林塞，休年自昔闻。","曲河隨暮草，重阜接闲云。","造父爲周御，詹嘉守晉軍。","應多懷古思，落葉又紛紛。"]', '诗', 'shi', '', NULL, '送太僕寺李丞赴都到桃林塞 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c91d74-8d48-4fa9-b02e-9d057b44648a', '宋中', '宋中', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["百戰無軍食，孤城陷虜塵。","爲傷多易子，翻弔淺爲臣。","漫漫東流水，悠悠南陌人。","空思前事往，向曉淚霑巾。"]', '["百戰無軍食，孤城陷虜塵。","爲傷多易子，翻弔淺爲臣。","漫漫东流水，悠悠南陌人。","空思前事往，向晓泪霑巾。"]', '诗', 'shi', '', NULL, '宋中 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bdf85f9-6a19-4dc1-8469-72f0e1dedfe8', '陪讌湖州公堂', '陪讌湖州公堂', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["謝公爲楚郡，坐客是瑤林。","文府重門奧，儒源積浪深。","壺觴邀薄醉，笙磬發高音。","末至才仍短，難隨白雪吟。"]', '["謝公爲楚郡，坐客是瑤林。","文府重门奧，儒源積浪深。","壺觴邀薄醉，笙磬發高音。","末至才仍短，难隨白雪吟。"]', '诗', 'shi', '', NULL, '陪讌湖州公堂 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde38318-f7ee-49c7-a1c2-37a1ff7347e6', '尋覺公因寄李二端司空十四曙', '尋覺公因寄李二端司空十四曙', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["少年嘗昧道，無事日悠悠。","及至悟生死，尋僧已白頭。","雲迴廬瀑雨，樹落給園秋。","爲我謝宗許，塵中難久留。"]', '["少年嘗昧道，無事日悠悠。","及至悟生死，尋僧已白头。","云迴廬瀑雨，樹落給园秋。","爲我謝宗許，塵中难久留。"]', '诗', 'shi', '', NULL, '尋覺公因寄李二端司空十四曙 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faad20a7-b49d-4cf1-8116-f5339b064b9a', '送郭秀才赴舉', '送郭秀才赴舉', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["鄉賦鹿鳴篇，君爲貢士先。","新經夢筆夜，纔比棄繻年。","海雨沾隋柳，江潮赴楚船。","相看南去雁，離恨倍潸然。"]', '["乡賦鹿鳴篇，君爲貢士先。","新經梦笔夜，纔比棄繻年。","海雨沾隋柳，江潮赴楚船。","相看南去雁，離恨倍潸然。"]', '诗', 'shi', '', NULL, '送郭秀才赴舉 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf19855-c331-44a3-86b6-56b055e16037', '送王閏', '送王閏', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["相送臨漢水，愴然望故關。","江蕪連夢澤，楚雪入商山。","語我他年舊，看君此日還。","因將自悲淚，一灑別離間。"]', '["相送臨漢水，愴然望故关。","江蕪連梦澤，楚雪入商山。","語我他年旧，看君此日還。","因將自悲泪，一灑別離间。"]', '诗', 'shi', '', NULL, '送王閏 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f06a818-7cdf-4668-98f6-3f5595bdd369', '送蜀客還', '送蜀客還', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["萬峯深積翠，路向此中難。","欲暮多羇思，因高莫遠看。","卓家人寂寞，揚子業荒殘。","唯見岷山水，悠悠帶月寒。"]', '["万峯深積翠，路向此中难。","欲暮多羇思，因高莫远看。","卓家人寂寞，揚子業荒殘。","唯见岷山水，悠悠带月寒。"]', '诗', 'shi', '', NULL, '送蜀客還 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7de18c-8fcb-4984-942c-5c5f224af739', '送海州盧錄事', '送海州盧錄事', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["之官逢計吏，風土問如何。","海口朝陽近，青州春氣多。","郊原鵬影到，樓閣蜃雲和。","損益關從事，期聽勞者歌。"]', '["之官逢計吏，风土问如何。","海口朝陽近，青州春氣多。","郊原鵬影到，楼閣蜃云和。","損益关從事，期听勞者歌。"]', '诗', 'shi', '', NULL, '送海州盧錄事 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5042dcf-6cfb-4d33-9bd9-cd0784402a7e', '登鍾山館', '登鍾山館', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["匹馬宜春路，蕭條背館心。","澗花寒夕雨，潭水黑朝林。","野市魚鹽隘，江村竹葦深。","子規何處發，青樹滿高岑。"]', '["匹马宜春路，蕭條背館心。","澗花寒夕雨，潭水黑朝林。","野市鱼鹽隘，江村竹葦深。","子規何处發，青樹满高岑。"]', '诗', 'shi', '', NULL, '登鍾山館 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('241f5a8b-91ab-4146-bf80-f0248dfbf3f5', '秋日', '秋日', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["照耀天山外，飛鵶幾共過。","微紅拂秋漢，片白透長波。","影促寒汀薄，光殘古木多。","金霞與雲氣，散漫復相和。"]', '["照耀天山外，飞鵶幾共過。","微紅拂秋漢，片白透长波。","影促寒汀薄，光殘古木多。","金霞與云氣，散漫复相和。"]', '诗', 'shi', '', NULL, '秋日 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0cf3753-27a8-45f4-8797-7e1cc8dbef2b', '贈苗員外', '贈苗員外', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["爲郎日賦詩，小謝少年時。","業繼儒門後，心多道者期。","晚迴長樂殿，新出夜明祠。","行樂西園暮，春風動柳絲。"]', '["爲郎日賦诗，小謝少年时。","業繼儒门後，心多道者期。","晚迴长乐殿，新出夜明祠。","行乐西园暮，春风动柳絲。"]', '诗', 'shi', '', NULL, '贈苗員外 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a70c7d-e01e-46b4-9764-647153bf10d0', '詣順公問道', '詣順公问道', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["此身知是妄，遠遠詣支公。","何法住持後，能逃生死中。","秋苔經古徑，蘀葉滿疎叢。","方便如開誘，南宗與北宗。"]', '["此身知是妄，远远詣支公。","何法住持後，能逃生死中。","秋苔經古徑，蘀葉满疎叢。","方便如开誘，南宗與北宗。"]', '诗', 'shi', '', NULL, '詣順公問道 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8691fc-fd80-43e0-8d36-761684e18479', '廢慶寶寺', '廢慶寶寺', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["黃葉前朝寺，無僧寒殿開。","池晴龜出暴，松暝鶴飛迴。","古井碑橫草，陰廊畫雜苔。","禪宮亦銷歇，塵世轉堪哀。"]', '["黄葉前朝寺，無僧寒殿开。","池晴龟出暴，松暝鹤飞迴。","古井碑橫草，陰廊畫杂苔。","禪宮亦銷歇，塵世轉堪哀。"]', '诗', 'shi', '', NULL, '廢慶寶寺 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223bb467-399f-423d-8e76-1a6a2a30787e', '赴許州留別洛中親故', '赴許州留別洛中親故', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["淳風今變俗，末學誤爲文。","幸免投湘浦，那辭近汝墳。","山遮魏闕路，日隱洛陽雲。","誰念聯翩翼，烟中獨失羣。"]', '["淳风今变俗，末学誤爲文。","幸免投湘浦，那辞近汝墳。","山遮魏闕路，日隐洛陽云。","誰念聯翩翼，烟中独失羣。"]', '诗', 'shi', '', NULL, '赴許州留別洛中親故 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75cc2c9-545d-4604-a912-837abba0724e', '送葉尊師歸處州', '送葉尊師归处州', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["風馭南行遠，長山與夜江。","羣祆離分野，五嶽拜旌幢。","石髓調金鼎，雲漿實玉缸。","㹞㹞吠聲曉，洞府有仙厖。"]', '["风馭南行远，长山與夜江。","羣祆離分野，五嶽拜旌幢。","石髓調金鼎，云漿實玉缸。","㹞㹞吠声晓，洞府有仙厖。"]', '诗', 'shi', '', NULL, '送葉尊師歸處州 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f58c81-ba56-4a87-9544-df2374830e6f', '酬張少尹秋日鳳翔西郊見寄', '酬張少尹秋日鳳翔西郊见寄', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["鼎氣孕河汾，英英濟舊勳。","劉生曾任俠，張率自能文。","官佐征西府，名齊將上軍。","秋山遙出浦，野鶴暮離羣。","遠恨邊笳起，勞歌騎吏聞。","廢關人不到，荒戍日空曛。","草木涼初變，陰晴景半分。","疊蟬臨積水，亂燕入過雲。","麗藻終思我，衰髯亦爲君。","閑吟寡和曲，庭葉漸紛紛。"]', '["鼎氣孕河汾，英英濟旧勳。","劉生曾任俠，張率自能文。","官佐征西府，名齊將上軍。","秋山遙出浦，野鹤暮離羣。","远恨邊笳起，勞歌騎吏闻。","廢关人不到，荒戍日空曛。","草木涼初变，陰晴景半分。","叠蟬臨積水，亂燕入過云。","丽藻終思我，衰髯亦爲君。","闲吟寡和曲，庭葉漸紛紛。"]', '诗', 'shi', '', NULL, '酬張少尹秋日鳳翔西郊見寄 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa6132d-c61e-4218-af24-5d9009e6795d', '春日書情寄元校書伯和相國元子', '春日书情寄元校书伯和相国元子', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["數歲平津邸，諸生出門時。","羇孤力行早，疎賤託身遲。","芳草看無厭，青山到未期。","貧居悲老大，春日上茅茨。","衛玠瓊瑤色，玄成鼎鼐姿。","友朋漢相府，兄弟謝家詩。","律合聲雖應，勞歌調自悲。","流年不可住，惆悵鏡中絲。"]', '["數歲平津邸，諸生出门时。","羇孤力行早，疎賤託身遲。","芳草看無厭，青山到未期。","貧居悲老大，春日上茅茨。","衛玠瓊瑤色，玄成鼎鼐姿。","友朋漢相府，兄弟謝家诗。","律合声雖應，勞歌調自悲。","流年不可住，惆悵镜中絲。"]', '诗', 'shi', '', NULL, '春日書情寄元校書伯和相國元子 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c7a9dd-fdba-4ae7-8e31-6ebbf1f7c024', '奉送崔侍御和蕃', '奉送崔侍御和蕃', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["萬里華戎隔，風沙道路秋。","新恩明主啟，舊好使臣修。","旌節隨邊草，關山見戍樓。","俗殊人左袵，地遠水西流。","日暮冰先合，春深雪未休。","無論善長對，博望自封侯。"]', '["万里华戎隔，风沙道路秋。","新恩明主啟，旧好使臣修。","旌節隨邊草，关山见戍楼。","俗殊人左袵，地远水西流。","日暮冰先合，春深雪未休。","無論善长对，博望自封侯。"]', '诗', 'shi', '', NULL, '奉送崔侍御和蕃 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3dc1675-b12f-4c6f-8346-2f05a369528e', '春日即事', '春日即事', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["芳菲那變易，年鬢自蹉跎。","室與千峯對，門唯二仲過。","宦情知己少，生事託人多。","草色微風長，鶯聲細雨和。","幾時猶滯拙，終日望恩波。","縱欲論相報，無如漂母何。"]', '["芳菲那变易，年鬢自蹉跎。","室與千峯对，门唯二仲過。","宦情知己少，生事託人多。","草色微风长，鶯声細雨和。","幾时猶滯拙，終日望恩波。","縱欲論相報，無如漂母何。"]', '诗', 'shi', '', NULL, '春日即事 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8b0af7-e222-4396-b29a-511afca4b8e7', '仙山行', '仙山行', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["深溪人不到，杖策獨緣源。","花落尋無徑，雞鳴覺近村。","數翁皆藉草，對[弈]復傾尊。","看畢初爲局，歸逢幾世孫。","雲迷入洞處，水引出山門。","惆悵歸城郭，樵柯迹尚存。"]', '["深溪人不到，杖策独緣源。","花落尋無徑，雞鳴覺近村。","數翁皆藉草，对[弈]复傾尊。","看畢初爲局，归逢幾世孫。","云迷入洞处，水引出山门。","惆悵归城郭，樵柯迹尚存。"]', '诗', 'shi', '', NULL, '仙山行 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf3d439-2a29-424a-8fad-501659965b59', '得替後書懷上第五相公', '得替後书懷上第五相公', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["誰語恓惶客，偏承顧盼私。","應逾骨肉分，敢忘死生期。","山縣唯荒壘，雲屯盡老師。","庖人寧自代，食蘗謬相推。","黃綬名空罷，青春鬢又衰。","還來掃門處，猶未報恩時。","獨立花飛滿，無言月下遲。","不知丞相意，更欲遣何之。"]', '["誰語恓惶客，偏承顧盼私。","應逾骨肉分，敢忘死生期。","山縣唯荒壘，云屯尽老師。","庖人寧自代，食蘗謬相推。","黄綬名空罷，青春鬢又衰。","還来掃门处，猶未報恩时。","独立花飞满，無言月下遲。","不知丞相意，更欲遣何之。"]', '诗', 'shi', '', NULL, '得替後書懷上第五相公 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882976bf-5aa1-4234-95b4-bff65df45589', '入塞曲', '入塞曲', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["將軍帶十圍，重錦製戎衣。","猿臂銷弓力，虬鬚長劒威。","首登平樂宴，新破大宛歸。","樓上誅姬笑，門前問客稀。","暮烽玄兔急，秋草紫騮肥。","未奉君王詔，高槐晝掩扉。"]', '["將軍带十圍，重錦製戎衣。","猿臂銷弓力，虬鬚长劒威。","首登平乐宴，新破大宛归。","楼上誅姬笑，门前问客稀。","暮烽玄兔急，秋草紫騮肥。","未奉君王詔，高槐晝掩扉。"]', '诗', 'shi', '', NULL, '入塞曲 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51992a8-b4a7-46a8-8bf1-43a71b4f4ad3', '送姚校書因歸河中', '送姚校书因归河中', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["十年相見少，一歲又還鄉。","去住人惆悵，東西路渺茫。","古陂無茂草，高樹有殘陽。","委棄秋來稻，彫疎採後桑。","月輪生舜廟，河水出關牆。","明日過閭里，光輝芸閣郎。"]', '["十年相见少，一歲又還乡。","去住人惆悵，东西路渺茫。","古陂無茂草，高樹有殘陽。","委棄秋来稻，彫疎採後桑。","月輪生舜廟，河水出关牆。","明日過閭里，光輝芸閣郎。"]', '诗', 'shi', '', NULL, '送姚校書因歸河中 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b78aaf7-4de0-4fc2-a524-8eaa6e66a244', '題清源寺', '題清源寺', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["儒墨兼宗道，雲泉隱舊廬。","盂城今寂寞，輞水自紆餘。","內學銷多累，西林易故居。","深房春竹老，細雨夜鐘疎。","陳跡留金地，遺文在石渠。","不知登座客，誰得蔡邕書。"]', '["儒墨兼宗道，云泉隐旧廬。","盂城今寂寞，輞水自紆餘。","內学銷多累，西林易故居。","深房春竹老，細雨夜鐘疎。","陳跡留金地，遺文在石渠。","不知登座客，誰得蔡邕书。"]', '诗', 'shi', '', NULL, '題清源寺 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('175b7fd0-26f3-4b13-8526-3348152fed32', '奉送蔣尚書兼御史大夫東都留守', '奉送蔣尚书兼御史大夫东都留守', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["副相威名重，春卿禮樂崇。","錫珪仍拜下，分命遂居東。","高斾翻秋日，清鐃引細風。","蟬稀金谷樹，草徧德陽宮。","敎用儒門儉，兵依武庫雄。","誰云千載後，周召獨爲公。"]', '["副相威名重，春卿禮乐崇。","錫珪仍拜下，分命遂居东。","高斾翻秋日，清鐃引細风。","蟬稀金谷樹，草徧德陽宮。","敎用儒门儉，兵依武庫雄。","誰云千載後，周召独爲公。"]', '诗', 'shi', '', NULL, '奉送蔣尚書兼御史大夫東都留守 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07d6638d-5f87-4f48-aca5-a0ee639bc795', '喜侯十七校書見訪', '喜侯十七校书见訪', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["東城獨屏居，有客到吾廬。","發廩因舂黍，開畦復翦蔬。","許酣令乞酒，辭窶任無魚。","徧出新成句，更通未悟書。","藤絲秋不長，竹粉雨仍餘。","誰爲須張燭，涼空有望舒。"]', '["东城独屏居，有客到吾廬。","發廩因舂黍，开畦复翦蔬。","許酣令乞酒，辞窶任無鱼。","徧出新成句，更通未悟书。","藤絲秋不长，竹粉雨仍餘。","誰爲須張燭，涼空有望舒。"]', '诗', 'shi', '', NULL, '喜侯十七校書見訪 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b04a3a4-f013-41dd-a0b9-865d58781400', '晚春青門林亭燕集', '晚春青门林亭燕集', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["都門連騎出，東野柳如絲。","秦苑看山處，王孫逐草時。","歡遊難再得，衰老是前期。","林靜鶯啼遠，春深日過遲。","落花今夕思，秉燭古人詩。","對酒當爲樂，雙杯未可辭。"]', '["都门連騎出，东野柳如絲。","秦苑看山处，王孫逐草时。","歡游难再得，衰老是前期。","林静鶯啼远，春深日過遲。","落花今夕思，秉燭古人诗。","对酒當爲乐，雙杯未可辞。"]', '诗', 'shi', '', NULL, '晚春青門林亭燕集 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c06a24-ace5-4c54-85f6-dcd4b6893b3f', '晚秋東遊寄猗氏第五明府解縣韓明府', '晚秋东游寄猗氏第五明府解縣韓明府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["步出青門去，疎鐘隔上林。","四郊多難日，千里獨歸心。","暮鳥聲偏苦，秋雲色易陰。","亂墳松柏少，野徑草茅深。","灞涘袁安履，汾南宓賤琴。","何由聽白雪，秪益淚霑襟。"]', '["步出青门去，疎鐘隔上林。","四郊多难日，千里独归心。","暮鸟声偏苦，秋云色易陰。","亂墳松柏少，野徑草茅深。","灞涘袁安履，汾南宓賤琴。","何由听白雪，秪益泪霑襟。"]', '诗', 'shi', '', NULL, '晚秋東遊寄猗氏第五明府解縣韓明府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac51ade1-4a21-47ce-a063-2fe7c05a16fc', '奉和元承杪秋憶終南舊居', '奉和元承杪秋憶終南旧居', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["白玉郎仍少，羊車上路平。","秋風搖遠草，舊業起高情。","亂樹通秦苑，重原接杜城。","溪雲隨暮淡，野水帶寒清。","廣樹留峯翠，閑門響葉聲。","近樵應已燒，多稼又新成。","解佩從休沐，承家豈退耕。","恭侯有遺躅，何事學泉明。"]', '["白玉郎仍少，羊车上路平。","秋风搖远草，旧業起高情。","亂樹通秦苑，重原接杜城。","溪云隨暮淡，野水带寒清。","廣樹留峯翠，闲门响葉声。","近樵應已燒，多稼又新成。","解佩從休沐，承家豈退耕。","恭侯有遺躅，何事学泉明。"]', '诗', 'shi', '', NULL, '奉和元承杪秋憶終南舊居 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a460c1-660c-400c-81e8-c085877eb300', '晚夏即事臨南居', '晚夏即事臨南居', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["何須學從宦，其奈本無機。","蕙草芳菲歇，青山早晚歸。","廣庭餘落照，高枕對閑扉。","樹色迎秋老，蟬聲過雨稀。","艱難逢事異，去就與時違。","遙憶衡門外，蒼蒼三徑微。"]', '["何須学從宦，其奈本無機。","蕙草芳菲歇，青山早晚归。","廣庭餘落照，高枕对闲扉。","樹色迎秋老，蟬声過雨稀。","艱难逢事異，去就與时違。","遙憶衡门外，蒼蒼三徑微。"]', '诗', 'shi', '', NULL, '晚夏即事臨南居 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6915cdbf-d7ee-4708-a247-7c1b83d0b538', '省試驪珠詩', '省試驪珠诗', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["是日重泉下，言探徑寸珠。","龍鱗今不逆，魚目也應殊。","掌上星初滿，盤中月正孤。","酬恩光莫及，照乘色難踰。","欲問投人否，先論按劒無。","儻憐希代價，敢對此冰壺。"]', '["是日重泉下，言探徑寸珠。","龙鱗今不逆，鱼目也應殊。","掌上星初满，盤中月正孤。","酬恩光莫及，照乘色难踰。","欲问投人否，先論按劒無。","儻怜希代價，敢对此冰壺。"]', '诗', 'shi', '', NULL, '省試驪珠詩 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57259261-28ad-4dde-a63f-e3bb6a9dd1a7', '元日早朝', '元日早朝', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["九陌朝臣滿，三朝候鼓賒。","遠珂時接韻，攢炬偶成花。","紫貝爲高闕，黃龍建大牙。","參差萬戟合，左右八貂斜。","羽扇紛朱檻，金鑪隔翠華。","微風傳曙漏，曉日上春霞。","環珮聲重疊，蠻夷服等差。","樂和天易感，山固壽無涯。","渥澤千年聖，車書四海家。","盛明多在位，誰得守蓬麻。"]', '["九陌朝臣满，三朝候鼓賒。","远珂时接韻，攢炬偶成花。","紫貝爲高闕，黄龙建大牙。","參差万戟合，左右八貂斜。","羽扇紛朱檻，金鑪隔翠华。","微风傳曙漏，晓日上春霞。","环珮声重叠，蠻夷服等差。","乐和天易感，山固壽無涯。","渥澤千年聖，车书四海家。","盛明多在位，誰得守蓬麻。"]', '诗', 'shi', '', NULL, '元日早朝 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c0e372-8785-479b-98a8-d88f25df6730', '送歸中丞使新羅', '送归中丞使新羅', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遠國通王化，儒林得使臣。","六君成典冊，萬里奉絲綸。","雲水連孤棹，恩私在一身。","悠悠龍節去，渺渺蜃樓新。","望裏行還暮，波中歲又春。","昏明看日御，靈怪問舟人。","城邑分華夏，衣裳擬縉紳。","他時禮命畢，歸路勿迷津。"]', '["远国通王化，儒林得使臣。","六君成典冊，万里奉絲綸。","云水連孤棹，恩私在一身。","悠悠龙節去，渺渺蜃楼新。","望裏行還暮，波中歲又春。","昏明看日御，靈怪问舟人。","城邑分华夏，衣裳擬縉紳。","他时禮命畢，归路勿迷津。"]', '诗', 'shi', '', NULL, '送歸中丞使新羅 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eaf1c55-1afe-42de-a6f5-d350c5f25296', '贈興平鄭明府', '贈兴平鄭明府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["海內兵猶在，關西賦未均。","仍勞持斧使，尚宰茂陵人。","遙夜重城掩，清宵片月新。","綠琴聽古調，白屋被深仁。","跡與儒生合，心惟靜者親。","深情先結契，薄宦早趨塵。","貧病休何日，艱難過此身。","悠悠行遠道，冉冉過良辰。","明主知封事，長沮笑問津。","棲遑忽相見，欲語淚霑巾。"]', '["海內兵猶在，关西賦未均。","仍勞持斧使，尚宰茂陵人。","遙夜重城掩，清宵片月新。","綠琴听古調，白屋被深仁。","跡與儒生合，心惟静者親。","深情先結契，薄宦早趨塵。","貧病休何日，艱难過此身。","悠悠行远道，冉冉過良辰。","明主知封事，长沮笑问津。","棲遑忽相见，欲語泪霑巾。"]', '诗', 'shi', '', NULL, '贈興平鄭明府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe1b9db-a556-4d82-8212-54f7137e63d9', '和王懷州觀西營秋射', '和王懷州观西營秋射', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["謝公親校武，草碧露漫漫。","落葉停高駕，空林滿從官。","迎籌皆疊鼓，揮箭或移竿。","名借三軍勇，功推百中難。","主皮山郡晚，飲筭柳營寒。","明日開鈴閣，新詩雙玉盤。"]', '["謝公親校武，草碧露漫漫。","落葉停高駕，空林满從官。","迎籌皆叠鼓，揮箭或移竿。","名借三軍勇，功推百中难。","主皮山郡晚，饮筭柳營寒。","明日开鈴閣，新诗雙玉盤。"]', '诗', 'shi', '', NULL, '和王懷州觀西營秋射 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055ee674-3e13-4973-8a53-1bdc400abcf4', '晚登虔州即事寄李侍御', '晚登虔州即事寄李侍御', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["章溪與貢水，何事會波瀾。","萬里歸人少，孤舟行路難。","春光浮曲浪，暮色隔連灘。","花發從南早，江流向北寬。","故交參盛府，新角聳危冠。","楚劒期終割，隋珠惜未彈。","酒醒愁轉極，別遠淚初乾。","願保喬松質，青青過大寒。"]', '["章溪與貢水，何事會波瀾。","万里归人少，孤舟行路难。","春光浮曲浪，暮色隔連灘。","花發從南早，江流向北寬。","故交參盛府，新角聳危冠。","楚劒期終割，隋珠惜未彈。","酒醒愁轉極，別远泪初乾。","願保喬松質，青青過大寒。"]', '诗', 'shi', '', NULL, '晚登虔州即事寄李侍御 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82caff2c-18ae-499b-9c2d-f5bab6dc2e54', '奉和第五相公登鄱陽郡城西樓', '奉和第五相公登鄱陽郡城西楼', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["茂德爲邦久，豐貂舊相尊。","發生傳雨露，均養助乾坤。","曉肆登樓目，春銷戀闕魂。","女牆分吏事，遠道啟津門。","湓浦潮聲盡，鍾陵暮色繁。","夕陽移夢土，芳草接湘源。","封內羣甿復，兵間百賦存。","童牛耕廢畝，壕木遶新村。","野步漁聲溢，荒祠鼓舞喧。","高齋成五字，遠岫發孤猨。","一顧承英達，多榮及子孫。","家貧仍受賜，身老未酬恩。","屬和瑤華曲，堪將繫組綸。"]', '["茂德爲邦久，豐貂旧相尊。","發生傳雨露，均養助乾坤。","晓肆登楼目，春銷戀闕魂。","女牆分吏事，远道啟津门。","湓浦潮声尽，鍾陵暮色繁。","夕陽移梦土，芳草接湘源。","封內羣甿复，兵间百賦存。","童牛耕廢畝，壕木遶新村。","野步漁声溢，荒祠鼓舞喧。","高斋成五字，远岫發孤猨。","一顧承英達，多榮及子孫。","家貧仍受賜，身老未酬恩。","屬和瑤华曲，堪將繫組綸。"]', '诗', 'shi', '', NULL, '奉和第五相公登鄱陽郡城西樓 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca2e8c3-79be-4b43-a8c8-9448e3ee0927', '甘泉詩', '甘泉诗', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["異井甘如醴，深仁遠未涯。","氣寒堪破暑，源淨自蠲邪。","修綆懸冰甃，新桐蔭玉沙。","帶星凝曉露，拂霧湧秋華。","綠溢涵千仞，清泠飲萬家。","何能葛洪宅，終日閉煙霞。"]', '["異井甘如醴，深仁远未涯。","氣寒堪破暑，源淨自蠲邪。","修綆懸冰甃，新桐蔭玉沙。","带星凝晓露，拂霧湧秋华。","綠溢涵千仞，清泠饮万家。","何能葛洪宅，終日閉煙霞。"]', '诗', 'shi', '', NULL, '甘泉詩 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee861e07-c37b-47b9-a5b1-641d43834d15', '發綿津驛', '發綿津驛', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["孤舟北去暮心傷，細雨東風春草長。","杳杳短亭分水陸，隆隆遠鼓集漁商。","千叢野竹連湘浦，一派寒江下吉陽。","欲問長安今遠近，初年塞雁有歸行。"]', '["孤舟北去暮心傷，細雨东风春草长。","杳杳短亭分水陸，隆隆远鼓集漁商。","千叢野竹連湘浦，一派寒江下吉陽。","欲问长安今远近，初年塞雁有归行。"]', '诗', 'shi', '', NULL, '發綿津驛 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7287a7-ee3f-4ef8-a4fa-e758745b0a5d', '塞上曲', '塞上曲', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["慣習干戈事鞍馬，初從少小在邊城。","身微久屬千夫長，家遠多親五郡兵。","嬾說疆場曾大獲，且悲年鬢老長征。","寒鴻過盡殘陽裏，樓上悽悽暮角聲。"]', '["慣習干戈事鞍马，初從少小在邊城。","身微久屬千夫长，家远多親五郡兵。","嬾说疆場曾大獲，且悲年鬢老长征。","寒鴻過尽殘陽裏，楼上悽悽暮角声。"]', '诗', 'shi', '', NULL, '塞上曲 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807c4c41-ecef-403e-9d28-551399bd1f2f', '路旁老人', '路旁老人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["老人獨坐倚官樹，欲語潸然淚便垂。","陌上歸心無產業，城邊戰骨有親知。","餘生尚在艱難日，長路多逢輕薄兒。","綠水青山雖似舊，如今貧後復何爲。"]', '["老人独坐倚官樹，欲語潸然泪便垂。","陌上归心無產業，城邊戰骨有親知。","餘生尚在艱难日，长路多逢轻薄兒。","綠水青山雖似旧，如今貧後复何爲。"]', '诗', 'shi', '', NULL, '路旁老人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a73a6b4-a6a3-4f6e-93e1-812ee4212ea4', '贈別劉員外長卿', '贈別劉員外长卿', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["清如寒玉直如絲，世故多虞事莫期。","建德津亭人別夜，新安江水月明時。","爲文易老皆知苦，謫宦無名倍足悲。","不學朱雲能折檻，空羞獻納在丹墀。"]', '["清如寒玉直如絲，世故多虞事莫期。","建德津亭人別夜，新安江水月明时。","爲文易老皆知苦，謫宦無名倍足悲。","不学朱云能折檻，空羞獻納在丹墀。"]', '诗', 'shi', '', NULL, '贈別劉員外長卿 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83db426c-3099-48f3-b939-b89ffcb8dd72', '宿萬固寺因寄嚴補闕', '宿万固寺因寄嚴補闕', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["曉隨樵客到青冥，因禮山僧宿化城。","鐘梵已休初入定，有無皆離本難名。","雲開半夜千林靜，月上中峰萬壑明。","爲報故人雷處士，塵心終日自勞生。"]', '["晓隨樵客到青冥，因禮山僧宿化城。","鐘梵已休初入定，有無皆離本难名。","云开半夜千林静，月上中峰万壑明。","爲報故人雷处士，塵心終日自勞生。"]', '诗', 'shi', '', NULL, '宿萬固寺因寄嚴補闕 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea4a079-7e65-4aa0-be8c-34dfd376efe3', '岐陽客舍呈張明府', '岐陽客舍呈張明府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["逸妻稚子應溝壑，歸路茫茫東去遙。","涼葉下時心悄悄，空齋夢裏雨蕭蕭。","星霜漸見侵華髮，生長虛聞在聖朝。","知己只今何處在，故山無事別漁樵。"]', '["逸妻稚子應溝壑，归路茫茫东去遙。","涼葉下时心悄悄，空斋梦裏雨蕭蕭。","星霜漸见侵华髮，生长虛闻在聖朝。","知己只今何处在，故山無事別漁樵。"]', '诗', 'shi', '', NULL, '岐陽客舍呈張明府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e128a79-2faa-4ca7-836a-d206056ae268', '奉和李觀察登河中白樓', '奉和李观察登河中白楼', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["城上高樓飛鳥齊，從公一遂躡丹梯。","黃河曲盡流天外，白日輪輕落海西。","玉樹九重長在夢，雲衢一望杳如迷。","何心更和陽春奏，況復秋風聞戰鼙。"]', '["城上高楼飞鸟齊，從公一遂躡丹梯。","黄河曲尽流天外，白日輪轻落海西。","玉樹九重长在梦，云衢一望杳如迷。","何心更和陽春奏，況复秋风闻戰鼙。"]', '诗', 'shi', '', NULL, '奉和李觀察登河中白樓 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e8672d8-cbab-49dd-9dd1-13a17097b811', '朝下寄韓舍人', '朝下寄韓舍人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["侍臣鳴珮出西曹，鸞殿分階翊綵旄。","瑞氣迴浮青玉案，日華遙上赤霜袍。","花間焰焰雲旗合，鳥外亭亭露掌高。","肯念萬年芳樹裏，隨風一葉在蓬蒿。"]', '["侍臣鳴珮出西曹，鸾殿分階翊綵旄。","瑞氣迴浮青玉案，日华遙上赤霜袍。","花间焰焰云旗合，鸟外亭亭露掌高。","肯念万年芳樹裏，隨风一葉在蓬蒿。"]', '诗', 'shi', '', NULL, '朝下寄韓舍人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d774e2-5c3f-4127-a82c-439c9af3529c', '賀李觀察禱河神降雨', '賀李观察禱河神降雨', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["質明齋祭北風微，騶馭千羣擁廟扉。","玉帛纔敷雲淡淡，笙鏞未撤雨霏霏。","路邊五稼添膏長，河上雙旌帶溼歸。","若出敬亭山下作，何人敢和謝玄暉。"]', '["質明斋祭北风微，騶馭千羣擁廟扉。","玉帛纔敷云淡淡，笙鏞未撤雨霏霏。","路邊五稼添膏长，河上雙旌带溼归。","若出敬亭山下作，何人敢和謝玄暉。"]', '诗', 'shi', '', NULL, '賀李觀察禱河神降雨 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb88b6b-ee07-4359-ab0b-c9c5756383d7', '上將行', '上將行', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["蕭關掃定犬羊羣，閉閣層城白日曛。","櫪上驊騮嘶鼓角，門前老將識風雲。","旌旗四面寒山暎，絲管千家靜夜聞。","誰道古來多簡冊，功臣唯有衛將軍。"]', '["蕭关掃定犬羊羣，閉閣層城白日曛。","櫪上驊騮嘶鼓角，门前老將識风云。","旌旗四面寒山暎，絲管千家静夜闻。","誰道古来多簡冊，功臣唯有衛將軍。"]', '诗', 'shi', '', NULL, '上將行 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de8243b7-914e-404a-afe4-4a4fd5dc03c3', '許下書情寄張韓二舍人', '許下书情寄張韓二舍人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["謫宦軍城老更悲，近來頻夜夢丹墀。","銀杯乍滅心中火，金鑷唯多鬢上絲。","繞院綠苔聞雁處，滿庭黃葉閉門時。","故人高步雲衢上，肯念前程杳未期。"]', '["謫宦軍城老更悲，近来頻夜梦丹墀。","銀杯乍滅心中火，金鑷唯多鬢上絲。","繞院綠苔闻雁处，满庭黄葉閉门时。","故人高步云衢上，肯念前程杳未期。"]', '诗', 'shi', '', NULL, '許下書情寄張韓二舍人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38df8395-ef69-4307-8625-1b8b115699f6', '九日', '九日', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["重陽寒寺滿秋梧，客在南樓顧老夫。","步蹇強登遊藻井，髮稀那更插茱萸。","橫空過雨千峰出，大野新霜萬葉枯。","更望尊中菊花酒，殷勤能得幾回沽。"]', '["重陽寒寺满秋梧，客在南楼顧老夫。","步蹇強登游藻井，髮稀那更插茱萸。","橫空過雨千峰出，大野新霜万葉枯。","更望尊中菊花酒，殷勤能得幾回沽。"]', '诗', 'shi', '', NULL, '九日 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa4996bf-9c69-42a4-a2be-9080ee3646bb', '送大谷高少府', '送大谷高少府', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["縣屬幷州北近胡，悠悠此別宦仍孤。","應知史筆思循吏，莫料轅門笑魯儒。","古塞草青宜牧馬，春城月暗好啼烏。","彫殘貴有親仁術，梅福何須去隱吳。"]', '["縣屬幷州北近胡，悠悠此別宦仍孤。","應知史笔思循吏，莫料轅门笑魯儒。","古塞草青宜牧马，春城月暗好啼烏。","彫殘貴有親仁術，梅福何須去隐吳。"]', '诗', 'shi', '', NULL, '送大谷高少府 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0aae2c5-e767-4de5-b119-6c9e7c8e6288', '同李端春望', '同李端春望', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["二毛羇旅尚迷津，萬井鶯花雨後春。","宮闕參差當晚日，山河迤邐靜纖塵。","和風醉裏承恩客，芳草歸時失意人。","南北東西各自去，年年依舊物華新。"]', '["二毛羇旅尚迷津，万井鶯花雨後春。","宮闕參差當晚日，山河迤邐静纖塵。","和风醉裏承恩客，芳草归时失意人。","南北东西各自去，年年依旧物华新。"]', '诗', 'shi', '', NULL, '同李端春望 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c5a426-d42a-4f80-9971-9ded9328b779', '嶽祠送薛近貶官', '嶽祠送薛近貶官', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["枯松老柏仙山下，白帝祠堂枕古逵。","遷客無辜祝史告，神明有喜女巫知。","遙思桂浦人空去，遠過衡陽雁不隨。","度嶺梅花翻向北，回看不見樹南枝。"]', '["枯松老柏仙山下，白帝祠堂枕古逵。","遷客無辜祝史告，神明有喜女巫知。","遙思桂浦人空去，远過衡陽雁不隨。","度嶺梅花翻向北，回看不见樹南枝。"]', '诗', 'shi', '', NULL, '嶽祠送薛近貶官 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331b3fff-8815-486a-9bf4-545ecb0774dd', '送友人遊江南', '送友人游江南', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["遠別悠悠白髮新，江潭何處是通津。","潮聲偏懼初來客，海味唯甘久住人。","漠漠煙光前浦晚，青青草色定山春。","汀洲更有南迴雁，亂起聯翩北向秦。"]', '["远別悠悠白髮新，江潭何处是通津。","潮声偏懼初来客，海味唯甘久住人。","漠漠煙光前浦晚，青青草色定山春。","汀洲更有南迴雁，亂起聯翩北向秦。"]', '诗', 'shi', '', NULL, '送友人遊江南 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a233c8e0-8e9e-4790-a0b9-1aeaffe5de2d', '長門怨', '长门怨', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["聞道昭陽宴，嚬蛾落葉中。","清歌逐寒月，遙夜入深宮。"]', '["闻道昭陽宴，嚬蛾落葉中。","清歌逐寒月，遙夜入深宮。"]', '诗', 'shi', '', NULL, '長門怨 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560558a6-9d96-4417-bf46-2a59bc451167', '秋日', '秋日', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["反照入閭巷，憂來與誰語。","古道無人行，秋風動禾黍。"]', '["反照入閭巷，憂来與誰語。","古道無人行，秋风动禾黍。"]', '诗', 'shi', '', NULL, '秋日 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aedcdc5-251d-452f-973a-9bdfa441bd2f', '秋夜', '秋夜', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["高秋夜分後，遠客雁來時。","寂寞重門掩，無人問所思。"]', '["高秋夜分後，远客雁来时。","寂寞重门掩，無人问所思。"]', '诗', 'shi', '', NULL, '秋夜 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9424647-f65f-4a67-9ac7-5e266d7510bc', '慈恩寺殘春', '慈恩寺殘春', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["雙林花已盡，葉色占殘芳。","若問同遊客，高年最斷腸。"]', '["雙林花已尽，葉色占殘芳。","若问同游客，高年最斷腸。"]', '诗', 'shi', '', NULL, '慈恩寺殘春 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33e9b1b3-6644-4366-8671-c763585e6fd6', '早次眉縣界', '早次眉縣界', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["匹馬曉路歸，悠悠渭川道。","晴山向孤城，秋日滿白草。"]', '["匹马晓路归，悠悠渭川道。","晴山向孤城，秋日满白草。"]', '诗', 'shi', '', NULL, '早次眉縣界 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be95f769-211b-4e8b-a1fe-9c2f6e99f613', '路傍墓', '路傍墓', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["石馬雙雙當古樹，不知何代公侯墓。","墓前靡靡春草深，唯有行人看碑路。"]', '["石马雙雙當古樹，不知何代公侯墓。","墓前靡靡春草深，唯有行人看碑路。"]', '诗', 'shi', '', NULL, '路傍墓 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b56280e-9c60-40db-acd2-83cb689eceda', '代園中老人', '代园中老人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["傭賃難堪一身老，皤皤力役在青春。","林園手種唯吾事，桃李成陰歸別人。"]', '["傭賃难堪一身老，皤皤力役在青春。","林园手種唯吾事，桃李成陰归別人。"]', '诗', 'shi', '', NULL, '代園中老人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c8ba39-a67c-435f-ab56-48667c25a85b', '古意', '古意', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["雖言千騎上頭居，一世生離恨有餘。","葉下綺窗銀燭冷，含啼自草錦中書。"]', '["雖言千騎上头居，一世生離恨有餘。","葉下綺窗銀燭冷，含啼自草錦中书。"]', '诗', 'shi', '', NULL, '古意 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6e42084-08d8-44c4-9919-1e5d10dc1fb9', '涼州詞', '涼州词', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["國使翻翻隨斾旌，隴西岐路足荒城。","氈裘牧馬胡雛小，日暮蕃歌三兩聲。"]', '["国使翻翻隨斾旌，隴西岐路足荒城。","氈裘牧马胡雛小，日暮蕃歌三兩声。"]', '诗', 'shi', '', NULL, '涼州詞 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39470e42-9a99-4d04-bd7a-227124373888', '安邑王校書居', '安邑王校书居', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["秋來池館清，夜聞宮漏聲。","迢遰玉山迥，泛灧銀河傾。","琴上松風至，窗裏竹煙生。","多君不家食，孰云事巖耕。"]', '["秋来池館清，夜闻宮漏声。","迢遰玉山迥，泛灧銀河傾。","琴上松风至，窗裏竹煙生。","多君不家食，孰云事巖耕。"]', '诗', 'shi', '', NULL, '安邑王校書居 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a89dd426-d770-4203-87c8-544a6cdb5023', '登總持寺閣', '登總持寺閣', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["今日登高閣，三休忽自悲。","因知筋力減，不及徃年時。","草樹還如舊，山河亦在茲。","龍鍾兼老病，更有重來期。"]', '["今日登高閣，三休忽自悲。","因知筋力減，不及徃年时。","草樹還如旧，山河亦在茲。","龙鍾兼老病，更有重来期。"]', '诗', 'shi', '', NULL, '登總持寺閣 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe96e9b8-e190-46bb-b402-108c8b9342f0', '寄錢起', '寄錢起', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["草長花落樹，羸病強尋春。","無復少年意，空餘華髮新。","青原高見水，白社靜逢人。","寄謝南宮客，軒車不見親。"]', '["草长花落樹，羸病強尋春。","無复少年意，空餘华髮新。","青原高见水，白社静逢人。","寄謝南宮客，軒车不见親。"]', '诗', 'shi', '', NULL, '寄錢起 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('845c5b71-0554-4e28-9333-3a4921d81bfe', '宿青龍寺故曇上人院', '宿青龙寺故曇上人院', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["年深宮院在，閒客自相逢。","閉戶臨寒竹，無人有夜鐘。","降龍今已去，巢鶴竟何從。","坐見繁星曉，淒涼識舊峯。"]', '["年深宮院在，閒客自相逢。","閉戶臨寒竹，無人有夜鐘。","降龙今已去，巢鹤竟何從。","坐见繁星晓，淒涼識旧峯。"]', '诗', 'shi', '', NULL, '宿青龍寺故曇上人院 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870032c5-1d66-42d1-8614-3d470b63e8d2', '新蟬', '新蟬', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["今朝蟬忽鳴，遷客若爲情。","便覺一年謝，能令萬感生。","微風方滿樹，落日稍沈城。","爲問同懷者，淒涼聽幾聲。"]', '["今朝蟬忽鳴，遷客若爲情。","便覺一年謝，能令万感生。","微风方满樹，落日稍沈城。","爲问同懷者，淒涼听幾声。"]', '诗', 'shi', '', NULL, '新蟬 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66711c88-d15e-4440-a51c-03447a294dee', '秋中雨田園即事', '秋中雨田园即事', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["漠漠重雲暗，蕭蕭密雨垂。","爲霖淹古道，積日滿荒陂。","五稼何時穫，孤村幾戶炊。","亂流發通圃，腐葉著秋枝。","暮爨新樵溼，晨漁舊浦移。","空餘去年菊，花發在東籬。"]', '["漠漠重云暗，蕭蕭密雨垂。","爲霖淹古道，積日满荒陂。","五稼何时穫，孤村幾戶炊。","亂流發通圃，腐葉著秋枝。","暮爨新樵溼，晨漁旧浦移。","空餘去年菊，花發在东籬。"]', '诗', 'shi', '', NULL, '秋中雨田園即事 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5809c93-7c03-458e-b028-7c5f765c2302', '拜新月', '拜新月', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["開簾見新月，便即下堦拜。","細語人不聞，北風吹裙帶。"]', '["开簾见新月，便即下堦拜。","細語人不闻，北风吹裙带。"]', '诗', 'shi', '', NULL, '拜新月 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a1a8f4-406e-47d3-af0a-f5448c5db710', '客行贈人', '客行贈人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["旅行雖別路，日暮各思歸。","欲下今朝淚，知君亦溼衣。"]', '["旅行雖別路，日暮各思归。","欲下今朝泪，知君亦溼衣。"]', '诗', 'shi', '', NULL, '客行贈人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc193afd-aca5-403b-82ce-a34e4ef281e1', '贈山老人', '贈山老人', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["白首獨一身，青山爲四隣。","雖行故鄉陌，不見故鄉人。"]', '["白首独一身，青山爲四隣。","雖行故乡陌，不见故乡人。"]', '诗', 'shi', '', NULL, '贈山老人 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8043b134-3787-4442-8fe3-0144fd04131c', '贈胡居士', '贈胡居士', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["孔融過五十，海內故人稀。","相府恩猶在，知君未拂衣。"]', '["孔融過五十，海內故人稀。","相府恩猶在，知君未拂衣。"]', '诗', 'shi', '', NULL, '贈胡居士 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f768442-2cad-4923-923f-bfdd106c78ea', '薦福寺送元偉', '薦福寺送元偉', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["送客攀花後，尋僧坐竹時。","明朝莫回望，青草馬行遲。"]', '["送客攀花後，尋僧坐竹时。","明朝莫回望，青草马行遲。"]', '诗', 'shi', '', NULL, '薦福寺送元偉 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a81ecdd4-5048-464a-b30d-c10cc513ae0a', '觀鄰老栽松', '观鄰老栽松', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["雖過老人宅，不解老人心。","何事斜陽裏，栽松欲待陰。"]', '["雖過老人宅，不解老人心。","何事斜陽裏，栽松欲待陰。"]', '诗', 'shi', '', NULL, '觀鄰老栽松 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a7cf7e6-88c9-48cf-8dee-3a39a0c86e67', '哭麴象', '哭麴象', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["憶昨秋風起，君曾歎逐臣。","何言芳草日，自作九泉人。"]', '["憶昨秋风起，君曾歎逐臣。","何言芳草日，自作九泉人。"]', '诗', 'shi', '', NULL, '哭麴象 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bcfa793-8eb9-4674-ab30-ce209f6086ee', '哭苗垂', '哭苗垂', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["舊友無由見，孤墳草欲長。","月斜鄰笛盡，車馬出山陽。"]', '["旧友無由见，孤墳草欲长。","月斜鄰笛尽，车马出山陽。"]', '诗', 'shi', '', NULL, '哭苗垂 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af2d4cd-7f0c-4fcf-8046-21b75d174476', '題雲際寺故僧院', '題云際寺故僧院', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["白髮悤悤色，青山草草心。","遠公仍下世，從此別東林。"]', '["白髮悤悤色，青山草草心。","远公仍下世，從此別东林。"]', '诗', 'shi', '', NULL, '題雲際寺故僧院 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80966406-a627-47c7-93de-73f21d95baa0', '句', '句', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["高樹多涼吹，疎蟬足斷聲。"]', '["高樹多涼吹，疎蟬足斷声。"]', '诗', 'shi', '', NULL, '句 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b180804b-8079-4cf7-92f6-025638e2fd76', '塞下曲 一', '塞下曲 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["慘慘寒日沒，北風卷蓬根。","將軍領疲兵，却入古塞門。","回頭指陰山，殺氣成黃雲。"]', '["慘慘寒日沒，北风卷蓬根。","將軍領疲兵，却入古塞门。","回头指陰山，殺氣成黄云。"]', '诗', 'shi', '', NULL, '塞下曲 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba5c708-7802-4268-8581-078afa37f3e6', '塞下曲 二', '塞下曲 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["上山望胡兵，胡馬馳驟速。","黃河冰已合，意又向南牧。","嫖姚夜出軍，霜雪割人肉。"]', '["上山望胡兵，胡马驰驟速。","黄河冰已合，意又向南牧。","嫖姚夜出軍，霜雪割人肉。"]', '诗', 'shi', '', NULL, '塞下曲 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e8b58fe-34f3-4856-a670-b919ca7f50f0', '塞下曲 三', '塞下曲 三', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["塞北無草木，烏鳶巢僵屍。","泱渀沙漠空，終日胡風吹。","戰卒多苦辛，苦辛無四時。"]', '["塞北無草木，烏鳶巢僵屍。","泱渀沙漠空，終日胡风吹。","戰卒多苦辛，苦辛無四时。"]', '诗', 'shi', '', NULL, '塞下曲 三 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70156f7d-313f-4ac0-9091-6abbd2c78aa5', '塞下曲 四', '塞下曲 四', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["晚渡西海西，向東看日沒。","傍岸砂礫堆，半和戰兵骨。","單于竟未滅，陰氣常勃勃。"]', '["晚渡西海西，向东看日沒。","傍岸砂礫堆，半和戰兵骨。","單于竟未滅，陰氣常勃勃。"]', '诗', 'shi', '', NULL, '塞下曲 四 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d357d2-5678-4f6b-ae2e-940fea6f13b9', '塞下曲 五', '塞下曲 五', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["城上畫角哀，即知兵心苦。","試問左右人，無言淚如雨。","何意休明時，終年事鼙鼓。"]', '["城上畫角哀，即知兵心苦。","試问左右人，無言泪如雨。","何意休明时，終年事鼙鼓。"]', '诗', 'shi', '', NULL, '塞下曲 五 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3adbd56c-6ec1-4cc4-b9a5-7bcb8a9abe30', '塞下曲 六', '塞下曲 六', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["北風凋白草，胡馬日駸駸。","夜後戍樓月，秋來邊將心。","鐵衣霜露重，戰馬歲年深。","自有盧龍塞，煙塵飛至今。"]', '["北风凋白草，胡马日駸駸。","夜後戍楼月，秋来邊將心。","鐵衣霜露重，戰马歲年深。","自有盧龙塞，煙塵飞至今。"]', '诗', 'shi', '', NULL, '塞下曲 六 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac81bbb8-0470-4fd2-895f-012474058a1a', '苦哉行五首 一', '苦哉行五首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["彼鼠侵我廚，縱貍授粱肉。","鼠雖爲君却，貍食自須足。","冀雪大國恥，翻是大國辱。","羶腥逼綺羅，磚瓦雜珠玉。","登樓非騁望，目笑是心哭。","何意天樂中，至今奏胡曲。"]', '["彼鼠侵我廚，縱貍授粱肉。","鼠雖爲君却，貍食自須足。","冀雪大国恥，翻是大国辱。","羶腥逼綺羅，磚瓦杂珠玉。","登楼非騁望，目笑是心哭。","何意天乐中，至今奏胡曲。"]', '诗', 'shi', '', NULL, '苦哉行五首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7b01a4-e877-45cd-afd8-4c65e212b39e', '苦哉行五首 二', '苦哉行五首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["官軍收洛陽，家住洛陽里。","夫壻與兄弟，目前見傷死。","吞聲不許哭，還遣衣羅綺。","上馬隨匈奴，數秋黃塵裏。","生爲名家女，死作塞垣鬼。","鄉國無還期，天津哭流水。"]', '["官軍收洛陽，家住洛陽里。","夫壻與兄弟，目前见傷死。","吞声不許哭，還遣衣羅綺。","上马隨匈奴，數秋黄塵裏。","生爲名家女，死作塞垣鬼。","乡国無還期，天津哭流水。"]', '诗', 'shi', '', NULL, '苦哉行五首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b384aaa-49e7-46c3-a17e-6c1e2b562868', '苦哉行五首 三', '苦哉行五首 三', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["登樓望天衢，目極淚盈睫。","彊笑無笑容，須妝舊花靨。","昔年買奴僕，奴僕來碎葉。","豈意未死間，自爲匈奴妾。","一生忽至此，萬事痛苦業。","得出塞垣飛，不如彼蜂蝶。"]', '["登楼望天衢，目極泪盈睫。","彊笑無笑容，須妝旧花靨。","昔年買奴僕，奴僕来碎葉。","豈意未死间，自爲匈奴妾。","一生忽至此，万事痛苦業。","得出塞垣飞，不如彼蜂蝶。"]', '诗', 'shi', '', NULL, '苦哉行五首 三 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d4ae998-4e4a-4554-a3b8-55cd9b756d5e', '苦哉行五首 四', '苦哉行五首 四', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["妾家清河邊，七葉承貂蟬。","身爲最小女，偏得渾家憐。","親戚不相識，幽閨十五年。","有時最遠出，秪到中門前。","前年狂胡來，懼死翻生全。","今秋官軍至，豈意遭戈鋋。","匈奴爲先鋒，長鼻黃髮拳。","彎弓獵生人，百步牛羊羶。","脫身落虎口，不及歸黃泉。","苦哉難重陳，暗哭蒼蒼天。"]', '["妾家清河邊，七葉承貂蟬。","身爲最小女，偏得渾家怜。","親戚不相識，幽閨十五年。","有时最远出，秪到中门前。","前年狂胡来，懼死翻生全。","今秋官軍至，豈意遭戈鋋。","匈奴爲先鋒，长鼻黄髮拳。","彎弓獵生人，百步牛羊羶。","脫身落虎口，不及归黄泉。","苦哉难重陳，暗哭蒼蒼天。"]', '诗', 'shi', '', NULL, '苦哉行五首 四 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8440d356-95c9-481f-ac60-e6dc2dba444a', '苦哉行五首 五', '苦哉行五首 五', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["可汗奉親詔，今月歸燕山。","忽如亂刀劒，攪妾心腸間。","出戶望北荒，迢迢玉門關。","生人爲死別，有去無時還。","漢月割妾心，胡風凋妾顏。","去去斷絕魂，呌天天不聞。"]', '["可汗奉親詔，今月归燕山。","忽如亂刀劒，攪妾心腸间。","出戶望北荒，迢迢玉门关。","生人爲死別，有去無时還。","漢月割妾心，胡风凋妾顏。","去去斷絕魂，呌天天不闻。"]', '诗', 'shi', '', NULL, '苦哉行五首 五 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a71077aa-b5b4-4c46-b426-3219e253958d', '苦辛行', '苦辛行', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["且莫奏短歌，聽余苦辛詞。","如今刀筆士，不及屠沽兒。","少年無事學詩賦，豈意文章復相悞。","東西南北少知音，終年竟歲悲行路。","仰面訴天天不聞，低頭告地地不言。","天地生我尚如此，陌上他人何足論。","誰謂西江深，涉之固無憂。","誰謂南山高，可以登之遊。","險巇唯有世間路，一晌令人堪白頭。","貴人立意不可測，等閑桃李成荆棘。","風塵之士深可親，心如雞犬能依人。","悲來却憶漢天子，不棄相如家舊貧。","勸君且飲酒，酒能散羇愁。","誰家有酒判一醉，萬事從他江水流。"]', '["且莫奏短歌，听余苦辛词。","如今刀笔士，不及屠沽兒。","少年無事学诗賦，豈意文章复相悞。","东西南北少知音，終年竟歲悲行路。","仰面訴天天不闻，低头告地地不言。","天地生我尚如此，陌上他人何足論。","誰謂西江深，涉之固無憂。","誰謂南山高，可以登之游。","險巇唯有世间路，一晌令人堪白头。","貴人立意不可測，等闲桃李成荆棘。","风塵之士深可親，心如雞犬能依人。","悲来却憶漢天子，不棄相如家旧貧。","勸君且饮酒，酒能散羇愁。","誰家有酒判一醉，万事從他江水流。"]', '诗', 'shi', '', NULL, '苦辛行 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16cc1ffb-7a18-4903-ab86-35931a9c9620', '長安秋夕', '长安秋夕', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["八月更漏長，愁人起常早。","閉門寂無事，滿院生秋草。","昨宵西窗夢，夢入荆南道。","遠客歸去來，在家貧亦好。"]', '["八月更漏长，愁人起常早。","閉门寂無事，满院生秋草。","昨宵西窗梦，梦入荆南道。","远客归去来，在家貧亦好。"]', '诗', 'shi', '', NULL, '長安秋夕 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a61610-8bbd-4df6-9406-883d3a05f1a9', '羅江客舍', '羅江客舍', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["山縣秋雲闇，茅亭暮雨寒。","自傷庭葉下，誰問客衣單。","有興時添酒，無聊嬾整冠。","近來鄉國夢，夜夜到長安。"]', '["山縣秋云闇，茅亭暮雨寒。","自傷庭葉下，誰问客衣單。","有兴时添酒，無聊嬾整冠。","近来乡国梦，夜夜到长安。"]', '诗', 'shi', '', NULL, '羅江客舍 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b563a63-b88a-4af9-99f8-d1840f235ce9', '贈岑郎中', '贈岑郎中', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["童年未解讀書時，誦得郎中數首詩。","四海煙塵猶隔闊，十年魂夢每相隨。","雖披雲霧逢迎疾，已恨趨風拜德遲。","天下無人鑒詩句，不尋詩伯重尋誰。"]', '["童年未解读书时，誦得郎中數首诗。","四海煙塵猶隔闊，十年魂梦每相隨。","雖披云霧逢迎疾，已恨趨风拜德遲。","天下無人鑒诗句，不尋诗伯重尋誰。"]', '诗', 'shi', '', NULL, '贈岑郎中 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3270b9ea-88f8-4ee0-a1e2-f02c3ba7d133', '聞笛', '闻笛', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["入夜思歸切，笛聲清更哀。","愁人不願聽，自到枕前來。","風起寒雲斷，夜深關月開。","平明獨惆悵，飛盡一庭梅。"]', '["入夜思归切，笛声清更哀。","愁人不願听，自到枕前来。","风起寒云斷，夜深关月开。","平明独惆悵，飞尽一庭梅。"]', '诗', 'shi', '', NULL, '聞笛 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8bc386-6894-4e72-a15a-5ac5fe6776eb', '漢上題韋氏莊', '漢上題韋氏莊', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["結茅同楚客，卜築漢江邊。","日落數歸鳥，夜深聞扣舷。","水痕侵岸柳，山翠借廚煙。","調笑提筐婦，春來蠶幾眠。"]', '["結茅同楚客，卜築漢江邊。","日落數归鸟，夜深闻扣舷。","水痕侵岸柳，山翠借廚煙。","調笑提筐婦，春来蠶幾眠。"]', '诗', 'shi', '', NULL, '漢上題韋氏莊 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e94887-b94b-45a0-951b-ce4ea165c595', '閨情', '閨情', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["側聽宮官說，知君寵尚存。","未能開笑頰，先欲換愁魂。","寶鏡窺妝影，紅衫裛淚痕。","昭陽今再入，寧敢恨長門。"]', '["側听宮官说，知君寵尚存。","未能开笑頰，先欲換愁魂。","寶镜窺妝影，紅衫裛泪痕。","昭陽今再入，寧敢恨长门。"]', '诗', 'shi', '', NULL, '閨情 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e31e980-e209-482d-8c9e-cf49429e366e', '衡陽春日遊僧院', '衡陽春日游僧院', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["曾共劉諮議，同時事道林。","與君相掩淚，來客豈知心。","堦雪凌春積，爐煙向暝深。","依然舊童子，相送出花林。"]', '["曾共劉諮議，同时事道林。","與君相掩泪，来客豈知心。","堦雪凌春積，爐煙向暝深。","依然旧童子，相送出花林。"]', '诗', 'shi', '', NULL, '衡陽春日遊僧院 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6032a2-4092-4d6b-befc-15119bdaebff', '玉臺體題湖上亭', '玉台體題湖上亭', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["湖入縣西邊，湖頭勝事偏。","綠竿初長笋，紅顆未開蓮。","蔽日高高樹，迎人小小船。","清風長入坐，夏月似秋天。"]', '["湖入縣西邊，湖头勝事偏。","綠竿初长笋，紅顆未开蓮。","蔽日高高樹，迎人小小船。","清风长入坐，夏月似秋天。"]', '诗', 'shi', '', NULL, '玉臺體題湖上亭 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f10c2ed6-1350-49fb-83e1-c2b6bcea8a02', '早梅', '早梅', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["一樹寒梅白玉條，迥臨村路傍溪橋。","應緣近水花先發，疑是經春雪未銷。"]', '["一樹寒梅白玉條，迥臨村路傍溪橋。","應緣近水花先發，疑是經春雪未銷。"]', '诗', 'shi', '', NULL, '早梅 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530667a7-76e4-49d1-83ac-50db8627d38a', '移家別湖上亭', '移家別湖上亭', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["好是春風湖上亭，柳條藤蔓繫離情。","黃鶯久住渾相識，欲別頻啼四五聲。"]', '["好是春风湖上亭，柳條藤蔓繫離情。","黄鶯久住渾相識，欲別頻啼四五声。"]', '诗', 'shi', '', NULL, '移家別湖上亭 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db7b46aa-a21b-48b6-a313-76af04709e52', '客堂秋夕', '客堂秋夕', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["隔窗螢影滅復流，北風微雨虛堂秋。","蟲聲竟夜引鄉淚，蟋蟀何自知人愁。","四時不得一日樂，以此方悲客遊惡。","寂寂江城無所聞，梧桐葉上偏蕭索。"]', '["隔窗螢影滅复流，北风微雨虛堂秋。","蟲声竟夜引乡泪，蟋蟀何自知人愁。","四时不得一日乐，以此方悲客游惡。","寂寂江城無所闻，梧桐葉上偏蕭索。"]', '诗', 'shi', '', NULL, '客堂秋夕 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99bfd98c-9520-4064-b151-3390901fbe59', '湖南雪中留別', '湖南雪中留別', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["草草還草草，湖東別離早。","何處愁殺人，歸鞍雪中道。","出門迷轍跡，雲水白浩浩。","明日武陵西，相思鬢堪老。"]', '["草草還草草，湖东別離早。","何处愁殺人，归鞍雪中道。","出门迷轍跡，云水白浩浩。","明日武陵西，相思鬢堪老。"]', '诗', 'shi', '', NULL, '湖南雪中留別 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a74e95-00c2-4dce-a38e-6a4ec4a8923d', '贈別張駙馬', '贈別張駙马', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["上元年中長安陌，見君朝下欲歸宅。","飛龍騎馬三十匹，玉勒雕鞍照初日。","數里衣香遙撲人，長衢雨歇無纖塵。","從奴斜抱勑賜錦，雙雙蹙出金麒麟。","天子愛壻皇后弟，獨步明時負權勢。","一身扈蹕承殊澤，甲第朱門聳高戟。","鳳凰樓上伴吹簫，鸚鵡杯中醉留客。","泰去否來何足論，宮中晏駕人事翻。","一朝負譴辭丹闕，五年待罪湘江源。","冠冕淒涼幾遷改，眼看桑田變成海。","華堂金屋別賜人，細眼黃頭總何在。","渚宮相見寸心悲，嬾欲今時問昔時。","看君風骨殊未歇，不用愁來雙淚垂。"]', '["上元年中长安陌，见君朝下欲归宅。","飞龙騎马三十匹，玉勒雕鞍照初日。","數里衣香遙撲人，长衢雨歇無纖塵。","從奴斜抱勑賜錦，雙雙蹙出金麒麟。","天子愛壻皇后弟，独步明时負權勢。","一身扈蹕承殊澤，甲第朱门聳高戟。","鳳凰楼上伴吹簫，鸚鵡杯中醉留客。","泰去否来何足論，宮中晏駕人事翻。","一朝負譴辞丹闕，五年待罪湘江源。","冠冕淒涼幾遷改，眼看桑田变成海。","华堂金屋別賜人，細眼黄头總何在。","渚宮相见寸心悲，嬾欲今时问昔时。","看君风骨殊未歇，不用愁来雙泪垂。"]', '诗', 'shi', '', NULL, '贈別張駙馬 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9bdd400-a18e-4a57-b9ee-602eddfbaabe', '涇州觀元戎出師', '涇州观元戎出師', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["寒日征西將，蕭蕭萬馬叢。","吹笳覆樓雪，祝纛滿旗風。","遮虜黃雲斷，燒羌白草空。","金鐃肅天外，玉帳靜霜中。","朔野長城閉，河源舊路通。","衛青師自老，魏絳賞何功。","槍壘依沙迥，轅門壓塞雄。","燕然如可勒，萬里願從公。"]', '["寒日征西將，蕭蕭万马叢。","吹笳覆楼雪，祝纛满旗风。","遮虜黄云斷，燒羌白草空。","金鐃肅天外，玉帳静霜中。","朔野长城閉，河源旧路通。","衛青師自老，魏絳賞何功。","槍壘依沙迥，轅门壓塞雄。","燕然如可勒，万里願從公。"]', '诗', 'shi', '', NULL, '涇州觀元戎出師 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f82c2ab-c614-4a30-808a-450b07c8aa12', '從軍行', '從軍行', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["昔從李都尉，雙鞬照馬蹄。","擒生黑山北，殺敵黃雲西。","太白沈虜地，邊草復萋萋。","歸來邯鄲市，百尺青樓梯。","感激然諾重，平生膽力齊。","芳筵暮歌發，豔粉輕鬟低。","半酣秋風起，鐵騎門前嘶。","遠戍報烽火，孤城嚴鼓鼙。","揮鞭望塵去，少婦莫含啼。"]', '["昔從李都尉，雙鞬照马蹄。","擒生黑山北，殺敵黄云西。","太白沈虜地，邊草复萋萋。","归来邯鄲市，百尺青楼梯。","感激然諾重，平生膽力齊。","芳筵暮歌發，豔粉轻鬟低。","半酣秋风起，鐵騎门前嘶。","远戍報烽火，孤城嚴鼓鼙。","揮鞭望塵去，少婦莫含啼。"]', '诗', 'shi', '', NULL, '從軍行 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3f1593-4234-4d3e-8c4b-3c870e9c85cd', '古意', '古意', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["女伴朝來說，知君欲棄捐。","嬾梳明鏡下，羞到畫堂前。","有淚霑脂粉，無情理管弦。","不知將巧笑，更遣向誰憐。"]', '["女伴朝来说，知君欲棄捐。","嬾梳明镜下，羞到畫堂前。","有泪霑脂粉，無情理管弦。","不知將巧笑，更遣向誰怜。"]', '诗', 'shi', '', NULL, '古意 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bfe73b3-605e-4e42-9e57-49ad2696f716', '聽杜山人彈胡笳', '听杜山人彈胡笳', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["綠琴胡笳誰妙彈，山人杜陵名庭蘭。","杜君少與山人友，山人沒來今已久。","當時海內求知音，囑付胡笳入君手。","杜陵攻琴四十年，琴聲在音不在弦。","座中爲我奏此曲，滿堂蕭飋如窮邊。","第一第二拍，淚盡蛾眉沒蕃客。","更聞出塞入塞聲，穹廬氈帳難爲情。","胡天雨雪四時下，五月不曾芳草生。","須臾促軫變宮徵，一聲悲兮一聲喜。","南看漢月雙眼明，却顧胡兒寸心死。","迴鶻數年收洛陽，洛陽士女皆驅將。","豈無父母與兄弟，聞此哀情皆斷腸。","杜陵先生證此道，沈家祝家皆絕倒。","如今世上雅風衰，若箇深知此聲好。","世上愛箏不愛琴，則明此調難知音。","今朝促軫爲君奏，不向俗流傳此心。"]', '["綠琴胡笳誰妙彈，山人杜陵名庭蘭。","杜君少與山人友，山人沒来今已久。","當时海內求知音，囑付胡笳入君手。","杜陵攻琴四十年，琴声在音不在弦。","座中爲我奏此曲，满堂蕭飋如窮邊。","第一第二拍，泪尽蛾眉沒蕃客。","更闻出塞入塞声，穹廬氈帳难爲情。","胡天雨雪四时下，五月不曾芳草生。","須臾促軫变宮徵，一声悲兮一声喜。","南看漢月雙眼明，却顧胡兒寸心死。","迴鶻數年收洛陽，洛陽士女皆驱將。","豈無父母與兄弟，闻此哀情皆斷腸。","杜陵先生證此道，沈家祝家皆絕倒。","如今世上雅风衰，若箇深知此声好。","世上愛箏不愛琴，則明此調难知音。","今朝促軫爲君奏，不向俗流傳此心。"]', '诗', 'shi', '', NULL, '聽杜山人彈胡笳 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd16e4cc-0d3d-4994-8d40-6bbdc4876a01', '詠史', '詠史', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["漢家青史上，計拙是和親。","社稷依明主，安危託婦人。","豈能將玉貌，便擬靜胡塵。","地下千年骨，誰爲輔佐臣。"]', '["漢家青史上，計拙是和親。","社稷依明主，安危託婦人。","豈能將玉貌，便擬静胡塵。","地下千年骨，誰爲輔佐臣。"]', '诗', 'shi', '', NULL, '詠史 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7f1998-5bf1-4c13-b713-5c1b6deef5c3', '桂州臘夜', '桂州臘夜', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["坐到三更盡，歸仍萬里賒。","雪聲偏傍竹，寒夢不離家。","曉角分殘漏，孤燈落碎花。","二年隨驃騎，辛苦向天涯。"]', '["坐到三更尽，归仍万里賒。","雪声偏傍竹，寒梦不離家。","晓角分殘漏，孤灯落碎花。","二年隨驃騎，辛苦向天涯。"]', '诗', 'shi', '', NULL, '桂州臘夜 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d3e19e-4980-4ebe-9bfe-f20fecc160d6', '再赴桂州先寄李大夫', '再赴桂州先寄李大夫', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["玷玉甘長棄，朱門喜再遊。","過因纔後重，恩合死前酬。","養驥須憐瘦，栽松莫厭秋。","今朝兩行淚，一半血和流。"]', '["玷玉甘长棄，朱门喜再游。","過因纔後重，恩合死前酬。","養驥須怜瘦，栽松莫厭秋。","今朝兩行泪，一半血和流。"]', '诗', 'shi', '', NULL, '再赴桂州先寄李大夫 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b050513c-bd96-4e75-90b5-1e2f0894e9ec', '題招提寺', '題招提寺', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["招提精舍好，石壁向江開。","山影水中盡，鳥聲天上來。","一燈傳歲月，深院長莓苔。","日暮雙林磬，泠泠送客回。"]', '["招提精舍好，石壁向江开。","山影水中尽，鸟声天上来。","一灯傳歲月，深院长莓苔。","日暮雙林磬，泠泠送客回。"]', '诗', 'shi', '', NULL, '題招提寺 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d815f2-631f-4389-935e-f7054b2552e2', '謫官辰州冬至日[有]懷', '謫官辰州冬至日[有]懷', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["去年長至在長安，策杖曾簪獬豸冠。","此歲長安逢至日，下堦遙想雪霜寒。","夢隨行伍朝天去，身寄窮荒報國難。","北望南郊消息斷，江頭唯有淚闌干。"]', '["去年长至在长安，策杖曾簪獬豸冠。","此歲长安逢至日，下堦遙想雪霜寒。","梦隨行伍朝天去，身寄窮荒報国难。","北望南郊消息斷，江头唯有泪闌干。"]', '诗', 'shi', '', NULL, '謫官辰州冬至日[有]懷 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f4f46e-3f2c-4762-9e90-d4ba21cf18dd', '贈韋況徴君', '贈韋況徴君', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["身欲逃名名自隨，鳳銜丹詔降茅茨。","苦節難違天子命，貞心唯有老松知。","回看藥竈封題密，強入蒲輪引步遲。","今日巢由舊冠帶，聖朝風化勝堯時。"]', '["身欲逃名名自隨，鳳銜丹詔降茅茨。","苦節难違天子命，貞心唯有老松知。","回看藥竈封題密，強入蒲輪引步遲。","今日巢由旧冠带，聖朝风化勝堯时。"]', '诗', 'shi', '', NULL, '贈韋況徴君 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba60883-d111-4b28-a339-b5104acebe25', '送吉州閻使君入道二首 一', '送吉州閻使君入道二首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["聞道桃源去，塵心忽自悲。","余當從宦日，君是棄官時。","金汞封仙骨，靈津嚥玉池。","受傳三籙備，起坐五雲隨。","洞裏花常發，人間鬢易衰。","他年會相訪，莫作爛柯棊。"]', '["闻道桃源去，塵心忽自悲。","余當從宦日，君是棄官时。","金汞封仙骨，靈津嚥玉池。","受傳三籙備，起坐五云隨。","洞裏花常發，人间鬢易衰。","他年會相訪，莫作爛柯棊。"]', '诗', 'shi', '', NULL, '送吉州閻使君入道二首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1a45d7-2c65-48f9-9a1f-00c367958a4f', '送吉州閻使君入道二首 二', '送吉州閻使君入道二首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["廬陵太守近隳官，霞帔初朝五帝壇。","風過鬼神延受籙，夜深龍虎衛燒丹。","冰容入鏡纖埃靜，玉液添缾漱齒寒。","莫遣桃花迷客路，千山萬水訪君難。"]', '["廬陵太守近隳官，霞帔初朝五帝壇。","风過鬼神延受籙，夜深龙虎衛燒丹。","冰容入镜纖埃静，玉液添缾漱齒寒。","莫遣桃花迷客路，千山万水訪君难。"]', '诗', 'shi', '', NULL, '送吉州閻使君入道二首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80bda9d4-0954-4a61-964c-62cb5a890867', '入劒門', '入劒门', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["劒門兵革後，萬事盡堪悲。","鳥鼠無巢穴，兒童話別離。","山川同昔日，荆棘是今時。","征戰何年定，家家有畫旗。"]', '["劒门兵革後，万事尽堪悲。","鸟鼠無巢穴，兒童話別離。","山川同昔日，荆棘是今时。","征戰何年定，家家有畫旗。"]', '诗', 'shi', '', NULL, '入劒門 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55a255c-8b5a-4f5f-959d-31eacbd3289d', '過商山', '過商山', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["雨暗商山過客稀，路傍孤店閉柴扉。","卸鞍良久茅簷下，待得巴人樵採歸。"]', '["雨暗商山過客稀，路傍孤店閉柴扉。","卸鞍良久茅簷下，待得巴人樵採归。"]', '诗', 'shi', '', NULL, '過商山 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81ec803-a9a8-44f3-bc37-b992472ccc27', '閏春宴花溪嚴侍御莊', '閏春宴花溪嚴侍御莊', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["一團青翠色，云是子陵家。","山帶新晴雨，溪留閏月花。","瓶開巾漉酒，地坼筍抽芽。","綵縟承顏面，朝朝賦白華。"]', '["一團青翠色，云是子陵家。","山带新晴雨，溪留閏月花。","瓶开巾漉酒，地坼筍抽芽。","綵縟承顏面，朝朝賦白华。"]', '诗', 'shi', '', NULL, '閏春宴花溪嚴侍御莊 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd745b61-3218-4381-b884-413dbe96bfef', '歲暮客懷', '歲暮客懷', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["異鄉三十口，親老復家貧。","無事乾坤內，虛爲翰墨人。","歲華南去後，愁夢北來頻。","惆悵江邊柳，依依又欲春。"]', '["異乡三十口，親老复家貧。","無事乾坤內，虛爲翰墨人。","歲华南去後，愁梦北来頻。","惆悵江邊柳，依依又欲春。"]', '诗', 'shi', '', NULL, '歲暮客懷 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e70619-c664-4b02-a77d-a81a0282a48f', '秋望興慶宮', '秋望兴慶宮', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["先皇歌舞地，今日未遊巡。","幽咽龍池水，淒涼御榻塵。","隨風秋樹棄，對月老宮人。","萬事如桑海，悲來欲慟神。"]', '["先皇歌舞地，今日未游巡。","幽咽龙池水，淒涼御榻塵。","隨风秋樹棄，对月老宮人。","万事如桑海，悲来欲慟神。"]', '诗', 'shi', '', NULL, '秋望興慶宮 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36116338-f1db-482b-b7bd-a5df09c7e21d', '送鄭鍊師貶辰州', '送鄭鍊師貶辰州', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["辰州萬里外，想得逐臣心。","謫去刑名枉，人間痛惜深。","誤將瑕指玉，遂使謾消金。","計日西歸在，休爲澤畔吟。"]', '["辰州万里外，想得逐臣心。","謫去刑名枉，人间痛惜深。","誤將瑕指玉，遂使謾消金。","計日西归在，休爲澤畔吟。"]', '诗', 'shi', '', NULL, '送鄭鍊師貶辰州 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c246f6-8c50-43a0-b4ad-6a42a6cf6d7e', '雲夢故城秋望', '云梦故城秋望', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["故國遺墟在，登臨想舊遊。","一朝人事變，千載水空流。","夢渚鴻聲晚，荆門樹色秋。","片雲凝不散，遙挂望鄉愁。"]', '["故国遺墟在，登臨想旧游。","一朝人事变，千載水空流。","梦渚鴻声晚，荆门樹色秋。","片云凝不散，遙挂望乡愁。"]', '诗', 'shi', '', NULL, '雲夢故城秋望 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a790de-580a-426a-bd11-fafca4b1d2c7', '秋日感懷', '秋日感懷', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["洛陽岐路信悠悠，無事辭家兩度秋。","日下未馳千里足，天涯徒泛五湖舟。","菏衣半浸緣鄉淚，玉貌潛銷是客愁。","說向長安親與故，誰憐歲晚尚淹留。"]', '["洛陽岐路信悠悠，無事辞家兩度秋。","日下未驰千里足，天涯徒泛五湖舟。","菏衣半浸緣乡泪，玉貌潛銷是客愁。","说向长安親與故，誰怜歲晚尚淹留。"]', '诗', 'shi', '', NULL, '秋日感懷 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e337bde8-dbb3-4bdd-ab74-a54239fd336b', '送王明府入道', '送王明府入道', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["何事陶彭澤，明時又挂冠。","爲耽泉石趣，不憚薜蘿寒。","輕雪籠紗帽，孤猨傍醮壇。","懸懸老松下，金竈夜燒丹。"]', '["何事陶彭澤，明时又挂冠。","爲耽泉石趣，不憚薜蘿寒。","轻雪籠紗帽，孤猨傍醮壇。","懸懸老松下，金竈夜燒丹。"]', '诗', 'shi', '', NULL, '送王明府入道 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a319214b-ef7d-41c4-acbd-348c78de54bf', '秋月', '秋月', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["江干入夜杵聲秋，百尺疎桐挂斗牛。","思苦自看明月苦，人愁不是月華愁。"]', '["江干入夜杵声秋，百尺疎桐挂斗牛。","思苦自看明月苦，人愁不是月华愁。"]', '诗', 'shi', '', NULL, '秋月 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648b7a06-ca8e-44e6-9597-c7d25395b78b', '賦得鐵馬鞭', '賦得鐵马鞭', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["成器雖因匠，懷剛本自天。","爲憐持寸節，長擬靜三邊。","未入英髦用，空存鐵石堅。","希君剖腹取，還解抱龍泉。"]', '["成器雖因匠，懷剛本自天。","爲怜持寸節，长擬静三邊。","未入英髦用，空存鐵石堅。","希君剖腹取，還解抱龙泉。"]', '诗', 'shi', '', NULL, '賦得鐵馬鞭 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f660a6c-8ebf-427c-b772-e1bb7f90b1ed', '聞顔尚書陷賊中', '闻顔尚书陷賊中', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["聞說征南沒，那堪故吏聞。","能持蘇武節，不受馬超勳。","國破無家信，天秋有鴈羣。","同榮不同辱，今日負將軍。"]', '["闻说征南沒，那堪故吏闻。","能持蘇武節，不受马超勳。","国破無家信，天秋有鴈羣。","同榮不同辱，今日負將軍。"]', '诗', 'shi', '', NULL, '聞顔尚書陷賊中 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6c09bc-04e4-487b-b201-43aaf6955c73', '送蘇參軍', '送蘇參軍', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["憶昨青襟醉裏分，酒醒迴首愴離羣。","舟移極浦城初掩，山束長江日早曛。","客來有恨空思德，別後誰人更議文。","常歎蘇生官太屈，應緣才似鮑參軍。"]', '["憶昨青襟醉裏分，酒醒迴首愴離羣。","舟移極浦城初掩，山束长江日早曛。","客来有恨空思德，別後誰人更議文。","常歎蘇生官太屈，應緣才似鲍參軍。"]', '诗', 'shi', '', NULL, '送蘇參軍 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52327ac2-b9b2-42d7-9fe3-4e8e20e96b34', '成都元十八侍御', '成都元十八侍御', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["不見元生已數朝，浣花溪路去菲遙。","客舍早知渾寂寞，交情豈謂更蕭條。","空有寸心思會面，恨無單酌遣相邀。","驊驄幸自能馳驟，何惜揮鞭過柞橋。"]', '["不见元生已數朝，浣花溪路去菲遙。","客舍早知渾寂寞，交情豈謂更蕭條。","空有寸心思會面，恨無單酌遣相邀。","驊驄幸自能驰驟，何惜揮鞭過柞橋。"]', '诗', 'shi', '', NULL, '成都元十八侍御 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d73235b-89f8-4e98-87bc-fe4ce5d21836', '觀衛尚書九日對中使射破的', '观衛尚书九日对中使射破的', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["盛宴傾黃菊，殊私降紫泥。","月營開射圃，霜斾拂晴霓。","出將三朝貴，彎弓五善齊。","腕迴金鏃滿，的破綠弦低。","勇氣干牛斗，歡聲震鼓鼙。","忠臣思報國，更欲取關西。"]', '["盛宴傾黄菊，殊私降紫泥。","月營开射圃，霜斾拂晴霓。","出將三朝貴，彎弓五善齊。","腕迴金鏃满，的破綠弦低。","勇氣干牛斗，歡声震鼓鼙。","忠臣思報国，更欲取关西。"]', '诗', 'shi', '', NULL, '觀衛尚書九日對中使射破的 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('834231ba-8f35-4174-b0e2-673a064b18e1', '辰州聞大駕還宮', '辰州闻大駕還宮', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["聞道鑾輿歸魏闕，望雲西拜喜成悲。","寧知隴水煙銷日，再有園林秋薦時。","渭水戰添亡虜血，秦人生覩舊朝儀。","自慚出守辰州畔，不得親隨日月旗。"]', '["闻道鑾輿归魏闕，望云西拜喜成悲。","寧知隴水煙銷日，再有园林秋薦时。","渭水戰添亡虜血，秦人生覩旧朝儀。","自慚出守辰州畔，不得親隨日月旗。"]', '诗', 'shi', '', NULL, '辰州聞大駕還宮 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017af722-70e2-4bc6-9a67-d27072e97e52', '辰州建中四年多懷', '辰州建中四年多懷', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["荒徼辰陽遠，窮秋瘴雨深。","主恩堪灑血，邊宦更何心。","海上紅旗滿，生前白髮侵。","竹寒寧改節，隼靜早因禽。","務退門多掩，愁來酒獨斟。","天涯憂國淚，無日不霑襟。"]', '["荒徼辰陽远，窮秋瘴雨深。","主恩堪灑血，邊宦更何心。","海上紅旗满，生前白髮侵。","竹寒寧改節，隼静早因禽。","務退门多掩，愁来酒独斟。","天涯憂国泪，無日不霑襟。"]', '诗', 'shi', '', NULL, '辰州建中四年多懷 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476d3cd8-872c-4402-aaaf-1477d6440a41', '上桂州李大夫', '上桂州李大夫', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["今日辭門館，情將衆別殊。","感深翻有淚，仁過曲憐愚。","晚鏡傷秋鬢，晴寒切病驅。","煙霞萬里闊，宇宙一身孤。","倚馬才寧有，登龍意豈無。","唯於方寸內，暗貯報恩珠。"]', '["今日辞门館，情將衆別殊。","感深翻有泪，仁過曲怜愚。","晚镜傷秋鬢，晴寒切病驱。","煙霞万里闊，宇宙一身孤。","倚马才寧有，登龙意豈無。","唯於方寸內，暗貯報恩珠。"]', '诗', 'shi', '', NULL, '上桂州李大夫 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b54515e-310e-4f31-967a-d27da2ba3991', '江城秋霽', '江城秋霽', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["霽後江城風景涼，豈堪登眺只堪傷。","遠天螮蝀收殘雨，映水鸕鷀近夕陽。","萬事無成空過日，十年多難不還鄉。","不知何處銷茲恨，轉覺愁隨夜夜長。"]', '["霽後江城风景涼，豈堪登眺只堪傷。","远天螮蝀收殘雨，映水鸕鷀近夕陽。","万事無成空過日，十年多难不還乡。","不知何处銷茲恨，轉覺愁隨夜夜长。"]', '诗', 'shi', '', NULL, '江城秋霽 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480d7d0b-277f-4ad9-9829-e32b45bca9a7', '上李常侍', '上李常侍', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["旌旗曉過大江西，七校前驅萬隊齊。","千里政聲人共喜，三軍令肅馬前嘶。","恩霑境內風初變，春入城陰柳漸低。","桃李不須令更種，早知門下舊成蹊。"]', '["旌旗晓過大江西，七校前驱万隊齊。","千里政声人共喜，三軍令肅马前嘶。","恩霑境內风初变，春入城陰柳漸低。","桃李不須令更種，早知门下旧成蹊。"]', '诗', 'shi', '', NULL, '上李常侍 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65117882-7972-4508-8f49-8b19e5cf237e', '上湖南崔中丞', '上湖南崔中丞', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["山上青松陌上塵，雲泥豈合得相親。","舉世盡嫌良馬瘦，唯君不棄臥龍貧。","千金未必能移性，一諾從來許殺身。","莫道書生無感激，寸心還是報恩人。"]', '["山上青松陌上塵，云泥豈合得相親。","舉世尽嫌良马瘦，唯君不棄臥龙貧。","千金未必能移性，一諾從来許殺身。","莫道书生無感激，寸心還是報恩人。"]', '诗', 'shi', '', NULL, '上湖南崔中丞 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b72c88d-e4c2-497f-9bba-a37bb3c5060f', '早春雪中', '早春雪中', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["陰雲萬里晝漫漫，愁坐關心事幾般。","爲報春風休下雪，柳條初放不禁寒。"]', '["陰云万里晝漫漫，愁坐关心事幾般。","爲報春风休下雪，柳條初放不禁寒。"]', '诗', 'shi', '', NULL, '早春雪中 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540a0494-c972-4ed4-bae4-8e41cf7ed85e', '雲安阻雨', '云安阻雨', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["日長巴峽雨濛濛，又說歸舟路未通。","遊人不及西江水，先得東流到渚宮。"]', '["日长巴峽雨濛濛，又说归舟路未通。","游人不及西江水，先得东流到渚宮。"]', '诗', 'shi', '', NULL, '雲安阻雨 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f467fbb-f8a3-4376-92e9-92b2f15046f6', '湖南春日二首 一', '湖南春日二首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["自憐春日客長沙，江上無人轉憶家。","光景却添鄉思苦，簷前數片落梅花。"]', '["自怜春日客长沙，江上無人轉憶家。","光景却添乡思苦，簷前數片落梅花。"]', '诗', 'shi', '', NULL, '湖南春日二首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5015a68-8524-4c67-b695-1789956f5084', '湖南春日二首 二', '湖南春日二首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["三湘漂寓若流萍，萬里湘鄉隔洞庭。","羇客春來心欲碎，東風莫遣柳條青。"]', '["三湘漂寓若流萍，万里湘乡隔洞庭。","羇客春来心欲碎，东风莫遣柳條青。"]', '诗', 'shi', '', NULL, '湖南春日二首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d8245b-b88e-4f55-ae81-b876221f74a3', '送陸秀才歸覲省', '送陸秀才归覲省', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["武陵何處在，南指楚雲陰。","花蕚連枝近，桃源去路深。","啼鶯徒寂寂，征馬已駸駸。","隄上千年柳，條條挂我心。"]', '["武陵何处在，南指楚云陰。","花蕚連枝近，桃源去路深。","啼鶯徒寂寂，征马已駸駸。","隄上千年柳，條條挂我心。"]', '诗', 'shi', '', NULL, '送陸秀才歸覲省 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9a1fdf-ecbd-4a7c-9fdd-e492202dc13e', '戲題秋月', '戲題秋月', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["秋宵月色勝春宵，萬里天涯靜寂寥。","近來數夜飛霜重，只畏娑婆樹葉凋。"]', '["秋宵月色勝春宵，万里天涯静寂寥。","近来數夜飞霜重，只畏娑婆樹葉凋。"]', '诗', 'shi', '', NULL, '戲題秋月 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9853bee5-ded5-4d64-8ff6-aec3092a97e2', '宿湘江', '宿湘江', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["九月湘江水漫流，沙邊唯覽月華秋。","金風浦上吹黃葉，一夜紛紛滿客舟。"]', '["九月湘江水漫流，沙邊唯覽月华秋。","金风浦上吹黄葉，一夜紛紛满客舟。"]', '诗', 'shi', '', NULL, '宿湘江 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed106038-327b-4901-afcc-4ce8c1a8786a', '戲贈張使君', '戲贈張使君', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["數載蹉跎罷搢紳，五湖乘興轉迷津。","如今野客無家第，醉處尋常是主人。"]', '["數載蹉跎罷搢紳，五湖乘兴轉迷津。","如今野客無家第，醉处尋常是主人。"]', '诗', 'shi', '', NULL, '戲贈張使君 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a2be6da-b046-4437-81df-897ace4204e9', '別公安賈明府', '別公安賈明府', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["葉縣門前江水深，淺於羇客報恩心。","把君詩卷西歸去，一度相思一度吟。"]', '["葉縣门前江水深，淺於羇客報恩心。","把君诗卷西归去，一度相思一度吟。"]', '诗', 'shi', '', NULL, '別公安賈明府 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01175b7-4cad-4f15-a884-de6089dc08ad', '霽雪', '霽雪', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["風卷寒雲暮雪晴，江煙洗盡柳條輕。","簷前數片無人埽，又得書窗一夜明。"]', '["风卷寒云暮雪晴，江煙洗尽柳條轻。","簷前數片無人埽，又得书窗一夜明。"]', '诗', 'shi', '', NULL, '霽雪 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e519eda-bd1c-4705-982e-b96f19b1a67f', '漢陰弔崔員外墳', '漢陰弔崔員外墳', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["遠別望有歸，葉落望春暉。","所痛泉路人，一去無還期。","荒墳遺漢陰，墳樹啼子規。","存沒抱冤滯，孤魂意何依。","豈無骨肉親，豈無深相知。","曝露不復問，高名亦何爲。","相攜慟君罷，春日空遲遲。"]', '["远別望有归，葉落望春暉。","所痛泉路人，一去無還期。","荒墳遺漢陰，墳樹啼子規。","存沒抱冤滯，孤魂意何依。","豈無骨肉親，豈無深相知。","曝露不复问，高名亦何爲。","相携慟君罷，春日空遲遲。"]', '诗', 'shi', '', NULL, '漢陰弔崔員外墳 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc46994f-0a85-42da-ad16-d0dad680e9cd', '題槿花', '題槿花', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["自用金錢買槿栽，二年方始得花開。","鮮紅未許佳人見，蝴蝶爭知早到來。"]', '["自用金錢買槿栽，二年方始得花开。","鲜紅未許佳人见，蝴蝶爭知早到来。"]', '诗', 'shi', '', NULL, '題槿花 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe1a437-558e-4509-9bd0-fc81f1fb46b0', '題宋玉亭', '題宋玉亭', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["宋玉亭前悲暮秋，陽臺路上雨初收。","應緣此處人多別，松竹蕭蕭也帶愁。"]', '["宋玉亭前悲暮秋，陽台路上雨初收。","應緣此处人多別，松竹蕭蕭也带愁。"]', '诗', 'shi', '', NULL, '題宋玉亭 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e7f084d-492b-4162-9d2d-055ddda51acc', '過東平軍', '過东平軍', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["畫角初鳴殘照微，營營鞍馬往來稀。","相逢士卒皆垂淚，八座朝天何日歸。"]', '["畫角初鳴殘照微，營營鞍马往来稀。","相逢士卒皆垂泪，八座朝天何日归。"]', '诗', 'shi', '', NULL, '過東平軍 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26934fb-899d-4d12-aeec-81f11c5e903f', '送辰州鄭使君', '送辰州鄭使君', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["誰人不譴謫，君去獨堪傷。","長子家無弟，慈親老在堂。","驚魂隨驛吏，冒暑向炎方。","未到猨啼處，參差已斷腸。"]', '["誰人不譴謫，君去独堪傷。","长子家無弟，慈親老在堂。","驚魂隨驛吏，冒暑向炎方。","未到猨啼处，參差已斷腸。"]', '诗', 'shi', '', NULL, '送辰州鄭使君 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76247eb-572b-4fa3-8d38-ab33fe686124', '江上柳送人', '江上柳送人', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["江柳斷腸色，黃絲垂未齊。","人看幾重恨，鳥入一枝低。","鄉淚正堪落，與君又解攜。","相思萬里道，春去夕陽西。"]', '["江柳斷腸色，黄絲垂未齊。","人看幾重恨，鸟入一枝低。","乡泪正堪落，與君又解携。","相思万里道，春去夕陽西。"]', '诗', 'shi', '', NULL, '江上柳送人 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f4ea19c-f164-4395-a71a-ba2b615a5cf1', '湘南曲', '湘南曲', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["虞帝南遊不復還，翠蛾幽怨水雲間。","昨夜月明湘浦宿，閨中珂珮度空山。"]', '["虞帝南游不复還，翠蛾幽怨水云间。","昨夜月明湘浦宿，閨中珂珮度空山。"]', '诗', 'shi', '', NULL, '湘南曲 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f28614a-3847-43c4-beb1-8bdc44216bdf', '桂州西山登高上陸大夫', '桂州西山登高上陸大夫', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["登高上山上，高處更堪愁。","野菊他鄉酒，蘆花滿眼秋。","風煙連楚郡，兄弟客荆州。","早晚朝天去，親隨定遠侯。"]', '["登高上山上，高处更堪愁。","野菊他乡酒，蘆花满眼秋。","风煙連楚郡，兄弟客荆州。","早晚朝天去，親隨定远侯。"]', '诗', 'shi', '', NULL, '桂州西山登高上陸大夫 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6186f655-bfa7-4d7c-89be-aaf4b2bbe0b2', '寄鄭鍊師', '寄鄭鍊師', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["平生金石友，淪落向辰州。","已是二年客，那堪終日愁。","尺書渾不寄，兩鬢計應秋。","今夜相思月，情人南海頭。"]', '["平生金石友，淪落向辰州。","已是二年客，那堪終日愁。","尺书渾不寄，兩鬢計應秋。","今夜相思月，情人南海头。"]', '诗', 'shi', '', NULL, '寄鄭鍊師 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73df0a46-898a-42c3-8563-b4fc8bac935c', '八月十五日', '八月十五日', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["憶昔千秋節，懽娛萬國同。","今來六親遠，此日一悲風。","年少逢胡亂，時平似夢中。","棃園幾人在，應是涕無窮。"]', '["憶昔千秋節，懽娛万国同。","今来六親远，此日一悲风。","年少逢胡亂，时平似梦中。","棃园幾人在，應是涕無窮。"]', '诗', 'shi', '', NULL, '八月十五日 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49dcf3d5-3f07-42cf-9959-b4d9e34f9ee3', '征人歸鄉', '征人归乡', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["三月江城柳絮飛，五年遊客送人歸。","故將別淚和鄉淚，今日闌干濕汝衣。"]', '["三月江城柳絮飞，五年游客送人归。","故將別泪和乡泪，今日闌干濕汝衣。"]', '诗', 'shi', '', NULL, '征人歸鄉 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3bad56f-a627-4c02-8da4-e59b0a9260a4', '駱家亭子納涼', '駱家亭子納涼', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["江湖思渺然，不離國門前。","折葦魚沈藻，攀藤鳥出煙。","生衣宜水竹，小酒入詩篇。","莫怪侵星坐，神清不欲眠。"]', '["江湖思渺然，不離国门前。","折葦鱼沈藻，攀藤鸟出煙。","生衣宜水竹，小酒入诗篇。","莫怪侵星坐，神清不欲眠。"]', '诗', 'shi', '', NULL, '駱家亭子納涼 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a93d44-c118-4632-ab41-cb284c3f42a4', '逢隴西故人憶關中舍弟', '逢隴西故人憶关中舍弟', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["莫話邊庭事，心摧不欲聞。","數年家隴地，舍弟歿胡軍。","每念支離苦，常嗟骨肉分。","急難何日見，遙哭隴西雲。"]', '["莫話邊庭事，心摧不欲闻。","數年家隴地，舍弟歿胡軍。","每念支離苦，常嗟骨肉分。","急难何日见，遙哭隴西云。"]', '诗', 'shi', '', NULL, '逢隴西故人憶關中舍弟 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005e9a7b-8f96-422b-831e-15334672bcf4', '秋夜梁十三廳事', '秋夜梁十三廳事', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["今來秋已暮，還恐未成歸。","夢裏家仍遠，愁中葉又飛。","竹聲風度急，燈影月來微。","得見梁夫子，心源有所依。"]', '["今来秋已暮，還恐未成归。","梦裏家仍远，愁中葉又飞。","竹声风度急，灯影月来微。","得见梁夫子，心源有所依。"]', '诗', 'shi', '', NULL, '秋夜梁十三廳事 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae1f682-4648-483a-ae39-0f8652fe11b8', '成都暮雨秋', '成都暮雨秋', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["九月龜城暮，愁人閉草堂。","地卑多雨潤，天暖少秋霜。","縱欲傾新酒，其如憶故鄉。","不知更漏意，惟向客邊長。"]', '["九月龟城暮，愁人閉草堂。","地卑多雨潤，天暖少秋霜。","縱欲傾新酒，其如憶故乡。","不知更漏意，惟向客邊长。"]', '诗', 'shi', '', NULL, '成都暮雨秋 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4401141b-88e2-4558-b885-7471d048f527', '酬梁二十', '酬梁二十', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["渚宮無限客，相見獨相親。","長路皆同病，無言似一身。","歲寒唯愛竹，憔悴不堪春。","細與知音說，攻文恐悞人。"]', '["渚宮無限客，相见独相親。","长路皆同病，無言似一身。","歲寒唯愛竹，憔悴不堪春。","細與知音说，攻文恐悞人。"]', '诗', 'shi', '', NULL, '酬梁二十 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a1771de-2185-4844-869c-9bb5a86f7291', '花下宴送鄭鍊師', '花下宴送鄭鍊師', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["愁裏惜春深，聞幽即共尋。","貴看花柳色，圖放別離心。","客醉花能笑，詩成花伴吟。","爲君調綠綺，先奏鳳歸林。"]', '["愁裏惜春深，闻幽即共尋。","貴看花柳色，圖放別離心。","客醉花能笑，诗成花伴吟。","爲君調綠綺，先奏鳳归林。"]', '诗', 'shi', '', NULL, '花下宴送鄭鍊師 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc7375c-009e-4f34-9744-bcbda1b040f6', '秋館雨後得弟兄書即事呈李明府', '秋館雨後得弟兄书即事呈李明府', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["弟兄書忽到，一夜喜兼愁。","空館復聞雨，貧家怯到秋。","坐中孤燭暗，窗外數螢流。","試以他鄉事，明朝問子游。"]', '["弟兄书忽到，一夜喜兼愁。","空館复闻雨，貧家怯到秋。","坐中孤燭暗，窗外數螢流。","試以他乡事，明朝问子游。"]', '诗', 'shi', '', NULL, '秋館雨後得弟兄書即事呈李明府 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c556f12-18ed-483b-a6f3-29e1dfa9dc1e', '寄梁淑', '寄梁淑', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["長憶江頭執別時，論文未有不相思。","鴈過經秋無尺素，人來終日見新詩。","心思食檗何由展，家似流萍任所之。","悔學秦人南避地，武陵原上又徵師。"]', '["长憶江头執別时，論文未有不相思。","鴈過經秋無尺素，人来終日见新诗。","心思食檗何由展，家似流萍任所之。","悔学秦人南避地，武陵原上又徵師。"]', '诗', 'shi', '', NULL, '寄梁淑 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('617a5253-3705-4d08-a743-8a95d7cab1a8', '送張秀才之長沙', '送張秀才之长沙', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["君向長沙去，長沙僕舊諳。","雖之桂嶺北，終是闕庭南。","山靄生朝雨，江煙作夕嵐。","松醪能醉客，慎勿滯湘潭。"]', '["君向长沙去，长沙僕旧諳。","雖之桂嶺北，終是闕庭南。","山靄生朝雨，江煙作夕嵐。","松醪能醉客，慎勿滯湘潭。"]', '诗', 'shi', '', NULL, '送張秀才之長沙 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83ba434-4d45-4934-90ba-cb9a283c7adf', '塞下曲', '塞下曲', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["漢將歸來虜塞空，旌旗初下玉關東。","高蹄戰馬三千匹，落日平原秋草中。"]', '["漢將归来虜塞空，旌旗初下玉关东。","高蹄戰马三千匹，落日平原秋草中。"]', '诗', 'shi', '', NULL, '塞下曲 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d73b9a-ef1c-4ba9-90e8-33337c0d3828', '送僧法和', '送僧法和', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["達士心無滯，他鄉總是家。","問經翻貝葉，論法指蓮花。","欲契真空義，先開智慧芽。"]', '["達士心無滯，他乡總是家。","问經翻貝葉，論法指蓮花。","欲契真空義，先开智慧芽。"]', '诗', 'shi', '', NULL, '送僧法和 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9ecee31-4d9d-4ef2-85c6-d28416d6b482', '送嚴十五郎之長安', '送嚴十五郎之长安', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["送客身爲客，思家愴別家。","暫收雙眼淚，遙想五陵花。","路遠征車迥，山迴劍閣斜。","長安君到日，春色未應賒。"]', '["送客身爲客，思家愴別家。","暫收雙眼泪，遙想五陵花。","路远征车迥，山迴劍閣斜。","长安君到日，春色未應賒。"]', '诗', 'shi', '', NULL, '送嚴十五郎之長安 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d04d23-e86c-4f86-bebc-7b01bac06227', '冬夜宴梁十三廳', '冬夜宴梁十三廳', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["故人能愛客，秉燭會吾曹。","家爲朋徒罄，心緣翰墨勞。","夜寒銷臘酒，霜冷重綈袍。","醉臥西窗下，時聞鴈響高。"]', '["故人能愛客，秉燭會吾曹。","家爲朋徒罄，心緣翰墨勞。","夜寒銷臘酒，霜冷重綈袍。","醉臥西窗下，时闻鴈响高。"]', '诗', 'shi', '', NULL, '冬夜宴梁十三廳 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b06a88-7428-4a32-983c-e38fa9022748', '收襄陽城二首 一', '收襄陽城二首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["悲風慘慘雨修修，峴北山低草木愁。","暗發前軍連夜戰，平明旌斾入襄州。"]', '["悲风慘慘雨修修，峴北山低草木愁。","暗發前軍連夜戰，平明旌斾入襄州。"]', '诗', 'shi', '', NULL, '收襄陽城二首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad423cdb-dc3b-4a76-baa9-e9bbe4c42ad6', '收襄陽城二首 二', '收襄陽城二首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["五營飛將擁霜戈，百里僵屍滿濜河。","日暮歸來看劍血，將軍却恨殺人多。"]', '["五營飞將擁霜戈，百里僵屍满濜河。","日暮归来看劍血，將軍却恨殺人多。"]', '诗', 'shi', '', NULL, '收襄陽城二首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b2bca2-914a-4f10-91ba-30789d8d1d94', '出軍', '出軍', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["龍繞旌竿獸滿旗，飜營乍似雪中移。","中軍一隊三千騎，盡是幷州遊俠兒。"]', '["龙繞旌竿獸满旗，飜營乍似雪中移。","中軍一隊三千騎，尽是幷州游俠兒。"]', '诗', 'shi', '', NULL, '出軍 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9bf721-cc0b-4b55-85e9-16048840e989', '和李尹種葛', '和李尹種葛', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["弱質人皆棄，唯君手自栽。","藟含霜後竹，香惹臘前梅。","擬託凌雲勢，須憑接引材。","清陰如可惜，黃鳥定飛來。"]', '["弱質人皆棄，唯君手自栽。","藟含霜後竹，香惹臘前梅。","擬託凌云勢，須憑接引材。","清陰如可惜，黄鸟定飞来。"]', '诗', 'shi', '', NULL, '和李尹種葛 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb4045f-7ced-4d49-8a43-ed45e4360619', '送零陵妓', '送零陵妓', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["寶鈿香蛾翡翠裙，裝成掩泣欲行雲。","殷勤好取襄王意，莫向陽臺夢使君。"]', '["寶鈿香蛾翡翠裙，裝成掩泣欲行云。","殷勤好取襄王意，莫向陽台梦使君。"]', '诗', 'shi', '', NULL, '送零陵妓 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('201fce61-24c2-4827-b750-b248c13cda8a', '採蓮曲二首 一', '採蓮曲二首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["雖聽採蓮曲，詎識採蓮心。","漾檝愛花遠，回船愁浪深。","煙生極浦色，日落半江陰。","同侶憐波靜，看妝墮玉簪。"]', '["雖听採蓮曲，詎識採蓮心。","漾檝愛花远，回船愁浪深。","煙生極浦色，日落半江陰。","同侶怜波静，看妝墮玉簪。"]', '诗', 'shi', '', NULL, '採蓮曲二首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132568c9-a68d-4d29-bfd9-5cf15e080481', '採蓮曲二首 二', '採蓮曲二首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["涔陽女兒花滿頭，毿毿同泛木蘭舟。","秋風日暮南湖裏，爭唱菱歌不肯休。"]', '["涔陽女兒花满头，毿毿同泛木蘭舟。","秋风日暮南湖裏，爭唱菱歌不肯休。"]', '诗', 'shi', '', NULL, '採蓮曲二首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391be8e3-b30d-4d09-8543-f3bb5ca518eb', '塞上曲', '塞上曲', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["胡風略地燒連山，碎葉孤城未下關。","山頭烽子聲聲呌，知是將軍夜獵還。"]', '["胡风略地燒連山，碎葉孤城未下关。","山头烽子声声呌，知是將軍夜獵還。"]', '诗', 'shi', '', NULL, '塞上曲 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4df06f66-cbad-4eeb-9ef3-4994697ac17b', '寂上人禪房', '寂上人禪房', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["俗塵浮垢閉禪關，百歲身心幾日閑。","安得此生同草木，無營長在四時間。"]', '["俗塵浮垢閉禪关，百歲身心幾日闲。","安得此生同草木，無營长在四时间。"]', '诗', 'shi', '', NULL, '寂上人禪房 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1325f327-c549-4ee8-ad32-5fca704bb474', '桂州口號', '桂州口號', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["畫角三聲動客愁，曉霜如雪覆江樓。","誰道桂林風景暖，到來重著皁貂裘。"]', '["畫角三声动客愁，晓霜如雪覆江楼。","誰道桂林风景暖，到来重著皁貂裘。"]', '诗', 'shi', '', NULL, '桂州口號 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a11ee75-1449-47da-9daf-9e950163c0f9', '紅槿花', '紅槿花', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["花是深紅葉麴塵，不將桃李共爭春。","今日驚秋自憐客，折來持贈少年人。"]', '["花是深紅葉麴塵，不將桃李共爭春。","今日驚秋自怜客，折来持贈少年人。"]', '诗', 'shi', '', NULL, '紅槿花 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1dc503-fff9-4188-90f8-4b337d9411e4', '哭黔中薛大夫', '哭黔中薛大夫', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["亞相何年鎮百蠻，生涯萬事瘴雲間。","夜郎城外誰人哭，昨日空餘旌節還。"]', '["亞相何年鎮百蠻，生涯万事瘴云间。","夜郎城外誰人哭，昨日空餘旌節還。"]', '诗', 'shi', '', NULL, '哭黔中薛大夫 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('862104e5-cfeb-4843-9e5f-8bdff6294563', '感春', '感春', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["看花淚盡知春盡，魂斷看花秪恨春。","名位未霑身欲老，詩書寧救眼前貧。"]', '["看花泪尽知春尽，魂斷看花秪恨春。","名位未霑身欲老，诗书寧救眼前貧。"]', '诗', 'shi', '', NULL, '感春 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c65d8d-2871-4c7f-b2fc-fdeaceefa18e', '途中寄李二', '途中寄李二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["楊柳煙含灞岸春，年年攀折爲行人。","好風若借低枝便，莫遣青絲埽路塵。"]', '["楊柳煙含灞岸春，年年攀折爲行人。","好风若借低枝便，莫遣青絲埽路塵。"]', '诗', 'shi', '', NULL, '途中寄李二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ab20d5-7509-4597-b183-d6ac7ff5b596', '寄許鍊師', '寄許鍊師', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["埽石焚香禮碧空，露華偏濕蘂珠宮。","如何說得天壇上，萬里無雲月正中。"]', '["埽石焚香禮碧空，露华偏濕蘂珠宮。","如何说得天壇上，万里無云月正中。"]', '诗', 'shi', '', NULL, '寄許鍊師 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dcc6052-2a05-489d-b1b6-468566abe405', '下第留辭顧侍郎', '下第留辞顧侍郎', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["綺陌彤彤花照塵，王門侯邸盡朱輪。","城南舊有山村路，欲向雲霞覓主人。"]', '["綺陌彤彤花照塵，王门侯邸尽朱輪。","城南旧有山村路，欲向云霞覓主人。"]', '诗', 'shi', '', NULL, '下第留辭顧侍郎 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('671df53a-8f7c-4858-a81b-b940a7f23410', '題雲公山房', '題云公山房', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["雲公蘭若深山裏，月明松殿微風起。","試問空門清淨心，蓮花不著秋潭水。"]', '["云公蘭若深山裏，月明松殿微风起。","試问空门清淨心，蓮花不著秋潭水。"]', '诗', 'shi', '', NULL, '題雲公山房 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c07af91d-f04b-49d9-bef2-7c385486e059', '別離作', '別離作', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["手把杏花枝，未曾經離別。","黃昏掩門後，寂寞自心知。"]', '["手把杏花枝，未曾經離別。","黄昏掩门後，寂寞自心知。"]', '诗', 'shi', '', NULL, '別離作 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3576fb63-e8ea-41bf-9cec-4b8ac791422c', '九日賈明府見訪', '九日賈明府见訪', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["獨掩衡門秋景閑，洛陽才子訪柴關。","莫嫌濁酒君須醉，雖是貧家菊也斑。","同人願得長攜手，久客深思一破顏。","却笑孟嘉吹帽落，登高何必上龍山。"]', '["独掩衡门秋景闲，洛陽才子訪柴关。","莫嫌濁酒君須醉，雖是貧家菊也斑。","同人願得长携手，久客深思一破顏。","却笑孟嘉吹帽落，登高何必上龙山。"]', '诗', 'shi', '', NULL, '九日賈明府見訪 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('699b5dce-f6cd-4580-b5fe-968eaa185c33', '開元觀陪杜大夫中元日觀樂', '开元观陪杜大夫中元日观乐', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["今朝歡稱玉京天，況值關東俗理年。","舞態疑迴紫陽女，歌聲似遏綵雲仙。","盤空雙鶴驚几劍，灑砌三花度管弦。","落日香塵擁歸騎，囗風油幕動高煙。"]', '["今朝歡稱玉京天，況值关东俗理年。","舞態疑迴紫陽女，歌声似遏綵云仙。","盤空雙鹤驚几劍，灑砌三花度管弦。","落日香塵擁归騎，囗风油幕动高煙。"]', '诗', 'shi', '', NULL, '開元觀陪杜大夫中元日觀樂 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab4e15ff-7244-4bd0-860e-4622b1feca27', '中秋夜登樓望月寄人', '中秋夜登楼望月寄人', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["西樓見月似江城，脈脈悠悠倚檻情。","萬里此情同皎潔，一年今日最分明。","初驚桂子從天落，稍誤蘆花帶雪平。","知稱玉人臨水見，可憐光彩有餘清。"]', '["西楼见月似江城，脈脈悠悠倚檻情。","万里此情同皎潔，一年今日最分明。","初驚桂子從天落，稍誤蘆花带雪平。","知稱玉人臨水见，可怜光彩有餘清。"]', '诗', 'shi', '', NULL, '中秋夜登樓望月寄人 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('922697b6-33fb-4084-bb8f-c3eea4b305d4', '贈宜陽張使君', '贈宜陽張使君', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["暫作宜陽客，深知太守賢。","政移千里俗，人戴兩重天。","舊郭多新室，閑坡盡辟田。","倘令黃霸在，今日恥同年。"]', '["暫作宜陽客，深知太守賢。","政移千里俗，人戴兩重天。","旧郭多新室，闲坡尽辟田。","倘令黄霸在，今日恥同年。"]', '诗', 'shi', '', NULL, '贈宜陽張使君 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3406eb2f-32d4-432a-95b7-4cdeb6a9aa95', '移家別樹', '移家別樹', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["千種庭前樹，人移樹不移。","看花愁作別，不及未栽時。"]', '["千種庭前樹，人移樹不移。","看花愁作別，不及未栽时。"]', '诗', 'shi', '', NULL, '移家別樹 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('860346c6-24a9-4614-bc42-eef8b29086d1', '成都送嚴十五之江東', '成都送嚴十五之江东', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["江東萬里外，別後幾悽悽。","峽路花應發，津亭柳正齊。","酒傾遲日暮，川闊遠天低。","心繫征帆上，隨君到剡溪。"]', '["江东万里外，別後幾悽悽。","峽路花應發，津亭柳正齊。","酒傾遲日暮，川闊远天低。","心繫征帆上，隨君到剡溪。"]', '诗', 'shi', '', NULL, '成都送嚴十五之江東 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6ae74b-ecff-464d-9692-353e6a83a2a7', '送李參軍', '送李參軍', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["好住好住王司戶，珍重珍重李參軍。","一東一西如別鶴，一南一北似浮雲。","月照疎林千片影，風吹寒水萬里紋。","別易會難今古事，非是余今獨與君。"]', '["好住好住王司戶，珍重珍重李參軍。","一东一西如別鹤，一南一北似浮云。","月照疎林千片影，风吹寒水万里紋。","別易會难今古事，非是余今独與君。"]', '诗', 'shi', '', NULL, '送李參軍 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9b9f11-1a5d-492c-a94f-88b9ed59f3eb', '題嚴氏竹亭', '題嚴氏竹亭', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["子陵棲遁處，堪繫野人心。","溪水浸山影，嵐煙向竹陰。","忘機看白日，留客醉瑤琴。","愛此多詩興，歸來步步吟。"]', '["子陵棲遁处，堪繫野人心。","溪水浸山影，嵐煙向竹陰。","忘機看白日，留客醉瑤琴。","愛此多诗兴，归来步步吟。"]', '诗', 'shi', '', NULL, '題嚴氏竹亭 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ab9743-84dc-4e44-a764-cc8d32fae9ec', '送王端公之太原歸覲相公', '送王端公之太原归覲相公', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["柱史今何適，西行詠陟岡。","也知人惜別，終美鴈成行。","春雨桃花靜，離尊竹葉香。","到時丞相閣，應喜棣華芳。"]', '["柱史今何適，西行詠陟岡。","也知人惜別，終美鴈成行。","春雨桃花静，離尊竹葉香。","到时丞相閣，應喜棣华芳。"]', '诗', 'shi', '', NULL, '送王端公之太原歸覲相公 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b372cf-583f-4e72-9ed6-81bafa8bcdcf', '旅次寄湖南張郎中', '旅次寄湖南張郎中', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["寒江近戶漫流聲，竹影臨窗亂月明。","歸夢不知湖水闊，夜來還到洛陽城。"]', '["寒江近戶漫流声，竹影臨窗亂月明。","归梦不知湖水闊，夜来還到洛陽城。"]', '诗', 'shi', '', NULL, '旅次寄湖南張郎中 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1689d325-7e76-4865-862b-6fe65ca9432f', '晚次荆江', '晚次荆江', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["孤舟大江水，水涉無昏曙。","雨暗迷津時，雲生望鄉處。","漁翁閑自樂，樵客紛多慮。","秋色湖上山，歸心日邊樹。","徒稱竹箭美，未得楓林趣。","向夕垂釣還，吾從落潮去。"]', '["孤舟大江水，水涉無昏曙。","雨暗迷津时，云生望乡处。","漁翁闲自乐，樵客紛多慮。","秋色湖上山，归心日邊樹。","徒稱竹箭美，未得楓林趣。","向夕垂釣還，吾從落潮去。"]', '诗', 'shi', '', NULL, '晚次荆江 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4889a0b4-4921-4d09-bab3-b69ae5fb1f5b', '同辛衮州巢父虛副端岳相思獻酬之作因紓歸懷兼呈辛魏二院長楊長寧', '同辛衮州巢父虛副端岳相思獻酬之作因紓归懷兼呈辛魏二院长楊长寧', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["暮角發高城，情人坐中起。","臨觴不及醉，分散秋風裏。","雖有明月期，離心若千里。","前歡反惆悵，後會還如此。","焉得夜淹留，一回終宴喜。","羇遊復牽役，館至重湖水。","早晚泛歸舟，吾從數君子。"]', '["暮角發高城，情人坐中起。","臨觴不及醉，分散秋风裏。","雖有明月期，離心若千里。","前歡反惆悵，後會還如此。","焉得夜淹留，一回終宴喜。","羇游复牽役，館至重湖水。","早晚泛归舟，吾從數君子。"]', '诗', 'shi', '', NULL, '同辛衮州巢父虛副端岳相思獻酬之作因紓歸懷兼呈辛魏二院長楊長寧 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d7fa09-8da8-48f0-9f43-f378e4d25fb5', '撫州處士湖泛舟送北迴兩指此南昌縣查溪蘭若別', '撫州处士湖泛舟送北迴兩指此南昌縣查溪蘭若別', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["移樽鋪山曲，祖帳查溪陰。","鋪山即遠道，查溪非故林。","悽然誦新詩，落淚霑素襟。","郡政我何有，別情君獨深。","禪庭古樹秋，宿雨清沈沈。","揮袂故里遠，悲傷去住心。"]', '["移樽鋪山曲，祖帳查溪陰。","鋪山即远道，查溪非故林。","悽然誦新诗，落泪霑素襟。","郡政我何有，別情君独深。","禪庭古樹秋，宿雨清沈沈。","揮袂故里远，悲傷去住心。"]', '诗', 'shi', '', NULL, '撫州處士湖泛舟送北迴兩指此南昌縣查溪蘭若別 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e15225-a319-475c-8c6d-7956d09d65b2', '耒陽谿夜行', '耒陽谿夜行', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["乘夕棹歸舟，緣源二轉幽。","月明看嶺樹，風靜聽溪流。","嵐氣船間入，霜華衣上浮。","猨聲雖此夜，不是別家愁。"]', '["乘夕棹归舟，緣源二轉幽。","月明看嶺樹，风静听溪流。","嵐氣船间入，霜华衣上浮。","猨声雖此夜，不是別家愁。"]', '诗', 'shi', '', NULL, '耒陽谿夜行 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d4a4e7-c5da-4339-adfe-c1aa309d2dfa', '桂城早秋', '桂城早秋', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["遠客驚秋早，江天夜露新。","滿庭惟有月，空館更何人。","卜命知身賤，傷寒舞劒頻。","猨啼曾下淚，可是爲憂貧。"]', '["远客驚秋早，江天夜露新。","满庭惟有月，空館更何人。","卜命知身賤，傷寒舞劒頻。","猨啼曾下泪，可是爲憂貧。"]', '诗', 'shi', '', NULL, '桂城早秋 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7247095c-ceeb-44e4-91e6-663aa7d504f5', '桂州歲暮', '桂州歲暮', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["歲暮天涯客，寒窗欲曉時。","君恩空自感，鄉思夢先知。","重誼人愁別，驚棲鵲戀枝。","不堪樓上角，南向海風吹。"]', '["歲暮天涯客，寒窗欲晓时。","君恩空自感，乡思梦先知。","重誼人愁別，驚棲鵲戀枝。","不堪楼上角，南向海风吹。"]', '诗', 'shi', '', NULL, '桂州歲暮 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdea9bf2-da77-4657-a7f7-83521485f165', '宿桂州江亭呈康端公', '宿桂州江亭呈康端公', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["獨向東亭坐，三更待月開。","螢光入竹去，水影過江來。","露滴千家靜，年流一葉催。","龍鐘萬里客，正合故人哀。"]', '["独向东亭坐，三更待月开。","螢光入竹去，水影過江来。","露滴千家静，年流一葉催。","龙鐘万里客，正合故人哀。"]', '诗', 'shi', '', NULL, '宿桂州江亭呈康端公 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10bd94bd-1cf5-4974-ac27-163c98993297', '寒食日恩賜火', '寒食日恩賜火', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["恩光及小臣，華燭忽驚春。","電影隨中使，星輝拂路人。","幸因榆柳暖，一照草茅貧。"]', '["恩光及小臣，华燭忽驚春。","電影隨中使，星輝拂路人。","幸因榆柳暖，一照草茅貧。"]', '诗', 'shi', '', NULL, '寒食日恩賜火 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd50ba7e-1dad-4f2d-bf20-1f00909f5fc2', '端午日恩賜百索', '端午日恩賜百索', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["仙宮長命縷，端午降殊私。","事盛蛟龍見，恩深犬馬知。","餘生儻可續，終冀荅明時。"]', '["仙宮长命縷，端午降殊私。","事盛蛟龙见，恩深犬马知。","餘生儻可續，終冀荅明时。"]', '诗', 'shi', '', NULL, '端午日恩賜百索 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11d8717-13a3-4319-80ca-054d1513be94', '貞懿皇后挽歌三首 一', '貞懿皇后挽歌三首 一', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["二陵恭婦道，六寢盛皇情。","禮遜生前貴，恩追歿後榮。","幼王親捧土，愛女復連塋。","東望長如在，誰云向玉京。"]', '["二陵恭婦道，六寢盛皇情。","禮遜生前貴，恩追歿後榮。","幼王親捧土，愛女复連塋。","东望长如在，誰云向玉京。"]', '诗', 'shi', '', NULL, '貞懿皇后挽歌三首 一 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f2beb1-d33f-46b4-9111-aa88723b67a5', '貞懿皇后挽歌三首 二', '貞懿皇后挽歌三首 二', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["後庭攀畫柳，上陌咽清笳。","命婦羞蘋葉，都人插柰花。","壽宮星月異，仙路往來賒。","縱有迎仙術，終悲隔絳紗。"]', '["後庭攀畫柳，上陌咽清笳。","命婦羞蘋葉，都人插柰花。","壽宮星月異，仙路往来賒。","縱有迎仙術，終悲隔絳紗。"]', '诗', 'shi', '', NULL, '貞懿皇后挽歌三首 二 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5086dcd0-ed5b-47cb-bd82-37664fe4364a', '秋砧送邑大夫', '秋砧送邑大夫', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["斷續長門下，清泠逆旅秋。","征夫應待信，寒女不勝愁。","帶月飛城上，因風散陌頭。","離居偏入聽，況復送歸舟。"]', '["斷續长门下，清泠逆旅秋。","征夫應待信，寒女不勝愁。","带月飞城上，因风散陌头。","離居偏入听，況复送归舟。"]', '诗', 'shi', '', NULL, '秋砧送邑大夫 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc613af-cb28-4122-9aec-0f6d24954068', '過擔石湖', '過擔石湖', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["曉發漁門戍，晴看擔石湖。","日銜高浪出，天入四空無。","尺寸分洲島，纖毫指舳艫。","渺然從此去，誰念客帆孤。"]', '["晓發漁门戍，晴看擔石湖。","日銜高浪出，天入四空無。","尺寸分洲島，纖毫指舳艫。","渺然從此去，誰念客帆孤。"]', '诗', 'shi', '', NULL, '過擔石湖 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03aa3f4-0260-49c5-8017-e0feffc5e20c', '春日早朝應制', '春日早朝應制', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["紫殿俯千官，春松應合歡。","御爐香焰暖，馳道玉聲寒。","乳燕翻珠綴，祥烏集露盤。","宮花一萬樹，不敢舉頭看。"]', '["紫殿俯千官，春松應合歡。","御爐香焰暖，驰道玉声寒。","乳燕翻珠綴，祥烏集露盤。","宮花一万樹，不敢舉头看。"]', '诗', 'shi', '', NULL, '春日早朝應制 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c55c44-7084-4543-8c1a-98659aec9bfb', '酬李袁州嘉祐', '酬李袁州嘉祐', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["少年輕會復輕離，老大開心總是悲。","強說前程聊自慰，未知攜手定何時。","公才屈指登黃閣，匪服胡顏上赤墀。","想到長安誦佳句，滿朝誰不念瓊枝。"]', '["少年轻會复轻離，老大开心總是悲。","強说前程聊自慰，未知携手定何时。","公才屈指登黄閣，匪服胡顏上赤墀。","想到长安誦佳句，满朝誰不念瓊枝。"]', '诗', 'shi', '', NULL, '酬李袁州嘉祐 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1139c653-caae-4f86-819c-6c990fe83220', '夏夜宿表兄話舊', '夏夜宿表兄話旧', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["夜合花開香滿庭，夜深微雨醉初醒。","遠書珍重何曾達，舊事淒涼不可聽。","去日兒童皆長大，昔年親友半凋零。","明朝又是孤舟別，愁見河橋酒幔青。"]', '["夜合花开香满庭，夜深微雨醉初醒。","远书珍重何曾達，旧事淒涼不可听。","去日兒童皆长大，昔年親友半凋零。","明朝又是孤舟別，愁见河橋酒幔青。"]', '诗', 'shi', '', NULL, '夏夜宿表兄話舊 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366efe25-4e62-4181-89cb-52c3f01b7f3f', '句', '句', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["禁兵環素帟，宮女哭寒雲。"]', '["禁兵环素帟，宮女哭寒云。"]', '诗', 'shi', '', NULL, '句 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9067ef-c595-412b-8ca7-fff6fb8fdab5', '晚次方山精舍却寄張薦員外', '晚次方山精舍却寄張薦員外', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["楚臘還無雪，江春又足風。","馬羸三逕外，人病四愁中。","西塞波濤闊，南朝寺舍空。","猶銜步兵酒，宿醉在除東。"]', '["楚臘還無雪，江春又足风。","马羸三逕外，人病四愁中。","西塞波濤闊，南朝寺舍空。","猶銜步兵酒，宿醉在除东。"]', '诗', 'shi', '', NULL, '晚次方山精舍却寄張薦員外 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63aaf778-c5bd-4d98-a3ec-e223a241d3aa', '和裴端公樞蕪城秋夕簡遠近親知', '和裴端公樞蕪城秋夕簡远近親知', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["歲積登朝戀，秋加陋巷貧。","宿酲因夜歇，佳句得愁新。","盡日憑幽几，何時上軟輪。","漢廷風憲在，應念匪躬人。"]', '["歲積登朝戀，秋加陋巷貧。","宿酲因夜歇，佳句得愁新。","尽日憑幽几，何时上軟輪。","漢廷风憲在，應念匪躬人。"]', '诗', 'shi', '', NULL, '和裴端公樞蕪城秋夕簡遠近親知 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49721ff7-6b92-493b-8b57-561c21769727', '項亭懷古', '項亭懷古', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["力取誠多難，天亡路亦窮。","有心裁帳下，無面到江東。","命厄留騅處，年銷逐鹿中。","漢家神器在，須廢拔山功。"]', '["力取誠多难，天亡路亦窮。","有心裁帳下，無面到江东。","命厄留騅处，年銷逐鹿中。","漢家神器在，須廢拔山功。"]', '诗', 'shi', '', NULL, '項亭懷古 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f472cf3f-b9c2-4bcb-a4e6-dca80c11bc07', '奉使西還早發小磵館寄盧滁州邁', '奉使西還早發小磵館寄盧滁州邁', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["野棠花覆地，山館夜來陰。","馬蹟穿雲去，雞聲出澗深。","清風時偃草，久旱或爲霖。","試與惸嫠話，猶堅借寇心。"]', '["野棠花覆地，山館夜来陰。","马蹟穿云去，雞声出澗深。","清风时偃草，久旱或爲霖。","試與惸嫠話，猶堅借寇心。"]', '诗', 'shi', '', NULL, '奉使西還早發小磵館寄盧滁州邁 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4a8830-564d-4800-849e-102044930605', '早發金鉤店寄奚十唐大二茂才', '早發金鉤店寄奚十唐大二茂才', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["出門山未曙，風葉暗蕭蕭。","月影臨荒柵，泉聲近廢橋。","歲經秋後役，程在洛中遙。","寄謝金門侶，弓旌悞見招。"]', '["出门山未曙，风葉暗蕭蕭。","月影臨荒柵，泉声近廢橋。","歲經秋後役，程在洛中遙。","寄謝金门侶，弓旌悞见招。"]', '诗', 'shi', '', NULL, '早發金鉤店寄奚十唐大二茂才 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c71ef5d-2b99-4ece-b3db-deefc25bc346', '途中立春寄楊郇伯', '途中立春寄楊郇伯', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["浪跡終年客，驚心此地春。","風前獨去馬，澤畔耦耕人。","老大交情重，悲涼外物親。","子雲今在宅，應見柳條新。"]', '["浪跡終年客，驚心此地春。","风前独去马，澤畔耦耕人。","老大交情重，悲涼外物親。","子云今在宅，應见柳條新。"]', '诗', 'shi', '', NULL, '途中立春寄楊郇伯 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f34943e5-a9e5-4768-8a72-95e6d0b78570', '故秘監丹陽郡公延陵包公挽歌詞', '故秘監丹陽郡公延陵包公挽歌词', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["卓絕明時第，孤貞貴後貧。","郄詵爲胄子，季札是鄉人。","筆下調金石，花開領搢紳。","那堪歸葬日，哭渡柳楊津。"]', '["卓絕明时第，孤貞貴後貧。","郄詵爲胄子，季札是乡人。","笔下調金石，花开領搢紳。","那堪归葬日，哭渡柳楊津。"]', '诗', 'shi', '', NULL, '故秘監丹陽郡公延陵包公挽歌詞 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da28c9b-ec8c-469c-ab74-f58aff76b190', '涼國惠康公主挽歌', '涼国惠康公主挽歌', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["玉立分堯緒，笄年下相門。","早加于氏對，偏占館陶恩。","淚有潛成血，香無却返魂。","共知何駙馬，垂白抱天孫。"]', '["玉立分堯緒，笄年下相门。","早加于氏对，偏占館陶恩。","泪有潛成血，香無却返魂。","共知何駙马，垂白抱天孫。"]', '诗', 'shi', '', NULL, '涼國惠康公主挽歌 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4698945-f527-4344-a4b5-af050a413e43', '哭張倉曹南史', '哭張倉曹南史', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["萬事竟蹉跎，重泉恨若何。","官臨環衛小，身逐轉蓬多。","麗藻嘗專席，閑情欲爛柯。","春風宛陵路，丹旐在滄波。"]', '["万事竟蹉跎，重泉恨若何。","官臨环衛小，身逐轉蓬多。","丽藻嘗專席，闲情欲爛柯。","春风宛陵路，丹旐在滄波。"]', '诗', 'shi', '', NULL, '哭張倉曹南史 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5c1cb9-bc53-4eba-97ff-9d7d80910201', '北固晚眺', '北固晚眺', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["水國芒種後，梅天風雨涼。","露蠶開晚簇，江燕繞危檣。","山趾北來固，潮頭西去長。","年年此登眺，人事幾銷亡。"]', '["水国芒種後，梅天风雨涼。","露蠶开晚簇，江燕繞危檣。","山趾北来固，潮头西去长。","年年此登眺，人事幾銷亡。"]', '诗', 'shi', '', NULL, '北固晚眺 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9caeae0-06ef-4554-9365-9ac1994d91ac', '謁三閭廟', '謁三閭廟', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["君非三諫寤，禮許一身逃。","自樹終天戚，何裨事主勞。","衆魚應餌骨，多士盡餔糟。","有客椒漿奠，文衰不繼騷。"]', '["君非三諫寤，禮許一身逃。","自樹終天戚，何裨事主勞。","衆鱼應餌骨，多士尽餔糟。","有客椒漿奠，文衰不繼騷。"]', '诗', 'shi', '', NULL, '謁三閭廟 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57eb4739-d295-4ac7-961e-f7d28f325383', '茅山贈梁尊師', '茅山贈梁尊師', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["雲屋何年客，青山白日長。","種花春掃雪，看籙夜焚香。","上象壺中闊，平生醉裏忙。","幸承仙籍後，乞取大還方。"]', '["云屋何年客，青山白日长。","種花春掃雪，看籙夜焚香。","上象壺中闊，平生醉裏忙。","幸承仙籍後，乞取大還方。"]', '诗', 'shi', '', NULL, '茅山贈梁尊師 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c71391-f43b-47cc-836b-038d2d078d30', '謁諸葛武侯廟', '謁諸葛武侯廟', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["永安宮外有祠堂，魚水恩深祚不長。","角立一方初退舍，擬稱三漢更圖王。","人同過隟無留影，石在窮沙尚啓行。","歸蜀降吳竟何事，爲陵爲谷共蒼蒼。"]', '["永安宮外有祠堂，鱼水恩深祚不长。","角立一方初退舍，擬稱三漢更圖王。","人同過隟無留影，石在窮沙尚啓行。","归蜀降吳竟何事，爲陵爲谷共蒼蒼。"]', '诗', 'shi', '', NULL, '謁諸葛武侯廟 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba2af05-1e7d-49cd-98f2-44371a857c6f', '奉賀太保岐公承恩致政', '奉賀太保岐公承恩致政', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["君爲宮保及清時，冠蓋初閑拜武遲。","五色詔中宣九德，百僚班外置三師。","山泉遂性休稱疾，子弟能官各受詞。","不學鑄金思范蠡，乞言猶許上丹墀。"]', '["君爲宮保及清时，冠蓋初闲拜武遲。","五色詔中宣九德，百僚班外置三師。","山泉遂性休稱疾，子弟能官各受词。","不学鑄金思范蠡，乞言猶許上丹墀。"]', '诗', 'shi', '', NULL, '奉賀太保岐公承恩致政 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c06f33-6a09-4f9d-94e1-86d39fd6078a', '之任武陵寒食日途次松滋渡先寄劉員外禹錫', '之任武陵寒食日途次松滋渡先寄劉員外禹錫', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["杏花榆莢曉風前，雲際離離上峽船。","江轉數程淹驛騎，楚曾三戶少人煙。","看春又過清明節，算老重經癸巳年。","幸得柱山當郡舍，在朝長詠卜居篇。"]', '["杏花榆莢晓风前，云際離離上峽船。","江轉數程淹驛騎，楚曾三戶少人煙。","看春又過清明節，算老重經癸巳年。","幸得柱山當郡舍，在朝长詠卜居篇。"]', '诗', 'shi', '', NULL, '之任武陵寒食日途次松滋渡先寄劉員外禹錫 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa155708-e969-4a7f-9a96-800ecc8818b8', '奉寄辰州房使君郎中', '奉寄辰州房使君郎中', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["漢代文明今盛明，猶將賈傅暫專城。","何妨密旨先符竹，莫是除書誤姓名。","蝸舍喜時春夢去，隼旟行處瘴江清。","新年只可三十二，却笑潘郎白髮生。"]', '["漢代文明今盛明，猶將賈傅暫專城。","何妨密旨先符竹，莫是除书誤姓名。","蝸舍喜时春梦去，隼旟行处瘴江清。","新年只可三十二，却笑潘郎白髮生。"]', '诗', 'shi', '', NULL, '奉寄辰州房使君郎中 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab240283-ee08-4d82-87d1-6ff1eba30096', '立春後言懷招汴州李匡衛推', '立春後言懷招汴州李匡衛推', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["閑齋夜擊唾壺歌，試望夷門奈遠何。","每聽寒笳離夢斷，時窺清鑑旅愁多。","初驚宵漏丁丁促，已覺春風習習和。","海內故人君最老，花開鞭馬更相過。"]', '["闲斋夜擊唾壺歌，試望夷门奈远何。","每听寒笳離梦斷，时窺清鑑旅愁多。","初驚宵漏丁丁促，已覺春风習習和。","海內故人君最老，花开鞭马更相過。"]', '诗', 'shi', '', NULL, '立春後言懷招汴州李匡衛推 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e764033f-a731-4cbd-a909-9e1131a02101', '奉送職方崔員外攝中丞新羅冊使', '奉送職方崔員外攝中丞新羅冊使', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["帝命海東使，人行天一涯。","辨方知木德，開國有金家。","冊拜申恩重，留歡作限賒。","順風鯨浪熱，初日錦帆斜。","夜色潛然火，秋期獨往槎。","慰安皆喻旨，忠信自無瑕。","髮美童年髻，簪香子月花。","便隨琛賮入，正朔在中華。"]', '["帝命海东使，人行天一涯。","辨方知木德，开国有金家。","冊拜申恩重，留歡作限賒。","順风鯨浪熱，初日錦帆斜。","夜色潛然火，秋期独往槎。","慰安皆喻旨，忠信自無瑕。","髮美童年髻，簪香子月花。","便隨琛賮入，正朔在中华。"]', '诗', 'shi', '', NULL, '奉送職方崔員外攝中丞新羅冊使 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37dc05d-581f-4234-84e2-06e42f2c733e', '酬舍弟牟秋日洛陽官舍寄懷十韻', '酬舍弟牟秋日洛陽官舍寄懷十韻', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["幼爲逃難者，纔省用兵初。","去國三苗外，全生四紀餘。","老頭親帝里，歸處失吾廬。","逝水猶嗚咽，祥雲自卷舒。","正郎曾首拜，亞尹未平除。","幾變陶家柳，空傳魏闕書。","思凌天際鶴，言甚轍中魚。","玉立知求己，金聲乍起予。","在朝魚水分，多病雪霜居。","忽報陽春曲，縱橫恨不如。"]', '["幼爲逃难者，纔省用兵初。","去国三苗外，全生四紀餘。","老头親帝里，归处失吾廬。","逝水猶嗚咽，祥云自卷舒。","正郎曾首拜，亞尹未平除。","幾变陶家柳，空傳魏闕书。","思凌天際鹤，言甚轍中鱼。","玉立知求己，金声乍起予。","在朝鱼水分，多病雪霜居。","忽報陽春曲，縱橫恨不如。"]', '诗', 'shi', '', NULL, '酬舍弟牟秋日洛陽官舍寄懷十韻 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f067ad-0289-4474-a94a-fe5117350987', '求自試', '求自試', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["仙禁祥雲合，高梧彩鳳遊。","沈冥求自試，通鑒果蒙收。","文墨悲無位，詩書誤白頭。","陳王抗表日，毛遂請行秋。","雙劍曾埋獄，司空問斗牛。","希垂拂拭惠，感激願相投。"]', '["仙禁祥云合，高梧彩鳳游。","沈冥求自試，通鑒果蒙收。","文墨悲無位，诗书誤白头。","陳王抗表日，毛遂請行秋。","雙劍曾埋獄，司空问斗牛。","希垂拂拭惠，感激願相投。"]', '诗', 'shi', '', NULL, '求自試 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46637ec9-5056-4420-a803-049de567ef82', '花發上林', '花發上林', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["上苑曉沈沈，花枝亂綴陰。","色浮雙闕近，春入九門深。","向暖風初扇，餘寒雪尚侵。","豔回秦女目，愁處越人心。","繞繞時縈蝶，關關乍引禽。","寧知幽谷羽，一舉欲依林。"]', '["上苑晓沈沈，花枝亂綴陰。","色浮雙闕近，春入九门深。","向暖风初扇，餘寒雪尚侵。","豔回秦女目，愁处越人心。","繞繞时縈蝶，关关乍引禽。","寧知幽谷羽，一舉欲依林。"]', '诗', 'shi', '', NULL, '花發上林 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('354902b4-ab27-4454-80a8-8b3d63251052', '過宋氏五女舊居', '過宋氏五女旧居', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["謝庭風韻婕妤才，天縱斯文去不迴。","一宅柳花今似雪，鄉人擬築望仙臺。"]', '["謝庭风韻婕妤才，天縱斯文去不迴。","一宅柳花今似雪，乡人擬築望仙台。"]', '诗', 'shi', '', NULL, '過宋氏五女舊居 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c13db18-b38e-482f-873e-62fffe754cc0', '還京樂歌詞', '還京乐歌词', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["百戰初休十萬師，國人西望翠華時。","家家盡唱升平曲，帝幸梨園親製詞。"]', '["百戰初休十万師，国人西望翠华时。","家家尽唱升平曲，帝幸梨园親製词。"]', '诗', 'shi', '', NULL, '還京樂歌詞 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7351d6b-330a-491a-9180-0251161bead4', '商山祠堂即事', '商山祠堂即事', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["奪嫡心萌事可憂，四賢西笑暫安劉。","後王不敢論珪組，土偶人前枳樹秋。"]', '["奪嫡心萌事可憂，四賢西笑暫安劉。","後王不敢論珪組，土偶人前枳樹秋。"]', '诗', 'shi', '', NULL, '商山祠堂即事 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eedd4a88-d1e9-4ec3-a8c3-0f98179658af', '七夕', '七夕', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["露盤花水望三星，髣髴虛無爲降靈。","斜漢沒時人不寐，幾條蛛網下風庭。"]', '["露盤花水望三星，髣髴虛無爲降靈。","斜漢沒时人不寐，幾條蛛網下风庭。"]', '诗', 'shi', '', NULL, '七夕 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a273d6-375f-4d6e-a432-6d6e0a3fb10a', '杏山館聽子規', '杏山館听子規', 'f7f41434-62b1-43e8-9e08-fe2b03ab63e8', '唐', '["楚塞餘春聽漸稀，斷猿今夕讓霑衣。","雲埋老樹空山裏，髣髴千聲一度飛。"]', '["楚塞餘春听漸稀，斷猿今夕讓霑衣。","云埋老樹空山裏，髣髴千声一度飞。"]', '诗', 'shi', '', NULL, '杏山館聽子規 竇常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd81112-19ef-4466-ae6d-ac8b8c6c30c5', '史館候別蔣拾遺不遇', '史館候別蔣拾遺不遇', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["千門萬戶迷，佇立月華西。","畫戟晨光動，春松宿露低。","主文親玉扆，通籍入金閨。","肯念從戎去，風沙事鼓鞞。"]', '["千门万戶迷，佇立月华西。","畫戟晨光动，春松宿露低。","主文親玉扆，通籍入金閨。","肯念從戎去，风沙事鼓鞞。"]', '诗', 'shi', '', NULL, '史館候別蔣拾遺不遇 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9429ffda-4ab2-440b-9d6f-842868680d89', '早赴臨臺立馬待漏口號寄弟羣', '早赴臨台立马待漏口號寄弟羣', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["上陌行初盡，嚴城立未開。","人疑早朝去，客是遠方來。","伏奏徒將命，周行自引才。","可憐霄漢曙，鴛鷺正徘徊。"]', '["上陌行初尽，嚴城立未开。","人疑早朝去，客是远方来。","伏奏徒將命，周行自引才。","可怜霄漢曙，鴛鷺正徘徊。"]', '诗', 'shi', '', NULL, '早赴臨臺立馬待漏口號寄弟羣 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b6e14a-5090-48fc-a8a3-82520d88083b', '緱氏拜陵迴道中呈李舍人少尹', '緱氏拜陵迴道中呈李舍人少尹', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["忽忝諸卿位，仍陪長者車。","禮容皆若舊，名籍自憑虛。","上路花偏早，空山雲甚餘。","却愁新詠發，酬和不相如。"]', '["忽忝諸卿位，仍陪长者车。","禮容皆若旧，名籍自憑虛。","上路花偏早，空山云甚餘。","却愁新詠發，酬和不相如。"]', '诗', 'shi', '', NULL, '緱氏拜陵迴道中呈李舍人少尹 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2419551b-8f63-4aec-b422-38c9a9f948a2', '陪韓院長韋河南同尋劉師不遇', '陪韓院长韋河南同尋劉師不遇', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["仙客誠難訪，吾人豈易同。","獨遊應駐景，相顧且吟風。","藥畹瓊枝秀，齋軒粉壁空。","不題三五字，何以達壺公。"]', '["仙客誠难訪，吾人豈易同。","独游應駐景，相顧且吟风。","藥畹瓊枝秀，斋軒粉壁空。","不題三五字，何以達壺公。"]', '诗', 'shi', '', NULL, '陪韓院長韋河南同尋劉師不遇 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa856f78-10a9-466e-92d9-12f439b59ed8', '送東光呂少府之官連帥奏授', '送东光呂少府之官連帥奏授', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["遠愛東光縣，平臨若木津。","一城見先日，百里早驚春。","德禮邀才重，恩輝拜命新。","幾時裁尺素，滄海有枯鱗。"]', '["远愛东光縣，平臨若木津。","一城见先日，百里早驚春。","德禮邀才重，恩輝拜命新。","幾时裁尺素，滄海有枯鱗。"]', '诗', 'shi', '', NULL, '送東光呂少府之官連帥奏授 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d84785-9ec0-41b1-baa8-f93cb3ceb566', '送劉公達判官赴天德軍幕', '送劉公達判官赴天德軍幕', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["特建青油幕，量分紫禁師。","自然知召子，不用問從誰。","文武輕車少，腥膻左袵衰。","北風如有寄，畫取受降時。"]', '["特建青油幕，量分紫禁師。","自然知召子，不用问從誰。","文武轻车少，腥膻左袵衰。","北风如有寄，畫取受降时。"]', '诗', 'shi', '', NULL, '送劉公達判官赴天德軍幕 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4065e8-4d17-4529-a2c8-21c76c592064', '故秘監丹陽郡公延陵包公挽歌', '故秘監丹陽郡公延陵包公挽歌', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["台鼎嘗虛位，夔龍莫致堯。","德音冥秘府，風韻散清朝。","天上文星落，林端玉樹凋。","有吳君子墓，返葬故山遙。"]', '["台鼎嘗虛位，夔龙莫致堯。","德音冥秘府，风韻散清朝。","天上文星落，林端玉樹凋。","有吳君子墓，返葬故山遙。"]', '诗', 'shi', '', NULL, '故秘監丹陽郡公延陵包公挽歌 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1f2b87d-3dc2-43de-bd75-ef631d40ed64', '望終南', '望終南', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["日愛南山好，時逢夏景殘。","白雲兼似雪，清晝乍生寒。","九陌峰如墜，千門翠可團。","欲知形勝盡，都在紫宸看。"]', '["日愛南山好，时逢夏景殘。","白云兼似雪，清晝乍生寒。","九陌峰如墜，千门翠可團。","欲知形勝尽，都在紫宸看。"]', '诗', 'shi', '', NULL, '望終南 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c95f5bef-8c3c-404d-a4f3-e988c44c3a10', '秋夕閑居對雨贈別盧七侍御坦', '秋夕闲居对雨贈別盧七侍御坦', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["燕燕辭巢蟬蛻枝，窮居積雨壞藩籬。","夜長簷霤寒無寢，日晏廚煙溼未炊。","悟主一言那可學，從軍五首竟徒爲。","故人驄馬朝天使，洛下秋聲恐要知。"]', '["燕燕辞巢蟬蛻枝，窮居積雨壞藩籬。","夜长簷霤寒無寢，日晏廚煙溼未炊。","悟主一言那可学，從軍五首竟徒爲。","故人驄马朝天使，洛下秋声恐要知。"]', '诗', 'shi', '', NULL, '秋夕閑居對雨贈別盧七侍御坦 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d16a02c-0acb-4699-9d56-1e421e73a01a', '晚過敷水驛却寄華州使院張鄭二侍御', '晚過敷水驛却寄华州使院張鄭二侍御', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["春雨如煙又若絲，曉來昏處晚晴時。","仙人掌上芙蓉沼，柱史關西松柏祠。","幾許歲華銷道路，無窮王事繫戎師。","迴瞻二妙非吾侶，日對三峰自有期。"]', '["春雨如煙又若絲，晓来昏处晚晴时。","仙人掌上芙蓉沼，柱史关西松柏祠。","幾許歲华銷道路，無窮王事繫戎師。","迴瞻二妙非吾侶，日对三峰自有期。"]', '诗', 'shi', '', NULL, '晚過敷水驛却寄華州使院張鄭二侍御 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b33fbf53-eaa8-4223-9712-933d8e4ce990', '洛下閑居夜晴觀雪寄四遠諸兄弟', '洛下闲居夜晴观雪寄四远諸兄弟', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["雪月相輝雲四開，終風助凍不揚埃。","萬重瓊樹宮中接，一直銀河天上來。","荆楚歲時知染翰，湘吳醇酎憶銜桮。","強題縑素無顏色，鴻雁南飛早晚迴。"]', '["雪月相輝云四开，終风助凍不揚埃。","万重瓊樹宮中接，一直銀河天上来。","荆楚歲时知染翰，湘吳醇酎憶銜桮。","強題縑素無顏色，鴻雁南飞早晚迴。"]', '诗', 'shi', '', NULL, '洛下閑居夜晴觀雪寄四遠諸兄弟 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8005e823-4697-4083-b629-431465a59833', '天津曉望因寄呈分司一二省郎', '天津晓望因寄呈分司一二省郎', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["萬乘西都去，千門正位虛。","鑿龍橫碧落，提象出華胥。","望幸宮嬪老，迎春海燕初。","保釐纔半仗，容衛盡空廬。","要自詞難擬，繇來畫不如。","散郎無所屬，聊事穆清居。"]', '["万乘西都去，千门正位虛。","鑿龙橫碧落，提象出华胥。","望幸宮嬪老，迎春海燕初。","保釐纔半仗，容衛尽空廬。","要自词难擬，繇来畫不如。","散郎無所屬，聊事穆清居。"]', '诗', 'shi', '', NULL, '天津曉望因寄呈分司一二省郎 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e6dc31-55cd-4633-bb6c-79a2ea520000', '早入朝書事', '早入朝书事', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["紫陌紛如畫，彤庭鬱未晨。","列星沈騎火，殘月暗車塵。","隱軫排霄翰，差池跨海鱗。","玉聲繁似樂，香澤散成春。","歎息驅羸馬，分明識故人。","一生三不遇，今作老郎身。"]', '["紫陌紛如畫，彤庭鬱未晨。","列星沈騎火，殘月暗车塵。","隐軫排霄翰，差池跨海鱗。","玉声繁似乐，香澤散成春。","歎息驱羸马，分明識故人。","一生三不遇，今作老郎身。"]', '诗', 'shi', '', NULL, '早入朝書事 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8522b687-c845-4d15-9e44-b60c3df77707', '元日喜聞大禮寄上翰林四學士中書六舍人二十韻', '元日喜闻大禮寄上翰林四学士中书六舍人二十韻', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["有事郊壇畢，無私日月臨。","歲華春更早，天瑞雪猶深。","玉輦迴時令，金門降德音。","翰飛鴛別侶，藂植桂爲林。","粉澤資鴻筆，薰和本素琴。","禮成戎器下，恩徹鬼方沈。","麟爵來稱紀，官師退絕箴。","道風黃閣靜，祥景紫垣陰。","壽酒朝時獻，農書夜直尋。","國香煴翠幄，庭燎赩紅衾。","漢魏文章盛，堯湯雨露霃。","密辭投水石，精義出沙金。","宸扆親唯敬，鈞衡近匪侵。","疾驅千里駿，清唳九霄禽。","慶賜迎新服，齋莊棄舊簪。","忽思班女怨，遙聽越人吟。","末路甘貧病，流年苦滯淫。","夢中青瑣闥，歸處碧山岑。","竊抃聞韶濩，觀光想韎任。","大哉環海晏，不笇子牟心。"]', '["有事郊壇畢，無私日月臨。","歲华春更早，天瑞雪猶深。","玉輦迴时令，金门降德音。","翰飞鴛別侶，藂植桂爲林。","粉澤資鴻笔，薰和本素琴。","禮成戎器下，恩徹鬼方沈。","麟爵来稱紀，官師退絕箴。","道风黄閣静，祥景紫垣陰。","壽酒朝时獻，農书夜直尋。","国香煴翠幄，庭燎赩紅衾。","漢魏文章盛，堯湯雨露霃。","密辞投水石，精義出沙金。","宸扆親唯敬，鈞衡近匪侵。","疾驱千里駿，清唳九霄禽。","慶賜迎新服，斋莊棄旧簪。","忽思班女怨，遙听越人吟。","末路甘貧病，流年苦滯淫。","梦中青瑣闥，归处碧山岑。","竊抃闻韶濩，观光想韎任。","大哉环海晏，不笇子牟心。"]', '诗', 'shi', '', NULL, '元日喜聞大禮寄上翰林四學士中書六舍人二十韻 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8771af-afaa-4d4e-b342-2c0f00c952c8', '奉使至邢州贈李八使君', '奉使至邢州贈李八使君', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["獨占龍岡部，深持虎節居。","盡心敷吏術，含笑掩兵書。","禮飾華纓重，才牽雅製餘。","茂陰延驛路，溫液逗官渠。","南畝行春罷，西樓待客初。","甕頭開綠蟻，砧下落紅魚。","牧伯風流足，輶軒若澀虛。","今宵鈴閣內，醉舞復何如。"]', '["独占龙岡部，深持虎節居。","尽心敷吏術，含笑掩兵书。","禮飾华纓重，才牽雅製餘。","茂陰延驛路，溫液逗官渠。","南畝行春罷，西楼待客初。","甕头开綠蟻，砧下落紅鱼。","牧伯风流足，輶軒若澀虛。","今宵鈴閣內，醉舞复何如。"]', '诗', 'shi', '', NULL, '奉使至邢州贈李八使君 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b09acbc-a3e5-46bf-ac39-37223c0650e8', '秋日洛陽官舍寄上水部家兄', '秋日洛陽官舍寄上水部家兄', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["洛陽歸老日，此縣忽爲君。","白髮兄仍見，丹誠帝豈聞。","九衢橫逝水，二室散浮雲。","屈指豪家盡，傷心要地分。","禁中周幾鼎，源上漢諸墳。","貔虎今無半，狐狸宿有羣。","威聲慙北部，仁化樂南薰。","野檗飢來食，天香靜處焚。","壯年唯喜酒，幼學便訶文。","及爾空衰暮，離憂詎可聞。"]', '["洛陽归老日，此縣忽爲君。","白髮兄仍见，丹誠帝豈闻。","九衢橫逝水，二室散浮云。","屈指豪家尽，傷心要地分。","禁中周幾鼎，源上漢諸墳。","貔虎今無半，狐狸宿有羣。","威声慙北部，仁化乐南薰。","野檗飢来食，天香静处焚。","壯年唯喜酒，幼学便訶文。","及爾空衰暮，離憂詎可闻。"]', '诗', 'shi', '', NULL, '秋日洛陽官舍寄上水部家兄 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9446507-663b-42d0-bc29-58689991d1a1', '李舍人少尹惠家醖一小榼立書絕句', '李舍人少尹惠家醖一小榼立书絕句', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["禁瑣天漿嫩，虞行夜月寒。","一瓢那可醉，應遣試嘗看。"]', '["禁瑣天漿嫩，虞行夜月寒。","一瓢那可醉，應遣試嘗看。"]', '诗', 'shi', '', NULL, '李舍人少尹惠家醖一小榼立書絕句 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44beac8-7a2b-46cc-80ba-d0d41254289a', '酬舍弟庠罷舉從州辟書', '酬舍弟庠罷舉從州辟书', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["之荆且願依劉表，折桂終慙見郄詵。","舍弟未應絲作鬢，園公不用印隨身。"]', '["之荆且願依劉表，折桂終慙见郄詵。","舍弟未應絲作鬢，园公不用印隨身。"]', '诗', 'shi', '', NULL, '酬舍弟庠罷舉從州辟書 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddc3023-f1f9-4dd4-9989-3659395f52a9', '奉酬楊侍郎十兄見贈之作', '奉酬楊侍郎十兄见贈之作', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["翠羽雕蟲日日新，翰林工部欲何神。","自悲由瑟無彈處，今作關西門下人。"]', '["翠羽雕蟲日日新，翰林工部欲何神。","自悲由瑟無彈处，今作关西门下人。"]', '诗', 'shi', '', NULL, '奉酬楊侍郎十兄見贈之作 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578f1206-f3b3-42b3-954a-5c3ce3e0a2c0', '杏園渡', '杏园渡', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["衛郊多壘少人家，南渡天寒日又斜。","君子素風悲已矣，杏園無復一枝花。"]', '["衛郊多壘少人家，南渡天寒日又斜。","君子素风悲已矣，杏园無复一枝花。"]', '诗', 'shi', '', NULL, '杏園渡 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f82dfe93-6197-41e4-a77e-a28f715fb498', '奉誠園聞笛', '奉誠园闻笛', 'd3c45bdd-a154-412f-bf28-ead7daaff891', '唐', '["曾絕朱纓吐錦茵，欲披荒草訪遺塵。","秋風忽灑西園淚，滿目山陽笛裏人。"]', '["曾絕朱纓吐錦茵，欲披荒草訪遺塵。","秋风忽灑西园泪，满目山陽笛裏人。"]', '诗', 'shi', '', NULL, '奉誠園聞笛 竇牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e24776-a971-4189-a7f0-58ddb785c778', '雪中遇直', '雪中遇直', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["寒光凝雪彩，限直居粉闈。","怳疑白雲上，乍覺金印非。","樹色靄虛空，琴聲諧素徽。","明晨阻通籍，獨臥挂朝衣。"]', '["寒光凝雪彩，限直居粉闈。","怳疑白云上，乍覺金印非。","樹色靄虛空，琴声諧素徽。","明晨阻通籍，独臥挂朝衣。"]', '诗', 'shi', '', NULL, '雪中遇直 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2992a9-fe55-4dfc-bde4-4c2493a0fc25', '東山月下懷友人', '东山月下懷友人', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["東山多喬木，月午始蒼蒼。","雖殊碧海狀，愛此青苔光。","高下滅華燭，參差啓洞房。","佳人夢餘思，寶瑟愁應商。","皎潔殊未已，沈吟限一方。","宦情哂雞口，世路倦羊腸。","彼美金石分，眷言蘭桂芳。","清暉詎同夕，耿耿但相望。"]', '["东山多喬木，月午始蒼蒼。","雖殊碧海狀，愛此青苔光。","高下滅华燭，參差啓洞房。","佳人梦餘思，寶瑟愁應商。","皎潔殊未已，沈吟限一方。","宦情哂雞口，世路倦羊腸。","彼美金石分，眷言蘭桂芳。","清暉詎同夕，耿耿但相望。"]', '诗', 'shi', '', NULL, '東山月下懷友人 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea240e7-663a-46c5-894c-e4f529973650', '時興', '时兴', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["夙心曠何許，日暮依林薄。","流水不待人，孤雲時映鶴。","濛濛千萬花，曷爲神仙藥。","不遇爛柯叟，報非舊城郭。"]', '["夙心曠何許，日暮依林薄。","流水不待人，孤云时映鹤。","濛濛千万花，曷爲神仙藥。","不遇爛柯叟，報非旧城郭。"]', '诗', 'shi', '', NULL, '時興 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bee2ca-10c5-498b-b577-83265df106c2', '題劍', '題劍', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["丈夫得寶劍，束髮曾書紳。","嗟吁一朝遇，願言千載鄰。","心許留家樹，辭直斷佞臣。","焉能爲繞指，拂拭試時人。"]', '["丈夫得寶劍，束髮曾书紳。","嗟吁一朝遇，願言千載鄰。","心許留家樹，辞直斷佞臣。","焉能爲繞指，拂拭試时人。"]', '诗', 'shi', '', NULL, '題劍 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270bbb78-6460-4d68-82eb-007dd6208f36', '黔中書事', '黔中书事', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["萬事非京國，千山擁麗譙。","佩刀看日曬，賜馬傍江調。","言語多重譯，壺觴每獨謠。","沿流如著翅，不敢問歸橈。"]', '["万事非京国，千山擁丽譙。","佩刀看日曬，賜马傍江調。","言語多重譯，壺觴每独謠。","沿流如著翅，不敢问归橈。"]', '诗', 'shi', '', NULL, '黔中書事 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aea5068-c4f2-42ef-9632-69d4ad6c4ad0', '冬日曉思寄楊二十七鍊師', '冬日晓思寄楊二十七鍊師', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["雨霜地如雪，松桂青參差。","鶴警晨光上，步出南軒時。","所遇各有適，我懷亦自怡。","願言緘素封，昨夜夢瓊枝。"]', '["雨霜地如雪，松桂青參差。","鹤警晨光上，步出南軒时。","所遇各有適，我懷亦自怡。","願言緘素封，昨夜梦瓊枝。"]', '诗', 'shi', '', NULL, '冬日曉思寄楊二十七鍊師 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d952ff-d24d-4920-86ac-54e2f1404375', '貞元末東院嘗接事今西川武相公于茲三周謬領中憲徘徊廳宇多獲文篇夏日即事因寄四韻', '貞元末东院嘗接事今西川武相公于茲三周謬領中憲徘徊廳宇多獲文篇夏日即事因寄四韻', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["重軒深似谷，列柏鎮含烟。","境絕蒼蠅到，風生白雪前。","彈冠驚迹近，專席感恩偏。","霄漢朝來下，油幢路幾千。"]', '["重軒深似谷，列柏鎮含烟。","境絕蒼蠅到，风生白雪前。","彈冠驚迹近，專席感恩偏。","霄漢朝来下，油幢路幾千。"]', '诗', 'shi', '', NULL, '貞元末東院嘗接事今西川武相公于茲三周謬領中憲徘徊廳宇多獲文篇夏日即事因寄四韻 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f4c1c5-eeb2-4918-b703-19e76a1b4453', '北地', '北地', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["何事到容州，臨池照白頭。","興隨年已往，愁與水長流。","僶俯思逋客，辛勤悔飯牛。","詩人亦何意，樹草欲忘憂。"]', '["何事到容州，臨池照白头。","兴隨年已往，愁與水长流。","僶俯思逋客，辛勤悔飯牛。","诗人亦何意，樹草欲忘憂。"]', '诗', 'shi', '', NULL, '北地 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299e5b62-1036-4f99-83b5-c0759f2fadfa', '雨後月下寄懷羊二十七資州', '雨後月下寄懷羊二十七資州', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["夕霽涼飆至，翛然心賞諧。","清光松上月，虛白郡中齋。","置酒平生在，開衿願見乖。","殷勤寄雙鯉，夢想入君懷。"]', '["夕霽涼飆至，翛然心賞諧。","清光松上月，虛白郡中斋。","置酒平生在，开衿願见乖。","殷勤寄雙鯉，梦想入君懷。"]', '诗', 'shi', '', NULL, '雨後月下寄懷羊二十七資州 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27acd4eb-d234-4bda-8d30-78c86004f0b6', '奉酬西川武相公晨興贈友見示之作', '奉酬西川武相公晨兴贈友见示之作', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["碧樹分曉色，宿雨弄清光。","猶聞子規啼，獨念一聲長。","眷眷軫芳思，依依寄遠方。","情同如蘭臭，惠比返魂香。","新什驚變雅，古瑟代沈湘。","殷勤見知己，掩抑繞中腸。","隙駟不我待，路人易相忘。","孤老空許國，幽報期蒼蒼。"]', '["碧樹分晓色，宿雨弄清光。","猶闻子規啼，独念一声长。","眷眷軫芳思，依依寄远方。","情同如蘭臭，惠比返魂香。","新什驚变雅，古瑟代沈湘。","殷勤见知己，掩抑繞中腸。","隙駟不我待，路人易相忘。","孤老空許国，幽報期蒼蒼。"]', '诗', 'shi', '', NULL, '奉酬西川武相公晨興贈友見示之作 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50c0aa1-9b96-4b81-a58d-5cb371a84d3c', '晨游昌師院', '晨游昌師院', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["深庭芳草濃，曉井山泉溢。","林馥亂沈煙，石潤侵經室。","幽巖鳥飛靜，晴嶺雲歸密。","壁蘚凝蒼華，竹陰滿晴日。","生期半宵夢，憂緒仍非一。","若無高世心，安能此終畢。"]', '["深庭芳草濃，晓井山泉溢。","林馥亂沈煙，石潤侵經室。","幽巖鸟飞静，晴嶺云归密。","壁蘚凝蒼华，竹陰满晴日。","生期半宵梦，憂緒仍非一。","若無高世心，安能此終畢。"]', '诗', 'shi', '', NULL, '晨游昌師院 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7a392e-edb9-45cf-b88b-8766ca8d1f73', '同王晦伯朱遐景宿慧山寺', '同王晦伯朱遐景宿慧山寺', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["共訪青山寺，曾隱南朝人。","問古松桂老，開襟言笑新。","步移月亦出，水映石磷磷。","予洗腸中酒，君濯纓上塵。","皓彩入幽抱，清氣逼蒼旻。","信此澹忘歸，淹留冰玉鄰。"]', '["共訪青山寺，曾隐南朝人。","问古松桂老，开襟言笑新。","步移月亦出，水映石磷磷。","予洗腸中酒，君濯纓上塵。","皓彩入幽抱，清氣逼蒼旻。","信此澹忘归，淹留冰玉鄰。"]', '诗', 'shi', '', NULL, '同王晦伯朱遐景宿慧山寺 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d612e9ac-acf9-40b8-a512-5aba64e89f16', '草堂夜坐', '草堂夜坐', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["匣中三尺劍，天上少微星。","勿謂相去遠，壯心曾不停。"]', '["匣中三尺劍，天上少微星。","勿謂相去远，壯心曾不停。"]', '诗', 'shi', '', NULL, '草堂夜坐 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f44085-e123-4f12-b74a-612d79a6439a', '經潼關贈宇文十', '經潼关贈宇文十', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["古有弓旌禮，今徴草澤臣。","方同白衣見，不是棄繻人。"]', '["古有弓旌禮，今徴草澤臣。","方同白衣见，不是棄繻人。"]', '诗', 'shi', '', NULL, '經潼關贈宇文十 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dd24d0-ec1c-4ebf-acaf-b6a269a1cfaf', '觀畫鶴', '观畫鹤', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["華亭不相識，衛國復誰知。","悵望沖天羽，甘心任畫師。"]', '["华亭不相識，衛国复誰知。","悵望沖天羽，甘心任畫師。"]', '诗', 'shi', '', NULL, '觀畫鶴 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ece60a-ead8-4699-a3fc-827e0090c01a', '晚自臺中歸永寧里南望山色悵然有懷呈上右司十一兄', '晚自台中归永寧里南望山色悵然有懷呈上右司十一兄', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["白髮侵侵生有涯，青襟曾愛紫河車。","自憐悟主難歸去，馬上看山恐到家。"]', '["白髮侵侵生有涯，青襟曾愛紫河车。","自怜悟主难归去，马上看山恐到家。"]', '诗', 'shi', '', NULL, '晚自臺中歸永寧里南望山色悵然有懷呈上右司十一兄 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaff274b-27a4-423b-81c4-cf978e8238e9', '中牟縣經魯公廟', '中牟縣經魯公廟', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["青史編名在篋中，故林遺廟揖仁風。","還將文字如顏色，暫下蒲車爲魯公。"]', '["青史編名在篋中，故林遺廟揖仁风。","還將文字如顏色，暫下蒲车爲魯公。"]', '诗', 'shi', '', NULL, '中牟縣經魯公廟 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca632d53-d4c4-41c3-a8e7-82f9c48cfd29', '初入諫司喜家室至', '初入諫司喜家室至', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["一旦悲歡見孟光，十年辛苦伴滄浪。","不知筆硯緣封事，猶問傭書日幾行。"]', '["一旦悲歡见孟光，十年辛苦伴滄浪。","不知笔硯緣封事，猶问傭书日幾行。"]', '诗', 'shi', '', NULL, '初入諫司喜家室至 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba98bbbe-d045-47a4-a5f5-71e6774a7f10', '春雨', '春雨', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["昨日偷閑看花了，今朝多雨奈人何。","人間盡似逢花雨，莫愛芳菲濕綺羅。"]', '["昨日偷闲看花了，今朝多雨奈人何。","人间尽似逢花雨，莫愛芳菲濕綺羅。"]', '诗', 'shi', '', NULL, '春雨 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6823906c-1d26-47d6-9c5b-7b32f9c222f6', '送內弟袁德師', '送內弟袁德師', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["南渡登州即水仙，西垣有客思悠然。","因君相問爲官意，不賣毗陵負郭田。"]', '["南渡登州即水仙，西垣有客思悠然。","因君相问爲官意，不賣毗陵負郭田。"]', '诗', 'shi', '', NULL, '送內弟袁德師 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec2fe12-1ce8-4362-a646-3ad851f606b8', '贈劉大兄院長', '贈劉大兄院长', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["萬年枝下昔同趨，三事行中半已無。","路自長沙忽相見，共驚雙鬢別來殊。"]', '["万年枝下昔同趨，三事行中半已無。","路自长沙忽相见，共驚雙鬢別来殊。"]', '诗', 'shi', '', NULL, '贈劉大兄院長 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36303fd2-798f-45a4-998b-8da64a9b592d', '假日尋花', '假日尋花', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["武陵緣源不可到，河陽帶縣詎堪誇。","枝枝如雪南關外，一日休閑盡屬花。"]', '["武陵緣源不可到，河陽带縣詎堪誇。","枝枝如雪南关外，一日休闲尽屬花。"]', '诗', 'shi', '', NULL, '假日尋花 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2d5516-1205-4cd7-ad75-85146f5f0e3d', '自京將赴黔南', '自京將赴黔南', '7f4cfa1b-8f9d-4a63-aaf7-7a931b3ab97e', '唐', '["風雨荆州二月天，問人初雇峽中船。","西南一望雲和水，猶道黔南有四千。"]', '["风雨荆州二月天，问人初雇峽中船。","西南一望云和水，猶道黔南有四千。"]', '诗', 'shi', '', NULL, '自京將赴黔南 竇羣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b8aff6-0170-45b7-8962-49cd4e6d46f3', '留守府酬皇甫曙侍御彈琴之什', '留守府酬皇甫曙侍御彈琴之什', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["青瑣晝無塵，碧梧陰似水。","高張朱弦琴，靜舉白玉指。","洞簫又奏繁，寒磬一聲起。","鶴警風露中，泉飛雪雲裏。","泠泠分雅鄭，析析諧宮徵。","座客無俗心，巢禽亦傾耳。","衛國知有人，齊竽偶相齒。","有時趨絳紗，盡日隨朱履。","那令雜繁手，出假求焦尾。","幾載遺正音，今朝自君始。"]', '["青瑣晝無塵，碧梧陰似水。","高張朱弦琴，静舉白玉指。","洞簫又奏繁，寒磬一声起。","鹤警风露中，泉飞雪云裏。","泠泠分雅鄭，析析諧宮徵。","座客無俗心，巢禽亦傾耳。","衛国知有人，齊竽偶相齒。","有时趨絳紗，尽日隨朱履。","那令杂繁手，出假求焦尾。","幾載遺正音，今朝自君始。"]', '诗', 'shi', '', NULL, '留守府酬皇甫曙侍御彈琴之什 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7408655a-9045-4e1d-8602-a6e9930dda7e', '金山行', '金山行', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["西江中𤃩波四截，湧出一峰青堞㙞。","外如削成中缺裂，陽氣發生陰氣結。","是時炎天五六月，上有火雲下冰雪。","夜色晨光相蕩沃，積翠流霞滿坑谷。","龍泓徹底沙布金，鳥道插雲梯甃玉。","架險凌虛隨指顧，榱桷玲瓏皆固護。","斡流倒景不可窺，萬仞千崖生跬步。","日華重重上金牓，丹楹碧砌真珠網。","此時天海風浪清，吳楚萬家皆在掌。","瓊樓菌閣紛明媚，曲檻迴軒深且邃。","海鳥夜上珊瑚枝，江花曉落瑠璃地。","有時倒影沈江底，萬狀分明光似洗。","不知水上有樓臺，却就波中看閉啓。","舟人忘却江水深，水神誤到人間世。","歘然風生波出沒，瀖濩晶瑩無定物。","居人相顧非人間，如到日宮經月窟。","信知靈景長有靈，住者不得無仙骨。","三神山上蓬萊宮，徒有丹青人未逢。","何如此處靈山宅，清涼不與囂塵隔。","曾到金山處處行，夢魂長羨金山客。"]', '["西江中𤃩波四截，湧出一峰青堞㙞。","外如削成中缺裂，陽氣發生陰氣結。","是时炎天五六月，上有火云下冰雪。","夜色晨光相蕩沃，積翠流霞满坑谷。","龙泓徹底沙布金，鸟道插云梯甃玉。","架險凌虛隨指顧，榱桷玲瓏皆固護。","斡流倒景不可窺，万仞千崖生跬步。","日华重重上金牓，丹楹碧砌真珠網。","此时天海风浪清，吳楚万家皆在掌。","瓊楼菌閣紛明媚，曲檻迴軒深且邃。","海鸟夜上珊瑚枝，江花晓落瑠璃地。","有时倒影沈江底，万狀分明光似洗。","不知水上有楼台，却就波中看閉啓。","舟人忘却江水深，水神誤到人间世。","歘然风生波出沒，瀖濩晶瑩無定物。","居人相顧非人间，如到日宮經月窟。","信知靈景长有靈，住者不得無仙骨。","三神山上蓬萊宮，徒有丹青人未逢。","何如此处靈山宅，清涼不與囂塵隔。","曾到金山处处行，梦魂长羨金山客。"]', '诗', 'shi', '', NULL, '金山行 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3368a8d5-11ac-41ab-92d4-c7327b2d9c42', '于闐鐘歌送靈徹上人歸越', '于闐鐘歌送靈徹上人归越', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["海中有國傾神功，烹金化成九乳鐘。","精氣激射聲沖瀜，護持海底諸魚龍。","聲有感，神無方，連天雲水無津梁。","不知飛在靈嘉寺，一國之人皆若狂。","東南之美天下傳，環文萬象無雕鐫。","有靈飛動不敢懸，鎖在危樓五百年。","有時清秋日正中，繁霜滿地天無風。","一聲洞徹八音盡，萬籟悄然星漢空。","徒言凡質千鈞重，一夫之力能振動。","大鳴小鳴須在君，不撃不考終不聞。","高僧訪古稽山曲，終日當之言不足。","手提文鋒百鍊成，恐刜此鐘無一聲。"]', '["海中有国傾神功，烹金化成九乳鐘。","精氣激射声沖瀜，護持海底諸鱼龙。","声有感，神無方，連天云水無津梁。","不知飞在靈嘉寺，一国之人皆若狂。","东南之美天下傳，环文万象無雕鐫。","有靈飞动不敢懸，鎖在危楼五百年。","有时清秋日正中，繁霜满地天無风。","一声洞徹八音尽，万籟悄然星漢空。","徒言凡質千鈞重，一夫之力能振动。","大鳴小鳴須在君，不撃不考終不闻。","高僧訪古稽山曲，終日當之言不足。","手提文鋒百鍊成，恐刜此鐘無一声。"]', '诗', 'shi', '', NULL, '于闐鐘歌送靈徹上人歸越 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abbe283c-9c0d-41e4-a4e2-864f693b8389', '太原送穆質南遊', '太原送穆質南游', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["今朝天景清，秋入晉陽城。","露葉離披處，風蟬三數聲。","那言苦行役，值此遠徂征。","莫話心中事，相看氣不平。"]', '["今朝天景清，秋入晉陽城。","露葉離披处，风蟬三數声。","那言苦行役，值此远徂征。","莫話心中事，相看氣不平。"]', '诗', 'shi', '', NULL, '太原送穆質南遊 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09d57f9-e7ee-4088-8cf0-06423f1dede0', '四皓驛聽琴送王師簡歸湖南使幕', '四皓驛听琴送王師簡归湖南使幕', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["朱弦韻正調，清夜似聞韶。","山館月猶在，松枝雪未消。","城笳三奏曉，別鶴一聲遙。","明日思君處，春泉翻寂寥。"]', '["朱弦韻正調，清夜似闻韶。","山館月猶在，松枝雪未消。","城笳三奏晓，別鹤一声遙。","明日思君处，春泉翻寂寥。"]', '诗', 'shi', '', NULL, '四皓驛聽琴送王師簡歸湖南使幕 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd4fddc-e8e9-4168-aafa-f619edab62bb', '夜行古戰場', '夜行古戰場', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["山斷塞初平，人言古戰庭。","泉冰聲更咽，陰火燄偏青。","月落雲沙黑，風迴草木腥。","不知秦與漢，徒欲弔英靈。"]', '["山斷塞初平，人言古戰庭。","泉冰声更咽，陰火燄偏青。","月落云沙黑，风迴草木腥。","不知秦與漢，徒欲弔英靈。"]', '诗', 'shi', '', NULL, '夜行古戰場 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d843e05-dc54-4fd9-beb9-44f188b596b3', '奉和王侍郎春日喜李侍郎崔給諫張舍人韋諫議見訪因命觴觀樂之什', '奉和王侍郎春日喜李侍郎崔給諫張舍人韋諫議见訪因命觴观乐之什', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["華館遲嘉賓，逢迎淑景新。","錦筵開絳帳，玉佩下朱輪。","曲裏三仙會，風前百囀春。","欲知忘味處，共仰在齊人。"]', '["华館遲嘉賓，逢迎淑景新。","錦筵开絳帳，玉佩下朱輪。","曲裏三仙會，风前百囀春。","欲知忘味处，共仰在齊人。"]', '诗', 'shi', '', NULL, '奉和王侍郎春日喜李侍郎崔給諫張舍人韋諫議見訪因命觴觀樂之什 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf98fca8-9bf1-4af4-bd35-e51bfe7f09ed', '酬謝韋卿二十五兄俯贈輙敢書情', '酬謝韋卿二十五兄俯贈輙敢书情', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["大賢持贈一明璫，蓬蓽初驚滿室光。","埋沒劍中生紫氣，塵埃瑟上動清商。","荆山璞在終應識，楚國人知不是狂。","莫恨伏轅身未老，會將筋力是王良。"]', '["大賢持贈一明璫，蓬蓽初驚满室光。","埋沒劍中生紫氣，塵埃瑟上动清商。","荆山璞在終應識，楚国人知不是狂。","莫恨伏轅身未老，會將筋力是王良。"]', '诗', 'shi', '', NULL, '酬謝韋卿二十五兄俯贈輙敢書情 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73580ea1-a063-4466-8b63-0de5df05f082', '奉酬侍御家兄東洛閑居夜晴觀雪之什', '奉酬侍御家兄东洛闲居夜晴观雪之什', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["洛陽宮觀與天齊，雪淨雲消月未西。","清淺乍分銀漢近，輝光漸覺玉繩低。","綠醽乍熟堪聊酌，黃竹篇成好命題。","應念武關山斷處，空愁簿領候晨雞。"]', '["洛陽宮观與天齊，雪淨云消月未西。","清淺乍分銀漢近，輝光漸覺玉繩低。","綠醽乍熟堪聊酌，黄竹篇成好命題。","應念武关山斷处，空愁簿領候晨雞。"]', '诗', 'shi', '', NULL, '奉酬侍御家兄東洛閑居夜晴觀雪之什 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b84e662-24d1-458b-b941-6292d4cebfd3', '勅目至家兄蒙淮南僕射杜公奏授祕校兼節度參謀同書寄上', '勅目至家兄蒙淮南僕射杜公奏授祕校兼節度參謀同书寄上', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["朝市三千里，園廬二十春。","步兵終日飲，原憲四時貧。","桂樹留人久，蓬山入夢新。","鶴書承處重，鵲語喜時頻。","草奏才偏委，嘉謀事最親。","榻因徐孺解，醴爲穆生陳。","衛國今多士，荆州好寄身。","煙霄定從此，非假問陶鈞。"]', '["朝市三千里，园廬二十春。","步兵終日饮，原憲四时貧。","桂樹留人久，蓬山入梦新。","鹤书承处重，鵲語喜时頻。","草奏才偏委，嘉謀事最親。","榻因徐孺解，醴爲穆生陳。","衛国今多士，荆州好寄身。","煙霄定從此，非假问陶鈞。"]', '诗', 'shi', '', NULL, '勅目至家兄蒙淮南僕射杜公奏授祕校兼節度參謀同書寄上 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ffa746-f851-44c4-8c0d-03c652af0c08', '酬韓愈侍郎登岳陽樓見贈', '酬韓愈侍郎登岳陽楼见贈', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["巨浸連空闊，危樓在杳冥。","稍分巴子國，欲近老人星。","昏旦呈新候，川原按舊經。","地圖封七澤，天限鎖重扃。","萬象皆歸掌，三光豈遁形。","月車纔碾浪，日御已翻溟。","落照金成柱，餘霞翠擁屏。","夜光疑漢曲，寒韻辨湘靈。","山晚雲常碧，湖春草徧青。","軒黃曾舉樂，范蠡幾揚舲。","有客初留鷁，貪程尚數蓂。","自當徐孺榻，不是謝公亭。","雅論冰生水，雄材刃發硎。","座中瓊玉潤，名下茝蘭馨。","假手誠知拙，齋心匪蹔寧。","每慙公府粟，却憶故山苓。","苦調當三歎，知音願一聽。","自悲由也瑟，敢墜孔悝銘。","野杏初成雪，松醪正滿瓶。","莫辭今日醉，長恨古人醒。"]', '["巨浸連空闊，危楼在杳冥。","稍分巴子国，欲近老人星。","昏旦呈新候，川原按旧經。","地圖封七澤，天限鎖重扃。","万象皆归掌，三光豈遁形。","月车纔碾浪，日御已翻溟。","落照金成柱，餘霞翠擁屏。","夜光疑漢曲，寒韻辨湘靈。","山晚云常碧，湖春草徧青。","軒黄曾舉乐，范蠡幾揚舲。","有客初留鷁，貪程尚數蓂。","自當徐孺榻，不是謝公亭。","雅論冰生水，雄材刃發硎。","座中瓊玉潤，名下茝蘭馨。","假手誠知拙，斋心匪蹔寧。","每慙公府粟，却憶故山苓。","苦調當三歎，知音願一听。","自悲由也瑟，敢墜孔悝銘。","野杏初成雪，松醪正满瓶。","莫辞今日醉，长恨古人醒。"]', '诗', 'shi', '', NULL, '酬韓愈侍郎登岳陽樓見贈 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737b0475-54f2-49b9-98a4-818210c1daa3', '東都嘉量亭獻留守韓僕射', '东都嘉量亭獻留守韓僕射', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["卜築三川上，儀刑萬井中。","度材垂後儉，選勝揜前功。","雲構中央起，煙波四面通。","乍疑游汗漫，稍似入崆垌。","廛閈高低盡，山河表裏窮。","峰戀從地碧，宮觀倚天紅。","靈檻如朝蜃，飛橋狀晚虹。","曙霞晴錯落，夕靄溼葱蘢。","庾亮樓何阨，陳蕃榻更崇。","有時閑講德，永日靜觀風。","玉斝飛無算，金鐃奏未終。","重筵開玳瑁，上客集鵷鴻。","接武空慙蹇，修文敢並雄。","豈須登峴首，然後奉羊公。"]', '["卜築三川上，儀刑万井中。","度材垂後儉，選勝揜前功。","云構中央起，煙波四面通。","乍疑游汗漫，稍似入崆垌。","廛閈高低尽，山河表裏窮。","峰戀從地碧，宮观倚天紅。","靈檻如朝蜃，飞橋狀晚虹。","曙霞晴錯落，夕靄溼葱蘢。","庾亮楼何阨，陳蕃榻更崇。","有时闲講德，永日静观风。","玉斝飞無算，金鐃奏未終。","重筵开玳瑁，上客集鵷鴻。","接武空慙蹇，修文敢並雄。","豈須登峴首，然後奉羊公。"]', '诗', 'shi', '', NULL, '東都嘉量亭獻留守韓僕射 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b12556-e0ae-4efc-b04d-ff84c2a9510a', '段都尉別業', '段都尉別業', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["曾識將軍段匹磾，幾場花下醉如泥。","春來欲問林園主，桃李無言鳥自啼。"]', '["曾識將軍段匹磾，幾場花下醉如泥。","春来欲问林园主，桃李無言鸟自啼。"]', '诗', 'shi', '', NULL, '段都尉別業 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0a32a7d-3522-42e4-be72-40eddf5786c2', '靈臺鎮贈丘岑中丞', '靈台鎮贈丘岑中丞', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["曉日天山雪半晴，紅旗遙識漢家營。","近來胡騎休南牧，羊馬城邊春草生。"]', '["晓日天山雪半晴，紅旗遙識漢家營。","近来胡騎休南牧，羊马城邊春草生。"]', '诗', 'shi', '', NULL, '靈臺鎮贈丘岑中丞 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ef108b-0a12-4a43-81bd-6ac8343e9005', '贈道芬上人', '贈道芬上人', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["雲濕烟封不可闚，畫時唯有鬼神知。","幾回逢著天台客，認得巖西最老枝。"]', '["云濕烟封不可闚，畫时唯有鬼神知。","幾回逢著天台客，認得巖西最老枝。"]', '诗', 'shi', '', NULL, '贈道芬上人 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fea221b-ed32-4a50-96f3-41051ad17d74', '金山寺', '金山寺', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["一點青螺白浪中，全依水府與天通。","晴江萬里雲飛盡，鼇背參差日氣紅。"]', '["一点青螺白浪中，全依水府與天通。","晴江万里云飞尽，鼇背參差日氣紅。"]', '诗', 'shi', '', NULL, '金山寺 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4b7a12f-e8cf-4b33-80c4-721c2ed298e5', '冬夜寓懷寄王翰林', '冬夜寓懷寄王翰林', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["滿地霜蕪葉下枝，幾回吟斷四愁詩。","漢家若欲論封禪，須及相如未病時。"]', '["满地霜蕪葉下枝，幾回吟斷四愁诗。","漢家若欲論封禪，須及相如未病时。"]', '诗', 'shi', '', NULL, '冬夜寓懷寄王翰林 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818b27fd-fde0-41c4-a105-34ccf37b714c', '醉中贈符載', '醉中贈符載', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["白社會中嘗共醉，青雲路上未相逢。","時人莫小池中水，淺處無妨有臥龍。"]', '["白社會中嘗共醉，青云路上未相逢。","时人莫小池中水，淺处無妨有臥龙。"]', '诗', 'shi', '', NULL, '醉中贈符載 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ceffd6-17ec-4943-a65a-44722d53b32c', '龍門看花', '龙门看花', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["無葉無枝不見空，連天撲地逕纔通。","山鶯驚起酒醒處，火焰燒人雪噴風。"]', '["無葉無枝不见空，連天撲地逕纔通。","山鶯驚起酒醒处，火焰燒人雪噴风。"]', '诗', 'shi', '', NULL, '龍門看花 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb57fa4-2bb1-461a-9a25-608fcd7d98aa', '陪留守韓僕射巡內至上陽宮感興二首 一', '陪留守韓僕射巡內至上陽宮感兴二首 一', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["翠輦西歸七十春，玉堂珠綴儼埃塵。","武皇弓劍埋何處，泣問上陽宮裏人。"]', '["翠輦西归七十春，玉堂珠綴儼埃塵。","武皇弓劍埋何处，泣问上陽宮裏人。"]', '诗', 'shi', '', NULL, '陪留守韓僕射巡內至上陽宮感興二首 一 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c65d95-22c0-4a97-8d8f-6751499e441f', '陪留守韓僕射巡內至上陽宮感興二首 二', '陪留守韓僕射巡內至上陽宮感兴二首 二', '9c8ba333-e2be-4c6f-904e-dfe62af76af8', '唐', '["愁雲漠漠草離離，太乙句陳處處疑。","薄暮毀垣春雨裏，殘花猶發萬年枝。"]', '["愁云漠漠草離離，太乙句陳处处疑。","薄暮毀垣春雨裏，殘花猶發万年枝。"]', '诗', 'shi', '', NULL, '陪留守韓僕射巡內至上陽宮感興二首 二 竇庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00b60a6-b250-4976-a73f-7a9e9143cada', '老將行', '老將行', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["烽煙猶未盡，年鬢暗相催。","輕敵心空在，彎弓手不開。","馬依秋草病，柳傍故營摧。","唯有酬恩客，時聽說劍來。"]', '["烽煙猶未尽，年鬢暗相催。","轻敵心空在，彎弓手不开。","马依秋草病，柳傍故營摧。","唯有酬恩客，时听说劍来。"]', '诗', 'shi', '', NULL, '老將行 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd23478-6266-4d6d-8512-2452ab78454d', '贈蕭都官', '贈蕭都官', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["蕭郎自小賢，愛客不言錢。","有酒輕寒夜，無愁倚少年。","閑尋織錦字，醉上看花船。","好是關身事，從人道性偏。"]', '["蕭郎自小賢，愛客不言錢。","有酒轻寒夜，無愁倚少年。","闲尋织錦字，醉上看花船。","好是关身事，從人道性偏。"]', '诗', 'shi', '', NULL, '贈蕭都官 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e12accc-65d0-4e58-8e96-92fc7ebe74e7', '忝職武昌初至夏口書事獻府主相公', '忝職武昌初至夏口书事獻府主相公', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["白髮放橐鞬，梁王愛舊全。","竹籬江畔宅，梅雨病中天。","時奉登樓讌，閑脩上水船。","邑人興謗易，莫遣鶴支錢。"]', '["白髮放橐鞬，梁王愛旧全。","竹籬江畔宅，梅雨病中天。","时奉登楼讌，闲脩上水船。","邑人兴謗易，莫遣鹤支錢。"]', '诗', 'shi', '', NULL, '忝職武昌初至夏口書事獻府主相公 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a76d057-df50-42d3-982c-130b2714cfa9', '早秋江行', '早秋江行', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["迴望湓城遠，西風吹荻花。","暮潮江勢闊，秋雨鴈行斜。","多醉渾無夢，頻愁欲到家。","漸驚雲樹轉，數點是晨鵶。"]', '["迴望湓城远，西风吹荻花。","暮潮江勢闊，秋雨鴈行斜。","多醉渾無梦，頻愁欲到家。","漸驚云樹轉，數点是晨鵶。"]', '诗', 'shi', '', NULL, '早秋江行 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c94fe3c3-46bd-4078-84d6-7a3736a1da9d', '題任處士幽居', '題任处士幽居', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["紅葉江邨夕，孤煙草舍貧。","水清魚識釣，林靜犬隨人。","採掇山無主，扶持藥有神。","客來唯勸酒，蝴蝶是前身。"]', '["紅葉江邨夕，孤煙草舍貧。","水清鱼識釣，林静犬隨人。","採掇山無主，扶持藥有神。","客来唯勸酒，蝴蝶是前身。"]', '诗', 'shi', '', NULL, '題任處士幽居 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af111f10-be8c-49d8-81ae-66c0ecc9b1bb', '漢陰驛與宇文十相遇旋歸西川因以贈別', '漢陰驛與宇文十相遇旋归西川因以贈別', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["吳蜀何年別，相逢漢水頭。","望鄉心共醉，握手淚先流。","宿霧千山曉，春霖一夜愁。","離情方浩蕩，莫說去刀州。"]', '["吳蜀何年別，相逢漢水头。","望乡心共醉，握手泪先流。","宿霧千山晓，春霖一夜愁。","離情方浩蕩，莫说去刀州。"]', '诗', 'shi', '', NULL, '漢陰驛與宇文十相遇旋歸西川因以贈別 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec72e2d-aafc-455e-9c50-9c9025ebbddc', '早春松江野望', '早春松江野望', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["江邨風雪霽，曉望忽驚春。","畊地人來早，營巢鵲語頻。","帶花移樹小，插槿作籬新。","何事勝無事，窮通任此身。"]', '["江邨风雪霽，晓望忽驚春。","畊地人来早，營巢鵲語頻。","带花移樹小，插槿作籬新。","何事勝無事，窮通任此身。"]', '诗', 'shi', '', NULL, '早春松江野望 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8567a02f-6dcb-40a7-9b31-0bb9dacc08fc', '少婦詞', '少婦词', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["坐惜年光變，遼陽信未通。","燕迷新畫屋，春識舊花叢。","夢繞天山外，愁翻錦字中。","昨來誰是伴，鸚鵡在簾櫳。"]', '["坐惜年光变，遼陽信未通。","燕迷新畫屋，春識旧花叢。","梦繞天山外，愁翻錦字中。","昨来誰是伴，鸚鵡在簾櫳。"]', '诗', 'shi', '', NULL, '少婦詞 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('033addbc-9038-41fb-b22b-b342d3125092', '歲晚喜遠兄弟至書情', '歲晚喜远兄弟至书情', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["幾年滄海別，相見竟多違。","鬢髮緣愁白，音書爲嬾稀。","新詩徒有贈，故國未同歸。","人事那堪問，無言是與非。"]', '["幾年滄海別，相见竟多違。","鬢髮緣愁白，音书爲嬾稀。","新诗徒有贈，故国未同归。","人事那堪问，無言是與非。"]', '诗', 'shi', '', NULL, '歲晚喜遠兄弟至書情 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f29c7073-7f1c-4772-8f5d-348fe1f71d79', '登玉鈎亭奉獻淮南李相公', '登玉鈎亭奉獻淮南李相公', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["西南城上高高處，望月分明似玉鈎。","朱檻人雲看鳥滅，綠楊如薺遶江流。","定知有客嫌陳榻，從此無人上庾樓。","今日卷簾天氣好，不勞騎馬看揚州。"]', '["西南城上高高处，望月分明似玉鈎。","朱檻人云看鸟滅，綠楊如薺遶江流。","定知有客嫌陳榻，從此無人上庾楼。","今日卷簾天氣好，不勞騎马看揚州。"]', '诗', 'shi', '', NULL, '登玉鈎亭奉獻淮南李相公 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6bf3b29-a210-4644-9ac4-51c39dac7751', '南陽道中作', '南陽道中作', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["東風雨洗順陽川，蜀錦花開綠草田。","彩雉鬬時頻駐馬，酒旗翻處亦留錢。","新晴日照山頭雪，薄暮人爭渡口船。","早晚到家春欲盡，今年寒食月初圓。"]', '["东风雨洗順陽川，蜀錦花开綠草田。","彩雉鬬时頻駐马，酒旗翻处亦留錢。","新晴日照山头雪，薄暮人爭渡口船。","早晚到家春欲尽，今年寒食月初圓。"]', '诗', 'shi', '', NULL, '南陽道中作 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb3998d-a042-4f94-a079-1088d91d9896', '哭呂衡州八郎中', '哭呂衡州八郎中', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["今朝血淚問蒼蒼，不分先悲旅館喪。","人送劍來歸隴上，鴈飛書去呌衡陽。","還家路遠兒童小，埋玉泉深晝夜長。","望盡素車秋草外，欲將身贖返魂香。"]', '["今朝血泪问蒼蒼，不分先悲旅館喪。","人送劍来归隴上，鴈飞书去呌衡陽。","還家路远兒童小，埋玉泉深晝夜长。","望尽素车秋草外，欲將身贖返魂香。"]', '诗', 'shi', '', NULL, '哭呂衡州八郎中 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f33d56e8-fd4d-4ddc-a921-deb26d1c66c3', '江陵遇元九李六二侍御紀事書情呈十二韻', '江陵遇元九李六二侍御紀事书情呈十二韻', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["自見人相愛，如君愛我稀。","好閑容問道，攻短每言非。","夢想何曾間，追歡未省違。","看花憐後到，避酒許先歸。","柳寺春堤遠，津橋曙月微。","漁翁隨去處，禪客共因依。","蓬閣初疑義，霜臺晚畏威。","學深通古字，心直觸危機。","肯滯荆州掾，猶香柏署衣。","山連巫峽秀，田傍渚宮肥。","美玉方齊價，遷鸎尚怯飛。","佇看霄漢上，連步侍彤闈。"]', '["自见人相愛，如君愛我稀。","好闲容问道，攻短每言非。","梦想何曾间，追歡未省違。","看花怜後到，避酒許先归。","柳寺春堤远，津橋曙月微。","漁翁隨去处，禪客共因依。","蓬閣初疑義，霜台晚畏威。","学深通古字，心直觸危機。","肯滯荆州掾，猶香柏署衣。","山連巫峽秀，田傍渚宮肥。","美玉方齊價，遷鸎尚怯飞。","佇看霄漢上，連步侍彤闈。"]', '诗', 'shi', '', NULL, '江陵遇元九李六二侍御紀事書情呈十二韻 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caddcfff-de58-4a1f-b9e9-66272b91e3b0', '遊仙詞', '游仙词', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["海上神山綠，溪邊杏樹紅。","不知何處去，月照玉樓空。"]', '["海上神山綠，溪邊杏樹紅。","不知何处去，月照玉楼空。"]', '诗', 'shi', '', NULL, '遊仙詞 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2880523b-e82b-412b-ad58-ef7f091cdc10', '贈阿史那都尉', '贈阿史那都尉', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["較獵燕山經幾春，雕弓白羽不離身。","年來馬上渾無力，望見飛鴻指似人。"]', '["較獵燕山經幾春，雕弓白羽不離身。","年来马上渾無力，望见飞鴻指似人。"]', '诗', 'shi', '', NULL, '贈阿史那都尉 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f112a7-d4fd-4d75-abcd-6b844ff50049', '陝府賓堂覽房杜二公仁壽年中題紀手跡', '陝府賓堂覽房杜二公仁壽年中題紀手跡', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["仁壽元和二百年，濛籠水墨淡如煙。","當時憔悴題名日，漢祖龍潛未上天。"]', '["仁壽元和二百年，濛籠水墨淡如煙。","當时憔悴題名日，漢祖龙潛未上天。"]', '诗', 'shi', '', NULL, '陝府賓堂覽房杜二公仁壽年中題紀手跡 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30428270-29d0-4a3f-9047-04b82a556a3e', '早春送宇文十歸吳', '早春送宇文十归吳', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["春遲不省似今年，二月無花雪滿天。","村店閉門何處宿，夜深遙喚渡江船。"]', '["春遲不省似今年，二月無花雪满天。","村店閉门何处宿，夜深遙喚渡江船。"]', '诗', 'shi', '', NULL, '早春送宇文十歸吳 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da486ab-de29-4f31-b870-33d7e323d2ce', '經竇車騎故城', '經竇车騎故城', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["荒陂古堞欲千年，名振圖書劍在泉。","今日諸孫拜墳樹，愧無文字續燕然。"]', '["荒陂古堞欲千年，名振圖书劍在泉。","今日諸孫拜墳樹，愧無文字續燕然。"]', '诗', 'shi', '', NULL, '經竇車騎故城 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406e0eed-8fcf-4132-baae-eb8bc64b60b9', '贈王氏小兒', '贈王氏小兒', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["竹林會裏偏憐小，淮水清時最覺賢。","莫倚兒童輕歲月，丈人曾共爾同年。"]', '["竹林會裏偏怜小，淮水清时最覺賢。","莫倚兒童轻歲月，丈人曾共爾同年。"]', '诗', 'shi', '', NULL, '贈王氏小兒 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8362bc0-7333-4d58-a939-23e9e85ab075', '唐州東途作', '唐州东途作', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["綠林兵起結愁雲，白羽飛書未解紛。","天子欲開三面網，莫將弓箭射官軍。"]', '["綠林兵起結愁云，白羽飞书未解紛。","天子欲开三面網，莫將弓箭射官軍。"]', '诗', 'shi', '', NULL, '唐州東途作 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf127bb7-0ba6-4ab9-b4bb-58cbd3b25dc2', '新羅進白鷹', '新羅進白鷹', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["御馬新騎禁苑秋，白鷹來自東海頭。","漢皇無事須游獵，雪亂爭飛錦臂韝。"]', '["御马新騎禁苑秋，白鷹来自东海头。","漢皇無事須游獵，雪亂爭飞錦臂韝。"]', '诗', 'shi', '', NULL, '新羅進白鷹 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d095cc-67cc-489b-8446-2a98034a99fa', '秋夕', '秋夕', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["護霜雲映月朦朧，烏鵲爭飛井上桐。","半夜酒醒人不覺，滿池荷葉動秋風。"]', '["護霜云映月朦朧，烏鵲爭飞井上桐。","半夜酒醒人不覺，满池荷葉动秋风。"]', '诗', 'shi', '', NULL, '秋夕 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfb8c500-4eb8-4816-9b13-91d292ad9c6f', '襄陽寒食寄宇文籍', '襄陽寒食寄宇文籍', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["煙水初銷見萬家，東風吹柳萬條斜。","大堤欲上誰相伴，馬踏春泥半是花。"]', '["煙水初銷见万家，东风吹柳万條斜。","大堤欲上誰相伴，马踏春泥半是花。"]', '诗', 'shi', '', NULL, '襄陽寒食寄宇文籍 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b19c7b4-897a-421d-9e1d-0595c4f9143b', '奉使薊門', '奉使薊门', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["自從身屬富人侯，蟬噪槐花已四秋。","今日一莖新白髮，懶騎官馬到幽州。"]', '["自從身屬富人侯，蟬噪槐花已四秋。","今日一莖新白髮，懶騎官马到幽州。"]', '诗', 'shi', '', NULL, '奉使薊門 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c82d762e-06ba-49f0-a269-a428d788af85', '送劉禹錫', '送劉禹錫', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["十年憔悴武陵溪，鶴病深林玉在泥。","今日太行平似砥，九霄初倚入雲梯。"]', '["十年憔悴武陵溪，鹤病深林玉在泥。","今日太行平似砥，九霄初倚入云梯。"]', '诗', 'shi', '', NULL, '送劉禹錫 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2988c85a-0b86-4acd-831d-ed3dbb523a9c', '送元稹西歸', '送元稹西归', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["南州風土滯龍媒，黃紙初飛勅字來。","二月曲江連舊宅，阿婆情熟牡丹開。"]', '["南州风土滯龙媒，黄紙初飞勅字来。","二月曲江連旧宅，阿婆情熟牡丹开。"]', '诗', 'shi', '', NULL, '送元稹西歸 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376bb1ed-f0cc-4f98-9a95-a4995eb54bd7', '過驪山', '過驪山', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["翠輦紅旌去不回，蒼蒼宮樹鎖青苔。","有人說得當時事，曾見長生玉殿開。"]', '["翠輦紅旌去不回，蒼蒼宮樹鎖青苔。","有人说得當时事，曾见长生玉殿开。"]', '诗', 'shi', '', NULL, '過驪山 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950a0be4-e2bd-4834-9c1f-f3bc0925c2ea', '洛中即事', '洛中即事', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["高梧葉盡鳥巢空，洛水潺湲夕照中。","寂寂天橋車馬絕，寒鴉飛入上陽宮。"]', '["高梧葉尽鸟巢空，洛水潺湲夕照中。","寂寂天橋车马絕，寒鴉飞入上陽宮。"]', '诗', 'shi', '', NULL, '洛中即事 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c6924e-ffd3-4606-86df-58614f76dc7c', '尋道者所隱不遇', '尋道者所隐不遇', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["籬外涓涓澗水流，槿花半點夕陽收。","欲題名字知相訪，又恐芭蕉不奈秋。"]', '["籬外涓涓澗水流，槿花半点夕陽收。","欲題名字知相訪，又恐芭蕉不奈秋。"]', '诗', 'shi', '', NULL, '尋道者所隱不遇 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a909e96-1fba-40ff-a743-0be626e045a6', '寄南游兄弟', '寄南游兄弟', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["書來未報幾時還，知在三湘五嶺間。","獨立衡門秋水闊，寒鴉飛去日銜山。"]', '["书来未報幾时還，知在三湘五嶺间。","独立衡门秋水闊，寒鴉飞去日銜山。"]', '诗', 'shi', '', NULL, '寄南游兄弟 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979a9120-0007-46b3-9b89-fe7ed88f262a', '宮人斜', '宮人斜', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["離宮路遠北原斜，生死恩深不到家。","雲雨今歸何處去，黃鸝飛上野棠花。"]', '["離宮路远北原斜，生死恩深不到家。","云雨今归何处去，黄鸝飞上野棠花。"]', '诗', 'shi', '', NULL, '宮人斜 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfbbe938-68c4-49ba-9868-ae245d49e881', '代鄰叟', '代鄰叟', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["年來七十罷耕桑，就暖支羸強下牀。","滿眼兒孫身外事，閑梳白髮對殘陽。"]', '["年来七十罷耕桑，就暖支羸強下牀。","满眼兒孫身外事，闲梳白髮对殘陽。"]', '诗', 'shi', '', NULL, '代鄰叟 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea977bb-f841-413f-a4de-4de2047c2fdc', '新營別墅寄家兄', '新營別墅寄家兄', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["懶性如今成野人，行藏由興不由身。","莫驚此度歸來晚，買得西山正值春。"]', '["懶性如今成野人，行藏由兴不由身。","莫驚此度归来晚，買得西山正值春。"]', '诗', 'shi', '', NULL, '新營別墅寄家兄 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f40d75d-64d0-4baf-9a3c-ab93efa2e720', '南游感興', '南游感兴', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["傷心欲問前朝事，惟見江流去不回。","日暮東風春草綠，鷓鴣飛上越王臺。"]', '["傷心欲问前朝事，惟见江流去不回。","日暮东风春草綠，鷓鴣飞上越王台。"]', '诗', 'shi', '', NULL, '南游感興 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0513d467-c578-4a77-a793-3789852c09b7', '題劍津', '題劍津', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["風前推折千年劍，巖下澄空萬古潭。","雙劍變成龍化去，兩溪相並水歸南。"]', '["风前推折千年劍，巖下澄空万古潭。","雙劍变成龙化去，兩溪相並水归南。"]', '诗', 'shi', '', NULL, '題劍津 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e44e405-1497-4a50-8d60-2a6d66979a92', '放魚', '放鱼', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["金錢贖得免刀痕，聞道禽魚亦感恩。","好去長江千萬里，不須辛苦上龍門。"]', '["金錢贖得免刀痕，闻道禽鱼亦感恩。","好去长江千万里，不須辛苦上龙门。"]', '诗', 'shi', '', NULL, '放魚 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73e9c6a8-0703-4a8f-bc26-b75cba63baab', '永寧小園寄接近校書', '永寧小园寄接近校书', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["故里心期奈別何，手栽芳樹憶庭柯。","東臯黍熟君應醉，梨葉初紅白露多。"]', '["故里心期奈別何，手栽芳樹憶庭柯。","东臯黍熟君應醉，梨葉初紅白露多。"]', '诗', 'shi', '', NULL, '永寧小園寄接近校書 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7677dd13-ce55-4662-a36d-7e4367fe597b', '從軍別家', '從軍別家', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["自笑儒生著戰袍，書齋壁上挂弓刀。","如今便是征人婦，好織迴文寄竇滔。"]', '["自笑儒生著戰袍，书斋壁上挂弓刀。","如今便是征人婦，好织迴文寄竇滔。"]', '诗', 'shi', '', NULL, '從軍別家 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9a86bfc-4d1c-46d2-9672-a68c01bdb546', '悼妓東東', '悼妓东东', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["芳菲美豔不禁風，未到春殘已墜紅。","惟有側輪車上鐸，耳邊長似呌東東。"]', '["芳菲美豔不禁风，未到春殘已墜紅。","惟有側輪车上鐸，耳邊长似呌东东。"]', '诗', 'shi', '', NULL, '悼妓東東 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e29d72b-7386-48c6-af3c-9dafd02f0665', '木蘭歌', '木蘭歌', 'bf8abfd3-f658-44ff-bdda-aa12e4e7baf8', '唐', '["木蘭抱杼嗟，借問復爲誰。","欲聞所戚戚，感激彊其顏。","老父隸兵籍，氣力日衰耗。","豈足萬里行，有子復尚少。","胡沙沒馬足，朔風裂人膚。","老父舊羸病，何以彊自扶。","木蘭代父去，秣馬備戎行。","易却紈綺裳，洗却鉛粉妝。","馳馬赴軍幕，慷慨攜干將。","朝屯雪山下，暮宿青海傍。","夜襲燕支虜，更攜于闐羌。","將軍得勝歸，士卒還故鄉。","父母見木蘭，喜極成悲傷。","木蘭能承父母顏，却卸巾韝理絲簧。","昔爲烈士雄，今爲嬌子容。","親戚持酒賀父母，始知生女與男同。","門前舊軍都，十年共崎嶇。","本結弟兄交，死戰誓不渝。","今者見木蘭，言聲雖是顏貌殊。","驚愕不敢前，歎息徒嘻吁。","世有臣子心，能如木蘭節。","忠孝兩不渝，千古之名焉可滅。"]', '["木蘭抱杼嗟，借问复爲誰。","欲闻所戚戚，感激彊其顏。","老父隸兵籍，氣力日衰耗。","豈足万里行，有子复尚少。","胡沙沒马足，朔风裂人膚。","老父旧羸病，何以彊自扶。","木蘭代父去，秣马備戎行。","易却紈綺裳，洗却鉛粉妝。","驰马赴軍幕，慷慨携干將。","朝屯雪山下，暮宿青海傍。","夜襲燕支虜，更携于闐羌。","將軍得勝归，士卒還故乡。","父母见木蘭，喜極成悲傷。","木蘭能承父母顏，却卸巾韝理絲簧。","昔爲烈士雄，今爲嬌子容。","親戚持酒賀父母，始知生女與男同。","门前旧軍都，十年共崎嶇。","本結弟兄交，死戰誓不渝。","今者见木蘭，言声雖是顏貌殊。","驚愕不敢前，歎息徒嘻吁。","世有臣子心，能如木蘭節。","忠孝兩不渝，千古之名焉可滅。"]', '诗', 'shi', '', NULL, '木蘭歌 韋元甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c612a51-0ac3-4166-bad1-90d6e4cb6def', '登越王樓見喬公詩偶題', '登越王楼见喬公诗偶題', '45ec643a-a2d8-40e2-b1d1-0a1054eea712', '唐', '["雲架重樓出郡城，虹梁雅韻仲宣情。","越王空置千年跡，丞相兼揚萬古名。","過鳥時時衝客會，閑風往往弄江聲。","謬將蹇步尋高躅，魚目驪珠豈繼明。"]', '["云架重楼出郡城，虹梁雅韻仲宣情。","越王空置千年跡，丞相兼揚万古名。","過鸟时时衝客會，闲风往往弄江声。","謬將蹇步尋高躅，鱼目驪珠豈繼明。"]', '诗', 'shi', '', NULL, '登越王樓見喬公詩偶題 王鋌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbf5886-20e6-4195-9899-6519701f126f', '清如玉壺冰', '清如玉壺冰', 'b87b4bfd-d127-4781-a00c-788210eac762', '唐', '["琰玉性惟堅，成壺體更圓。","虛心含景象，應物受寒泉。","溫潤資天質，清貞稟自然。","日融光乍散，雪照色逾鮮。","至鑒功寧宰，無私照豈偏。","明將冰鏡對，白與粉花連。","拂拭終爲美，提攜佇見傳。","勿令毫髪累，遺恨鮑公篇。"]', '["琰玉性惟堅，成壺體更圓。","虛心含景象，應物受寒泉。","溫潤資天質，清貞稟自然。","日融光乍散，雪照色逾鲜。","至鑒功寧宰，無私照豈偏。","明將冰镜对，白與粉花連。","拂拭終爲美，提携佇见傳。","勿令毫髪累，遺恨鲍公篇。"]', '诗', 'shi', '', NULL, '清如玉壺冰 潘炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('463d0e24-1294-4095-9126-f63581c7b834', '長至日上公獻壽', '长至日上公獻壽', 'f2ece9d7-e6cb-40c0-a437-0b1e335b3d80', '唐', '["鳳闕晴鐘動，雞人曉漏長。","九重初啓鑰，三事正稱觴。","日至龍顏近，天旋聖曆昌。","休光連雪淨，瑞氣雜爐香。","化被君臣洽，恩霑士庶康。","不因稽舊典，誰得紀朝章。"]', '["鳳闕晴鐘动，雞人晓漏长。","九重初啓鑰，三事正稱觴。","日至龙顏近，天旋聖曆昌。","休光連雪淨，瑞氣杂爐香。","化被君臣洽，恩霑士庶康。","不因稽旧典，誰得紀朝章。"]', '诗', 'shi', '', NULL, '長至日上公獻壽 張叔良 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac6a38f-b5ff-466b-abc3-6e5b79065dc4', '涇渭揚清濁', '涇渭揚清濁', 'e50b5ed5-2070-4d5b-a2db-8021004aa94c', '唐', '["涇渭橫秦野，逶迤近帝城。","二渠通作潤，萬戶映皆清。","明晦看殊色，潺湲聽一聲。","岸虛深草掩，波五曉煙輕。","御獵思投釣，漁歌好濯纓。","合流知禹力，同共到滄瀛。"]', '["涇渭橫秦野，逶迤近帝城。","二渠通作潤，万戶映皆清。","明晦看殊色，潺湲听一声。","岸虛深草掩，波五晓煙轻。","御獵思投釣，漁歌好濯纓。","合流知禹力，同共到滄瀛。"]', '诗', 'shi', '', NULL, '涇渭揚清濁 呂牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085a79ec-8601-4046-864b-b57fc3b42a21', '別張賈', '別張賈', '067ee659-cb82-49b4-8862-6945e053789e', '唐', '["束簡下高閣，買符驅短轅。","故人惜分袂，結念醉芳罇。","切切別思纏，蕭蕭征騎煩。","臨歸無限意，相視却忘言。"]', '["束簡下高閣，買符驱短轅。","故人惜分袂，結念醉芳罇。","切切別思纏，蕭蕭征騎煩。","臨归無限意，相視却忘言。"]', '诗', 'shi', '', NULL, '別張賈 韋夏卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b16e7a-797f-4fae-bba1-6c32ab049271', '送顧況歸茅山', '送顧況归茅山', '067ee659-cb82-49b4-8862-6945e053789e', '唐', '["聖代爲遷客，虛皇作近臣。","法尊稱大洞，學淺忝初真。","鸞鳳文章麗，煙霞翰墨新。","羨君尋句曲，白鵠是三神。"]', '["聖代爲遷客，虛皇作近臣。","法尊稱大洞，学淺忝初真。","鸾鳳文章丽，煙霞翰墨新。","羨君尋句曲，白鵠是三神。"]', '诗', 'shi', '', NULL, '送顧況歸茅山 韋夏卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f05eaa6-cf58-4b2d-9f01-6f727e93195f', '和丘員外題湛長史舊居', '和丘員外題湛长史旧居', '067ee659-cb82-49b4-8862-6945e053789e', '唐', '["道勝物能齊，累輕身易退。","苟安一丘上，何必三山外。","雲霞長若綺，松石常如黛。","徒有昔王過，竟遺青史載。","詩因埜寺詠，酒向山椒酹。","異時逢爾知，茲辰駐余斾。"]', '["道勝物能齊，累轻身易退。","苟安一丘上，何必三山外。","云霞长若綺，松石常如黛。","徒有昔王過，竟遺青史載。","诗因埜寺詠，酒向山椒酹。","異时逢爾知，茲辰駐余斾。"]', '诗', 'shi', '', NULL, '和丘員外題湛長史舊居 韋夏卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd69f24-037f-4b76-bedb-ad0318728fb3', '同韋夏卿送顧況歸茅山', '同韋夏卿送顧況归茅山', 'a4b6e919-aabb-4268-aa28-4145e325b73a', '唐', '["謫宦聞嘗賦，遊仙便作詩。","白銀雙闕戀，青竹一龍騎。","先入茅君洞，旋過葛稚陂。","無然列禦寇，五日有還期。"]', '["謫宦闻嘗賦，游仙便作诗。","白銀雙闕戀，青竹一龙騎。","先入茅君洞，旋過葛稚陂。","無然列禦寇，五日有還期。"]', '诗', 'shi', '', NULL, '同韋夏卿送顧況歸茅山 綦毋誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec90746-56f1-4b99-88f6-e50eb1370c0f', '感秋', '感秋', '9d526541-b281-44c3-828b-552477d51f64', '唐', '["試向疎林望，方知節候殊。","亂聲千葉下，寒影一巢孤。","不蔽秋天雁，驚飛夜月烏。","霜風與春日，幾度遣榮枯。"]', '["試向疎林望，方知節候殊。","亂声千葉下，寒影一巢孤。","不蔽秋天雁，驚飞夜月烏。","霜风與春日，幾度遣榮枯。"]', '诗', 'shi', '', NULL, '感秋 姚倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00c3fe2-c986-42d1-82ae-545dc80ba583', '過章秀才洛陽客舍', '過章秀才洛陽客舍', '9d526541-b281-44c3-828b-552477d51f64', '唐', '["達人心自適，旅舍當閑居。","不出來時徑，重看讀了書。","晚山嵐色近，斜日樹陰疎。","盡是忘言客，聽君誦子虛。"]', '["達人心自適，旅舍當闲居。","不出来时徑，重看读了书。","晚山嵐色近，斜日樹陰疎。","尽是忘言客，听君誦子虛。"]', '诗', 'shi', '', NULL, '過章秀才洛陽客舍 姚倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c04f1f8-3b37-480a-9d10-9b900fc31055', '賦得生芻一束', '賦得生芻一束', '25ea9ef6-2e74-4679-befd-0946e2153f58', '唐', '["比玉人應重，爲芻物自輕。","向風傾弱葉，裛露示纖莖。","蒨練宜春景，芊綿對雨情。","每慙蘋藻用，多謝𦶜蘭榮。","孺子才雖遠，公孫策未行。","諮詢如不棄，終冀及微生。"]', '["比玉人應重，爲芻物自轻。","向风傾弱葉，裛露示纖莖。","蒨練宜春景，芊綿对雨情。","每慙蘋藻用，多謝𦶜蘭榮。","孺子才雖远，公孫策未行。","諮詢如不棄，終冀及微生。"]', '诗', 'shi', '', NULL, '賦得生芻一束 于結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf49a4f6-6042-42b4-9597-952a754996a1', '賦得生芻一束', '賦得生芻一束', '3a6b6bc2-7cb8-4058-9f80-5530a4584bd6', '唐', '["孫弘期射策，長倩贈生芻。","至潔心將比，忘憂道不孤。","芝蘭方入室，蕭艾莫同途。","馥馥香猶在，青青色更殊。","芳寧九春歇，薰豈十年無。","葑菲如堪採，山苗自可逾。"]', '["孫弘期射策，长倩贈生芻。","至潔心將比，忘憂道不孤。","芝蘭方入室，蕭艾莫同途。","馥馥香猶在，青青色更殊。","芳寧九春歇，薰豈十年無。","葑菲如堪採，山苗自可逾。"]', '诗', 'shi', '', NULL, '賦得生芻一束 鄭孺華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75da1e65-31e2-42b3-b58c-82c8dc22efe3', '空靈岸', '空靈岸', '420a0114-b00e-4a88-9fc6-0e837b8afca6', '唐', '["寒盡鴻先去，江迴客未歸。","早知名是幻，不敢繡爲衣。","霧積川原暗，山多郡縣稀。","今朝下湘岸，更逐鷓鴣飛。"]', '["寒尽鴻先去，江迴客未归。","早知名是幻，不敢繡爲衣。","霧積川原暗，山多郡縣稀。","今朝下湘岸，更逐鷓鴣飞。"]', '诗', 'shi', '', NULL, '空靈岸 張叔卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d0fce9-3927-4646-85b1-89e1ba7b5af6', '流桂州', '流桂州', '420a0114-b00e-4a88-9fc6-0e837b8afca6', '唐', '["莫問蒼梧遠，而今世路難。","胡塵不到處，即是小長安。"]', '["莫问蒼梧远，而今世路难。","胡塵不到处，即是小长安。"]', '诗', 'shi', '', NULL, '流桂州 張叔卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348d058b-22e9-44c4-9645-8c736626ee14', '酬竇大閑居見寄', '酬竇大闲居见寄', '3621ddbb-cbfe-42ab-85aa-3599cfac1ff5', '唐', '["來自三湘到五溪，青楓無樹不猨啼。","名慙竹使宦情少，路隔桃源歸思迷。","鵩鳥賦成知性命，鯉魚書至恨暌攜。","煩君強著潘年比，騎省風流詎可齊。"]', '["来自三湘到五溪，青楓無樹不猨啼。","名慙竹使宦情少，路隔桃源归思迷。","鵩鸟賦成知性命，鯉鱼书至恨暌携。","煩君強著潘年比，騎省风流詎可齊。"]', '诗', 'shi', '', NULL, '酬竇大閑居見寄 房孺復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f2be4f-627b-4451-84fb-590727d5b8a5', '送妓人出家', '送妓人出家', '9741daac-50f6-4fc5-87bc-f47ab4e07f3b', '唐', '["盡出花鈿與四隣，雲鬟剪落厭殘春。","暫驚風燭難留世，便是蓮花不染身。","貝葉欲翻迷錦字，梵聲初學悞梁塵。","從今豔色歸空後，湘浦應無解珮人。"]', '["尽出花鈿與四隣，云鬟剪落厭殘春。","暫驚风燭难留世，便是蓮花不染身。","貝葉欲翻迷錦字，梵声初学悞梁塵。","從今豔色归空後，湘浦應無解珮人。"]', '诗', 'shi', '', NULL, '送妓人出家 楊郇伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa7f347-fca0-4972-8cd9-3f792f76418a', '宿北樂館', '宿北乐館', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["欲眠不眠夜深淺，越鳥一聲空山遠。","庭木蕭蕭落葉時，溪聲雨聲聽不辨。","溪流潺潺雨習習，燈影山光滿窗入。","棟里不知渾是雲，曉來但覺衣裳濕。"]', '["欲眠不眠夜深淺，越鸟一声空山远。","庭木蕭蕭落葉时，溪声雨声听不辨。","溪流潺潺雨習習，灯影山光满窗入。","棟里不知渾是云，晓来但覺衣裳濕。"]', '诗', 'shi', '', NULL, '宿北樂館 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ef56b5d-6cad-4297-bae0-712a661e30a2', '東都所居寒食下作', '东都所居寒食下作', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["江南寒食早，二月杜鵑鳴。","日暖山初綠，春寒雨欲晴。","浴蠶當社日，改火待清明。","更喜瓜田好，令人憶邵平。"]', '["江南寒食早，二月杜鵑鳴。","日暖山初綠，春寒雨欲晴。","浴蠶當社日，改火待清明。","更喜瓜田好，令人憶邵平。"]', '诗', 'shi', '', NULL, '東都所居寒食下作 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa479a59-7529-4209-86e5-33f0eec4678c', '登西靈塔', '登西靈塔', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["塔廟出招提，登臨碧海西。","不知人意遠，漸覺鳥飛低。","稍與雲霞近，如將日月齊。","遷喬未得意，徒欲躡雲梯。"]', '["塔廟出招提，登臨碧海西。","不知人意远，漸覺鸟飞低。","稍與云霞近，如將日月齊。","遷喬未得意，徒欲躡云梯。"]', '诗', 'shi', '', NULL, '登西靈塔 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb7c128-e0d0-427e-9d8d-d2e07185e6a8', '送駱徵君', '送駱徵君', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["野人膺辟命，溪上掩柴扉。","黃卷猶將去，青山豈更歸。","馬留苔蘚迹，人脫薜蘿衣。","他日相思處，天邊望少微。"]', '["野人膺辟命，溪上掩柴扉。","黄卷猶將去，青山豈更归。","马留苔蘚迹，人脫薜蘿衣。","他日相思处，天邊望少微。"]', '诗', 'shi', '', NULL, '送駱徵君 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fca99c7-a467-43a6-8893-4f2151ec902a', '賦得浦外虹送人', '賦得浦外虹送人', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["日影化爲虹，彎彎出浦東。","一條微雨後，五色片雲中。","輪勢隨天度，橋形跨海通。","還將飲水處，持送使車雄。"]', '["日影化爲虹，彎彎出浦东。","一條微雨後，五色片云中。","輪勢隨天度，橋形跨海通。","還將饮水处，持送使车雄。"]', '诗', 'shi', '', NULL, '賦得浦外虹送人 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01ccb79c-73c2-4109-9ff5-f10c302fe5d6', '賦得秋河曙耿耿', '賦得秋河曙耿耿', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["晚望秋高夜，微明欲曙河。","橋成鵲已去，機罷女應過。","月上殊開練，雲行類動波。","尋源不可到，耿耿復如何。"]', '["晚望秋高夜，微明欲曙河。","橋成鵲已去，機罷女應過。","月上殊开練，云行類动波。","尋源不可到，耿耿复如何。"]', '诗', 'shi', '', NULL, '賦得秋河曙耿耿 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb6ad8a-32a4-4c59-b0ff-01abe0e3db65', '賦得池塘生春草', '賦得池塘生春草', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["謝公遺詠處，池水夾通津。","古往人何在，年來草自春。","色宜波際綠，香愛雨中新。","今日青青意，空悲行路人。"]', '["謝公遺詠处，池水夾通津。","古往人何在，年来草自春。","色宜波際綠，香愛雨中新。","今日青青意，空悲行路人。"]', '诗', 'shi', '', NULL, '賦得池塘生春草 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49f054a5-f141-4fe7-94d6-7f7b43d7f494', '闕題', '闕題', '4a46e16e-e82a-4911-972b-39e2a75408ad', '唐', '["丈夫不感恩，感恩寧有淚。","心頭感恩血，一滴染天地。"]', '["丈夫不感恩，感恩寧有泪。","心头感恩血，一滴染天地。"]', '诗', 'shi', '', NULL, '闕題 陳潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3182d857-499a-4f62-89f1-aa628eaf63e3', '哭長孫侍郎', '哭长孫侍郎', 'baaf5909-7352-4cb8-9e84-40ff6c6bca50', '唐', '["道爲詩書重，名因賦頌雄。","禮闈曾擢桂，憲府既乘驄。","流水生涯盡，浮雲世事空。","唯餘舊臺柏，蕭瑟九原中。"]', '["道爲诗书重，名因賦頌雄。","禮闈曾擢桂，憲府既乘驄。","流水生涯尽，浮云世事空。","唯餘旧台柏，蕭瑟九原中。"]', '诗', 'shi', '', NULL, '哭長孫侍郎 杜誦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdeaedca-0899-4ffb-b368-a3396acdd350', '明皇帝挽歌', '明皇帝挽歌', '74c0cc2e-886e-4564-875f-8c65636bec7b', '唐', '["律曆千年會，車書萬里同。","固期常戴日，豈意厭觀風。","地慘新[疆]理，城摧舊戰功。","山河萬古壯，今夕盡歸空。"]', '["律曆千年會，车书万里同。","固期常戴日，豈意厭观风。","地慘新[疆]理，城摧旧戰功。","山河万古壯，今夕尽归空。"]', '诗', 'shi', '', NULL, '明皇帝挽歌 鄭丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f985fc4-d1f2-46e5-a6e3-4670d491f802', '肅宗挽歌', '肅宗挽歌', '74c0cc2e-886e-4564-875f-8c65636bec7b', '唐', '["國以重明受，天從諒闇移。","諸侯方北面，白日忽西馳。","龍影當泉落，鴻名向廟垂。","永言青史上，還見戴無爲。"]', '["国以重明受，天從諒闇移。","諸侯方北面，白日忽西驰。","龙影當泉落，鴻名向廟垂。","永言青史上，還见戴無爲。"]', '诗', 'shi', '', NULL, '肅宗挽歌 鄭丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d11fa50-fb4a-41b0-b664-cde7559db342', '落花', '落花', 'dcc5cc37-033b-4e3c-957d-03082c9b903f', '唐', '["早春見花枝，朝朝恨發遲。","直看花落盡，却意未開時。","以此方人世，彌令感盛衰。","始知山簡遶，頻向習家池。"]', '["早春见花枝，朝朝恨發遲。","直看花落尽，却意未开时。","以此方人世，彌令感盛衰。","始知山簡遶，頻向習家池。"]', '诗', 'shi', '', NULL, '落花 鄭昈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed9d032-88fc-465d-a637-3a344fcad426', '宿新安江深渡館寄鄭州王使君', '宿新安江深渡館寄鄭州王使君', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["霜飛十月中，搖落衆山空。","孤館閉寒木，大江生夜風。","賦詩忙有意，沈約在關東。"]', '["霜飞十月中，搖落衆山空。","孤館閉寒木，大江生夜风。","賦诗忙有意，沈約在关东。"]', '诗', 'shi', '', NULL, '宿新安江深渡館寄鄭州王使君 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c61891-a0a4-498c-94e0-14c21e58c55e', '春眺揚州西上崗寄徐員外', '春眺揚州西上崗寄徐員外', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["蕪城西眺極蒼流，漠漠春煙間曙樓。","瓜步早潮吞建業，蒜山晴雪照揚州。","隋家故事不能問，鶴在仙池期我游。"]', '["蕪城西眺極蒼流，漠漠春煙间曙楼。","瓜步早潮吞建業，蒜山晴雪照揚州。","隋家故事不能问，鹤在仙池期我游。"]', '诗', 'shi', '', NULL, '春眺揚州西上崗寄徐員外 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da9e6e6d-2045-449f-873b-df89c5f651dc', '送李司直歸浙東幕兼寄鮑將軍', '送李司直归浙东幕兼寄鲍將軍', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["翩翩書記早曾聞，二十年來願見君。","今日相逢悲白髮，同時幾許在青雲。","人從北固山邊去，水到西陵渡口分。","會作王門曳裾客，爲余前謝鮑將軍。"]', '["翩翩书記早曾闻，二十年来願见君。","今日相逢悲白髮，同时幾許在青云。","人從北固山邊去，水到西陵渡口分。","會作王门曳裾客，爲余前謝鲍將軍。"]', '诗', 'shi', '', NULL, '送李司直歸浙東幕兼寄鮑將軍 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23745d0-e2f1-4f9b-b5b7-84a392435426', '望中有懷', '望中有懷', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["龍向洞中銜雨出，鳥從花里帶香飛。","白雲斷處見明月，黃葉落時聞擣衣。"]', '["龙向洞中銜雨出，鸟從花里带香飞。","白云斷处见明月，黄葉落时闻擣衣。"]', '诗', 'shi', '', NULL, '望中有懷 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c7a1de-a9e7-467f-8b9c-1a99461197b4', '題虎丘山西寺', '題虎丘山西寺', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["王氏家山昔在茲，陸機爲賦陸雲詩。","青蓮香匝東西宇，日月與僧無盡時。"]', '["王氏家山昔在茲，陸機爲賦陸云诗。","青蓮香匝东西宇，日月與僧無尽时。"]', '诗', 'shi', '', NULL, '題虎丘山西寺 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5fee21-36d3-4208-ad6e-662a54617b79', '吳興送梁補闕歸朝賦得荻花', '吳兴送梁補闕归朝賦得荻花', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["柳家汀洲孟冬月，雲寒水清荻花發。","一枝持贈朝天人，願比蓬萊殿前雪。"]', '["柳家汀洲孟冬月，云寒水清荻花發。","一枝持贈朝天人，願比蓬萊殿前雪。"]', '诗', 'shi', '', NULL, '吳興送梁補闕歸朝賦得荻花 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad873e5d-356a-4a12-a846-392768fb408a', '句', '句', 'e99f3404-831a-4681-b790-de9bc696a36f', '唐', '["夜靜忽疑身是夢，更聞寒雨滴芭蕉。"]', '["夜静忽疑身是梦，更闻寒雨滴芭蕉。"]', '诗', 'shi', '', NULL, '句 朱長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657adab1-891f-4ad7-8570-10676fef36ec', '獨不見', '独不见', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["前宮路非遠，舊苑春將遍。","玉戶看早梅，雕梁數飛燕。","身輕逐舞袖，香暖傳歌扇。","自和秋風詞，長侍昭陽殿。","誰信後庭人，年年獨不見。"]', '["前宮路非远，旧苑春將遍。","玉戶看早梅，雕梁數飞燕。","身轻逐舞袖，香暖傳歌扇。","自和秋风词，长侍昭陽殿。","誰信後庭人，年年独不见。"]', '诗', 'shi', '', NULL, '獨不見 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f98159-5ac5-4f50-8d26-d4089f3f37d1', '去婦怨', '去婦怨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["出戶不敢啼，風悲日悽悽。","心知恩義絕，誰忍分明別。","下坂車轔轔，畏逢鄉里親。","空持牀前幔，却寄家中人。","忽辭王吉去，爲是秋胡死。","若比今日情，煩冤不相似。"]', '["出戶不敢啼，风悲日悽悽。","心知恩義絕，誰忍分明別。","下坂车轔轔，畏逢乡里親。","空持牀前幔，却寄家中人。","忽辞王吉去，爲是秋胡死。","若比今日情，煩冤不相似。"]', '诗', 'shi', '', NULL, '去婦怨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429c51a1-78e9-4603-9efa-b8e829358610', '古意', '古意', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["悠悠南山雲，濯濯東流水。","念我平生歡，託居在東里。","失既不足憂，得亦不爲喜。","安貧固其然，處賤寧獨恥。","雲閑虛我心，水清澹吾味。","雲水俱無心，斯可長伉儷。"]', '["悠悠南山云，濯濯东流水。","念我平生歡，託居在东里。","失既不足憂，得亦不爲喜。","安貧固其然，处賤寧独恥。","云闲虛我心，水清澹吾味。","云水俱無心，斯可长伉儷。"]', '诗', 'shi', '', NULL, '古意 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c79193be-38e8-4c79-8ac1-b7d3a4fb7933', '南野', '南野', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["治田長山下，引流坦溪曲。","東山有遺塋，南野起新築。","家世素業儒，子孫鄙食祿。","披雲朝出畊，帶月夜歸讀。","身勩竟亡疲，團團欣在目。","野芳綠可採，泉美清可掬。","茂樹延晚涼，早田候秋熟。","茶烹松火紅，酒吸荷杯綠。","解佩臨清池，撫琴看修竹。","此懷誰與同，此樂君所獨。"]', '["治田长山下，引流坦溪曲。","东山有遺塋，南野起新築。","家世素業儒，子孫鄙食祿。","披云朝出畊，带月夜归读。","身勩竟亡疲，團團欣在目。","野芳綠可採，泉美清可掬。","茂樹延晚涼，早田候秋熟。","茶烹松火紅，酒吸荷杯綠。","解佩臨清池，撫琴看修竹。","此懷誰與同，此乐君所独。"]', '诗', 'shi', '', NULL, '南野 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('127a633c-22c0-45a6-af3f-21a31f284d5a', '曾遊', '曾游', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["泊舟古城下，高閣快登眺。","大江會彭蠡，羣峰豁玄嶠。","清影涵空明，黛色凝遠照。","碑留太史書，詞刻長公調。","絕粒感楚囚，丹衷猶照耀。","懷哉不可招，憑闌一悲嘯。"]', '["泊舟古城下，高閣快登眺。","大江會彭蠡，羣峰豁玄嶠。","清影涵空明，黛色凝远照。","碑留太史书，词刻长公調。","絕粒感楚囚，丹衷猶照耀。","懷哉不可招，憑闌一悲嘯。"]', '诗', 'shi', '', NULL, '曾遊 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6c1cb6-7549-4bd4-922d-fc9fb9ba2340', '江行', '江行', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["漾舟晴川裏，挂席候風生。","臨泛何容與，愛此江水清。","蘆洲隱遙嶂，露日映孤城。","自顧疎野性，屢忘鷗鳥情。","聊復於時顧，暫欲解塵纓。","驅馳非吾願，虛懷浩已盈。"]', '["漾舟晴川裏，挂席候风生。","臨泛何容與，愛此江水清。","蘆洲隐遙嶂，露日映孤城。","自顧疎野性，屢忘鷗鸟情。","聊复於时顧，暫欲解塵纓。","驱驰非吾願，虛懷浩已盈。"]', '诗', 'shi', '', NULL, '江行 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63dd89a3-64b9-4705-9fd8-53ee15cdff0f', '孤鴻篇', '孤鴻篇', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["江上雙飛鴻，飲啄行相隨。","翔風一何厲，中道傷其雌。","顧影明月下，哀鳴聲正悲。","已無矰𥐊患，豈乏稻梁資。","嗈嗈慕儔匹，遠集清江湄。","中有孤文鵷，翩翩好容儀。","共欣相知遇，畢志同棲遲。","野田鴟鴞鳥，相妒復相疑。","鴻志不汝較，奮翼起高飛。","焉隨腐鼠欲，負此雲霄期。"]', '["江上雙飞鴻，饮啄行相隨。","翔风一何厲，中道傷其雌。","顧影明月下，哀鳴声正悲。","已無矰𥐊患，豈乏稻梁資。","嗈嗈慕儔匹，远集清江湄。","中有孤文鵷，翩翩好容儀。","共欣相知遇，畢志同棲遲。","野田鴟鴞鸟，相妒复相疑。","鴻志不汝較，奮翼起高飞。","焉隨腐鼠欲，負此云霄期。"]', '诗', 'shi', '', NULL, '孤鴻篇 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c54e9c9-a444-4f49-b8a2-b55e5ae801cc', '感懷二首 一', '感懷二首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["尺帛無長裁，淺水無長流。","水淺易成枯，帛短誰人收。","人生取舍間，趨競固非優。","舊交跡雖疎，中心自云稠。","新交意雖密，中道生怨尤。","踟躕復踟躕，世路今悠悠。"]', '["尺帛無长裁，淺水無长流。","水淺易成枯，帛短誰人收。","人生取舍间，趨競固非優。","旧交跡雖疎，中心自云稠。","新交意雖密，中道生怨尤。","踟躕复踟躕，世路今悠悠。"]', '诗', 'shi', '', NULL, '感懷二首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d36c933-4e04-4829-8a6f-6adc77204e84', '感懷二首 二', '感懷二首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["主人飲君酒，勸君弗相違。","但當盡弘量，觴至無復辭。","人生百年中，會合能幾時。","不見枝上花，昨滿今漸稀。","花落還再開，人老無少期。","古來賢達士，飲酒不復疑。"]', '["主人饮君酒，勸君弗相違。","但當尽弘量，觴至無复辞。","人生百年中，會合能幾时。","不见枝上花，昨满今漸稀。","花落還再开，人老無少期。","古来賢達士，饮酒不复疑。"]', '诗', 'shi', '', NULL, '感懷二首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b6db087-2999-4f42-9877-67c2a4cfde45', '喜雨', '喜雨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["閑居倦時燠，開軒俯平林。","雷聲殷遙空，雲氣布層陰。","川上風雨來，灑然滌煩襟。","田家共歡笑，溝澮亦已深。","團團聚鄰曲，斗酒相與斟。","樵歌野田中，漁釣滄江潯。","蒼天暨有念，悠悠終我心。"]', '["闲居倦时燠，开軒俯平林。","雷声殷遙空，云氣布層陰。","川上风雨来，灑然滌煩襟。","田家共歡笑，溝澮亦已深。","團團聚鄰曲，斗酒相與斟。","樵歌野田中，漁釣滄江潯。","蒼天暨有念，悠悠終我心。"]', '诗', 'shi', '', NULL, '喜雨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6f2e24d-b2cb-412e-b579-a48f0e20b961', '歎葵花', '歎葵花', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["今日見花落，明日見花開。","花開能向日，花落委蒼苔。","自不同凡卉，看時幾日迴。"]', '["今日见花落，明日见花开。","花开能向日，花落委蒼苔。","自不同凡卉，看时幾日迴。"]', '诗', 'shi', '', NULL, '歎葵花 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a657e3-0b2b-4c6b-b69b-14057f346891', '從軍行', '從軍行', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["丈夫四方志，結髮事遠游。","遠游歷燕薊，獨戍邊城陬。","西風壠水寒，明月關山悠。","酬恩仗孤劍，十年弊貂裘。","封侯屬何人，磋跎雪盈頭。","老馬思故櫪，窮鱗憶深流。","彈鋏動深慨，浩歌氣橫秋。","報國期努力，功名良見收。"]', '["丈夫四方志，結髮事远游。","远游歷燕薊，独戍邊城陬。","西风壠水寒，明月关山悠。","酬恩仗孤劍，十年弊貂裘。","封侯屬何人，磋跎雪盈头。","老马思故櫪，窮鱗憶深流。","彈鋏动深慨，浩歌氣橫秋。","報国期努力，功名良见收。"]', '诗', 'shi', '', NULL, '從軍行 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d4489c-981b-416d-97bd-d7de86b432d8', '九日與敬處士左學士同賦采菊上東山便爲首句', '九日與敬处士左学士同賦采菊上东山便爲首句', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["采菊上東山，山高路非遠。","江湖乍遼敻，城郭亦在眼。","晝日市井喧，閏年禾稼晚。","開尊會佳客，長嘯臨絕巘。","戲鶴唳且閑，斷雲輕不卷。","鄉心各萬里，醉話時一展。","喬木列遙天，殘陽貫平坂。","徒憂征車重，自笑謀慮淺。","却顧郡齋中，寄傲與君同。"]', '["采菊上东山，山高路非远。","江湖乍遼敻，城郭亦在眼。","晝日市井喧，閏年禾稼晚。","开尊會佳客，长嘯臨絕巘。","戲鹤唳且闲，斷云轻不卷。","乡心各万里，醉話时一展。","喬木列遙天，殘陽貫平坂。","徒憂征车重，自笑謀慮淺。","却顧郡斋中，寄傲與君同。"]', '诗', 'shi', '', NULL, '九日與敬處士左學士同賦采菊上東山便爲首句 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('289f44b0-41de-41e2-84b8-41e04a7f604c', '奉天酬別鄭諫議雲逵盧拾遺景亮見別之作', '奉天酬別鄭諫議云逵盧拾遺景亮见別之作', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["巨孽盜都城，傳聞天下驚。","陪臣九江畔，走馬來赴難。","伏奏見龍顏，旋持手詔還。","單車不可駐，朱檻未遑攀。","故人出相餞，共悲行路難。","臨岐荷贈言，對酒獨傷魂。","世故山川險，憂多思慮昏。","重陰蔽芳月，疊嶺明舊雪。","泥積轍更深，木冰花不發。","鄭君間世賢，忠孝乃雙全。","大義棄妻子，至淳易生死。","知心三四人，越境千餘里。","駿馬帳前發，驚塵路旁起。","樓頭俛首看，莫敢相留止。","拜闕奏良圖，留中沃聖謨。","洗兵救衞郡，誘敵討幽都。","名亞典屬國，良選諫大夫。","從容九霄上，談笑授陰符。","盧生富才術，特立居近密。","採掇獻吾君，朝廷視聽新。","寬饒狂自比，汲黯直爲鄰。","就列繼三事，主文當七人。","可憐長守道，不覺五逢春。","昔去城南陌，各爲天際客。","關河煙霧深，寸步音塵隔。","羈旅忽相遇，別離又茲夕。","前悲涕未乾，後喜心已慼。","而我方老大，頗爲風眩迫。","夫君幷少年，何爾鬢鬚白。","惆悵語不盡，裴回情轉劇。","一尊自共持，以慰長相憶。"]', '["巨孽盜都城，傳闻天下驚。","陪臣九江畔，走马来赴难。","伏奏见龙顏，旋持手詔還。","單车不可駐，朱檻未遑攀。","故人出相餞，共悲行路难。","臨岐荷贈言，对酒独傷魂。","世故山川險，憂多思慮昏。","重陰蔽芳月，叠嶺明旧雪。","泥積轍更深，木冰花不發。","鄭君间世賢，忠孝乃雙全。","大義棄妻子，至淳易生死。","知心三四人，越境千餘里。","駿马帳前發，驚塵路旁起。","楼头俛首看，莫敢相留止。","拜闕奏良圖，留中沃聖謨。","洗兵救衞郡，誘敵討幽都。","名亞典屬国，良選諫大夫。","從容九霄上，談笑授陰符。","盧生富才術，特立居近密。","採掇獻吾君，朝廷視听新。","寬饒狂自比，汲黯直爲鄰。","就列繼三事，主文當七人。","可怜长守道，不覺五逢春。","昔去城南陌，各爲天際客。","关河煙霧深，寸步音塵隔。","羈旅忽相遇，別離又茲夕。","前悲涕未乾，後喜心已慼。","而我方老大，頗爲风眩迫。","夫君幷少年，何爾鬢鬚白。","惆悵語不尽，裴回情轉劇。","一尊自共持，以慰长相憶。"]', '诗', 'shi', '', NULL, '奉天酬別鄭諫議雲逵盧拾遺景亮見別之作 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10b060f-73a8-4f5e-bf88-786d1c274e75', '梧桐', '梧桐', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["亭亭南軒外，貞幹修且直。","廣葉結青陰，繁花連素色。","天資韶雅性，不愧知音識。"]', '["亭亭南軒外，貞幹修且直。","廣葉結青陰，繁花連素色。","天資韶雅性，不愧知音識。"]', '诗', 'shi', '', NULL, '梧桐 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69227cca-7a41-431d-8ce9-8eda02f0c6e1', '孤石', '孤石', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["迥若千仞峰，孤危不盈尺。","早晚他山來，猶帶煙雨跡。","貞堅自有分，不亂和氏璧。"]', '["迥若千仞峰，孤危不盈尺。","早晚他山来，猶带煙雨跡。","貞堅自有分，不亂和氏璧。"]', '诗', 'shi', '', NULL, '孤石 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda01b8e-4e02-4173-b3b7-6ca523acd4fe', '花', '花', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["花發炎景中，芳春獨能久。","因風任開落，向日無先後。","若待秋霜來，蘭蓀共何有。"]', '["花發炎景中，芳春独能久。","因风任开落，向日無先後。","若待秋霜来，蘭蓀共何有。"]', '诗', 'shi', '', NULL, '花 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8989bc-6581-4530-9869-49574f9b111c', '竹', '竹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["卷籜正離披，新枝復蒙密。","翛翛月下聞，褭褭林際出。","豈獨對芳菲，終年色如一。"]', '["卷籜正離披，新枝复蒙密。","翛翛月下闻，褭褭林際出。","豈独对芳菲，終年色如一。"]', '诗', 'shi', '', NULL, '竹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79f3c3f-edf2-442b-9ee1-f12d5305b8b0', '懷素上人草書歌', '懷素上人草书歌', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["楚僧懷素工草書，古法盡能新有餘。","神清骨竦意真率，醉來爲我揮健筆。","始從破體變風姿，一一花開春景遲。","忽爲壯麗就枯澀，龍蛇騰盤獸屹立。","馳毫驟墨劇奔駟，滿座失聲看不及。","心手相師勢轉奇，詭形怪狀翻合宜。","人人細問此中妙，懷素自言初不知。"]', '["楚僧懷素工草书，古法尽能新有餘。","神清骨竦意真率，醉来爲我揮健笔。","始從破體变风姿，一一花开春景遲。","忽爲壯丽就枯澀，龙蛇腾盤獸屹立。","驰毫驟墨劇奔駟，满座失声看不及。","心手相師勢轉奇，詭形怪狀翻合宜。","人人細问此中妙，懷素自言初不知。"]', '诗', 'shi', '', NULL, '懷素上人草書歌 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065c182e-76f5-4777-b84e-e80651f509df', '女耕田行', '女耕田行', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["乳燕入巢笋成竹，誰家二女種新穀。","無人無牛不及犁，持刀斫地翻作泥。","自言家貧母年老，長兄從軍未娶嫂。","去年災疫牛囤空，截絹買刀都市中。","頭巾掩面畏人識，以刀代牛誰與同。","姊妹相攜心正苦，不見路人唯見土。","疏通畦隴防亂苗，整頓溝塍待時雨。","日正南岡下餉歸，可憐朝雉擾驚飛。","東鄰西舍花發盡，共惜餘芳淚滿衣。"]', '["乳燕入巢笋成竹，誰家二女種新穀。","無人無牛不及犁，持刀斫地翻作泥。","自言家貧母年老，长兄從軍未娶嫂。","去年災疫牛囤空，截絹買刀都市中。","头巾掩面畏人識，以刀代牛誰與同。","姊妹相携心正苦，不见路人唯见土。","疏通畦隴防亂苗，整頓溝塍待时雨。","日正南岡下餉归，可怜朝雉擾驚飞。","东鄰西舍花發尽，共惜餘芳泪满衣。"]', '诗', 'shi', '', NULL, '女耕田行 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44916888-b8b7-4a9e-95fe-d18888843b29', '柳花歌送客往桂陽', '柳花歌送客往桂陽', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["滄浪渡頭柳花發，斷續因風飛不絕。","搖烟拂水積翠間，綴雪含霜誰忍攀。","夾岸紛紛送君去，鳴櫂孤尋到何處。","移家深入桂水源，種柳新成花更繁。","定知別後消散盡，却憶今朝傷旅魂。"]', '["滄浪渡头柳花發，斷續因风飞不絕。","搖烟拂水積翠间，綴雪含霜誰忍攀。","夾岸紛紛送君去，鳴櫂孤尋到何处。","移家深入桂水源，種柳新成花更繁。","定知別後消散尽，却憶今朝傷旅魂。"]', '诗', 'shi', '', NULL, '柳花歌送客往桂陽 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1250a5c-8655-4616-86bd-bae55f8ec692', '邊城曲', '邊城曲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["人生莫作遠行客，遠行莫戍黃沙磧。","黃沙磧下八月時，霜風裂膚百草衰。","塵沙晴天迷道路，河水悠悠向東去。","胡笳聽徹雙淚流，羈魂慘慘生邊愁。","原頭獵火夜相向，馬蹄蹴蹋層冰上。","不似京華俠少年，清歌妙舞落花前。"]', '["人生莫作远行客，远行莫戍黄沙磧。","黄沙磧下八月时，霜风裂膚百草衰。","塵沙晴天迷道路，河水悠悠向东去。","胡笳听徹雙泪流，羈魂慘慘生邊愁。","原头獵火夜相向，马蹄蹴蹋層冰上。","不似京华俠少年，清歌妙舞落花前。"]', '诗', 'shi', '', NULL, '邊城曲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95949c09-0922-413f-9e5d-9bfb356d8f04', '屯田詞', '屯田词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["春來耕田遍沙磧，老稚欣欣種禾麥。","麥苗漸長天苦晴，土乾确确鉏不得。","新禾未熟飛蝗至，青苗食盡餘枯莖。","捕蝗歸來守空屋，囊無寸帛缾無粟。","十月移屯來向城，官教去伐南山木。","驅牛駕車入山去，霜重草枯牛凍死。","艱辛歷盡誰得知，望斷天南淚如雨。"]', '["春来耕田遍沙磧，老稚欣欣種禾麦。","麦苗漸长天苦晴，土乾确确鉏不得。","新禾未熟飞蝗至，青苗食尽餘枯莖。","捕蝗归来守空屋，囊無寸帛缾無粟。","十月移屯来向城，官教去伐南山木。","驱牛駕车入山去，霜重草枯牛凍死。","艱辛歷尽誰得知，望斷天南泪如雨。"]', '诗', 'shi', '', NULL, '屯田詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c410b3-6b61-4398-86e5-e4a6bfe07087', '巫山高', '巫山高', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["巫山峨峨高插天，危峰十二凌紫煙。","瞿塘嘈嘈急如弦，洄流勢逆將覆船。","雲梯豈可進，百[丈]那能牽，陸行巉巖水不前。","灑淚向流水，淚歸東海邊。","含愁對明月，明月空自圓。","故鄉回首思綿綿，側身天地心茫然。"]', '["巫山峨峨高插天，危峰十二凌紫煙。","瞿塘嘈嘈急如弦，洄流勢逆將覆船。","云梯豈可進，百[丈]那能牽，陸行巉巖水不前。","灑泪向流水，泪归东海邊。","含愁对明月，明月空自圓。","故乡回首思綿綿，側身天地心茫然。"]', '诗', 'shi', '', NULL, '巫山高 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39ab0c0-9771-4cce-910d-94eaddaf2908', '早春曲', '早春曲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["青樓昨夜東風轉，錦帳凝寒覺春淺。","垂楊搖絲鶯亂啼，褭褭煙光不堪翦。","博山吹雲龍腦香，銅壺滴愁更漏長。","玉頰啼紅夢初醒，羞見青鸞鏡中影。","儂家少年愛游逸，萬里輪蹄去無跡。","朱顏未衰消息稀，腸斷天涯草空碧。"]', '["青楼昨夜东风轉，錦帳凝寒覺春淺。","垂楊搖絲鶯亂啼，褭褭煙光不堪翦。","博山吹云龙腦香，銅壺滴愁更漏长。","玉頰啼紅梦初醒，羞见青鸾镜中影。","儂家少年愛游逸，万里輪蹄去無跡。","朱顏未衰消息稀，腸斷天涯草空碧。"]', '诗', 'shi', '', NULL, '早春曲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a629440-590c-46f8-ba98-f6e33a16a910', '白苧詞', '白苧词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["館娃宮中露華冷，月落啼鵶散金井。","吳王扶頭酒初醒，秉燭張筵樂清景。","美人不眠憐夜永，起舞亭亭亂花影。","新裁白苧勝紅綃，玉佩珠纓金步搖。","回鸞轉鳳意自嬌，銀箏錦瑟聲相調。","君恩如水流不斷，但願年年此同宵。","東風吹花落庭樹，春色催人等閑去。","大家爲歡莫延佇，頃刻銅龍報天曙。"]', '["館娃宮中露华冷，月落啼鵶散金井。","吳王扶头酒初醒，秉燭張筵乐清景。","美人不眠怜夜永，起舞亭亭亂花影。","新裁白苧勝紅綃，玉佩珠纓金步搖。","回鸾轉鳳意自嬌，銀箏錦瑟声相調。","君恩如水流不斷，但願年年此同宵。","东风吹花落庭樹，春色催人等闲去。","大家爲歡莫延佇，頃刻銅龙報天曙。"]', '诗', 'shi', '', NULL, '白苧詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a032115c-e129-487b-b0cb-c8d15f01d2a7', '行路難', '行路难', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["出門行路難，富貴安可期。","淮陰不免惡少辱，阮生亦作窮途悲。","顛倒英雄古來有，封侯却屬屠沽兒。","長安車馬隨輕肥，青雲賓從紛交馳。","白眼向人多意氣，宰牛烹羊如折葵。","讌樂寧知白日短，時時醉擁雙蛾眉。","揚雄閉門空讀書，門前碧草春離離。","不如拂衣且歸去，世上浮名徒爾爲。"]', '["出门行路难，富貴安可期。","淮陰不免惡少辱，阮生亦作窮途悲。","顛倒英雄古来有，封侯却屬屠沽兒。","长安车马隨轻肥，青云賓從紛交驰。","白眼向人多意氣，宰牛烹羊如折葵。","讌乐寧知白日短，时时醉擁雙蛾眉。","揚雄閉门空读书，门前碧草春離離。","不如拂衣且归去，世上浮名徒爾爲。"]', '诗', 'shi', '', NULL, '行路難 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('032ae665-b243-47cb-bce0-29ba76ab5871', '相思曲', '相思曲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["高樓重重閉明月，腸斷僊郎隔年別。","紫簫橫笛寂無聲，獨向瑤窗坐愁絕。","魚沈鴈杳天涯路，始信人間別離苦。","恨滿牙牀翡翠衾，怨折金釵鳳皇股。","井深轆轤嗟綆短，衣帶相思日應緩。","將刀斫水水復連，揮刃割情情不斷。","落紅亂逐東流水，一點芳心爲君死。","妾身願作巫山雲，飛入仙郎夢魂裏。"]', '["高楼重重閉明月，腸斷僊郎隔年別。","紫簫橫笛寂無声，独向瑤窗坐愁絕。","鱼沈鴈杳天涯路，始信人间別離苦。","恨满牙牀翡翠衾，怨折金釵鳳皇股。","井深轆轤嗟綆短，衣带相思日應緩。","將刀斫水水复連，揮刃割情情不斷。","落紅亂逐东流水，一点芳心爲君死。","妾身願作巫山云，飞入仙郎梦魂裏。"]', '诗', 'shi', '', NULL, '相思曲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa2573dd-66a5-4d1b-93a7-8ebd842af47c', '送別錢起', '送別錢起', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["陽關多古調，無奈醉中聞。","歸夢吳山遠，離情楚水分。","孤舟經暮雨，征路入秋雲。","後夜同明月，山窗定憶君。"]', '["陽关多古調，無奈醉中闻。","归梦吳山远，離情楚水分。","孤舟經暮雨，征路入秋云。","後夜同明月，山窗定憶君。"]', '诗', 'shi', '', NULL, '送別錢起 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf2d9c1-f855-415f-929b-6609bc18b8ab', '送張南史', '送張南史', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["陋巷無車轍，煙蘿總是春。","賈生獨未達，原憲竟忘貧。","草座留山月，荷衣遠洛塵。","最憐知己在，林下訪閑人。"]', '["陋巷無车轍，煙蘿總是春。","賈生独未達，原憲竟忘貧。","草座留山月，荷衣远洛塵。","最怜知己在，林下訪闲人。"]', '诗', 'shi', '', NULL, '送張南史 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de7087b-106a-46c1-bba4-cb54c90be50c', '春日早朝應制', '春日早朝應制', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["仙仗肅朝官，承平聖主歡。","月沈宮漏靜，雨濕禁花寒。","丹荔來金闕，朱櫻貢玉盤。","六龍扶御日，只許近臣看。"]', '["仙仗肅朝官，承平聖主歡。","月沈宮漏静，雨濕禁花寒。","丹荔来金闕，朱櫻貢玉盤。","六龙扶御日，只許近臣看。"]', '诗', 'shi', '', NULL, '春日早朝應制 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85664d8d-957f-45b3-8943-653dfe6f9570', '早行寄朱山人放', '早行寄朱山人放', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["山曉旅人去，天高秋氣悲。","明河川上沒，芳草露中衰。","此別又千里，少年能幾時。","心知剡溪路，聊且寄前期。"]', '["山晓旅人去，天高秋氣悲。","明河川上沒，芳草露中衰。","此別又千里，少年能幾时。","心知剡溪路，聊且寄前期。"]', '诗', 'shi', '', NULL, '早行寄朱山人放 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b8ef604-25bb-4670-baee-590b8bd7a99f', '除夜宿石頭驛', '除夜宿石头驛', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["旅館誰相問，寒燈獨可親。","一年將盡夜，萬里未歸人。","寥落悲前事，支離笑此身。","愁顏與衰鬢，明日又逢春。"]', '["旅館誰相问，寒灯独可親。","一年將尽夜，万里未归人。","寥落悲前事，支離笑此身。","愁顏與衰鬢，明日又逢春。"]', '诗', 'shi', '', NULL, '除夜宿石頭驛 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5502f772-645a-44bb-a825-797ef4a8bc2d', '吳明府自遠而來留宿', '吳明府自远而来留宿', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["出門逢故友，衣服滿塵埃。","歲月不可問，山川何處來。","綺城容弊宅，散職寄靈臺。","自此留君醉，相歡得幾回。"]', '["出门逢故友，衣服满塵埃。","歲月不可问，山川何处来。","綺城容弊宅，散職寄靈台。","自此留君醉，相歡得幾回。"]', '诗', 'shi', '', NULL, '吳明府自遠而來留宿 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94ae3e7e-eb5d-414c-bfd6-124f50687ce5', '客夜與故人偶集', '客夜與故人偶集', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["天秋月又滿，城闕夜千重。","還作江南會，翻疑夢裏逢。","風枝驚暗鵲，露草覆寒蛩。","羈旅長堪醉，相留畏曉鐘。"]', '["天秋月又满，城闕夜千重。","還作江南會，翻疑梦裏逢。","风枝驚暗鵲，露草覆寒蛩。","羈旅长堪醉，相留畏晓鐘。"]', '诗', 'shi', '', NULL, '客夜與故人偶集 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3bcc6e4-b13f-4000-961e-d5d77850bf28', '送友人東歸', '送友人东归', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["萬里楊柳色，出關送故人。","輕煙拂流水，落日照行塵。","積夢江湖闊，憶家兄弟貧。","裴回灞亭上，不語自傷春。"]', '["万里楊柳色，出关送故人。","轻煙拂流水，落日照行塵。","積梦江湖闊，憶家兄弟貧。","裴回灞亭上，不語自傷春。"]', '诗', 'shi', '', NULL, '送友人東歸 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2547b0a5-ba78-40c9-b95a-1c9ad3840518', '江上別張歡', '江上別張歡', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["年年五湖上，厭見五湖春。","長醉非關酒，多愁不爲貧。","山川迷道路，伊洛困風塵。","今日扁舟別，俱爲滄海人。"]', '["年年五湖上，厭见五湖春。","长醉非关酒，多愁不爲貧。","山川迷道路，伊洛困风塵。","今日扁舟別，俱爲滄海人。"]', '诗', 'shi', '', NULL, '江上別張歡 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d48316f-ab78-4a8e-b47e-87c28cde1763', '廣陵送趙主簿自蜀歸絳州寧覲', '廣陵送趙主簿自蜀归絳州寧覲', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["將歸汾水上，遠省錦城來。","已泛西江盡，仍隨北鴈迴。","暮雲征馬速，曉月故關開。","漸向庭闈近，留君醉一杯。"]', '["將归汾水上，远省錦城来。","已泛西江尽，仍隨北鴈迴。","暮云征马速，晓月故关开。","漸向庭闈近，留君醉一杯。"]', '诗', 'shi', '', NULL, '廣陵送趙主簿自蜀歸絳州寧覲 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7a3460-b622-461e-90a4-4838330f236f', '別友人', '別友人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["擾擾倦行役，相逢陳蔡間。","如何百年內，不見一人閑。","對酒惜餘景，問程愁亂山。","秋風萬里道，又出穆陵關。"]', '["擾擾倦行役，相逢陳蔡间。","如何百年內，不见一人闲。","对酒惜餘景，问程愁亂山。","秋风万里道，又出穆陵关。"]', '诗', 'shi', '', NULL, '別友人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d8fec3-5fcc-4b52-acb2-f405b374e67d', '宿城南盛本道懷皇甫冉', '宿城南盛本道懷皇甫冉', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["暑夜宿[南城]，懷人夢不成。","高樓邀落月，疊鼓送殘更。","隔浦雲林近，滿川風露清。","東碕不可見，矯首若爲情。"]', '["暑夜宿[南城]，懷人梦不成。","高楼邀落月，叠鼓送殘更。","隔浦云林近，满川风露清。","东碕不可见，矯首若爲情。"]', '诗', 'shi', '', NULL, '宿城南盛本道懷皇甫冉 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037dbc62-bcf2-4ab9-b784-5eb36fceb76f', '暉上人獨坐亭', '暉上人独坐亭', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["蕭條心境外，兀坐獨參禪。","蘿月明盤石，松風落潤泉。","性空長入定，心悟自通玄。","去住渾無跡，青山謝世緣。"]', '["蕭條心境外，兀坐独參禪。","蘿月明盤石，松风落潤泉。","性空长入定，心悟自通玄。","去住渾無跡，青山謝世緣。"]', '诗', 'shi', '', NULL, '暉上人獨坐亭 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d681657c-0c46-43c2-b207-9ef5caf0c494', '送崔融', '送崔融', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["王者應無敵，天兵動遠征。","建牙連朔漠，飛騎入胡城。","夜月邊城影，秋風隴水聲。","陳琳能草檄，含笑出長平。"]', '["王者應無敵，天兵动远征。","建牙連朔漠，飞騎入胡城。","夜月邊城影，秋风隴水声。","陳琳能草檄，含笑出长平。"]', '诗', 'shi', '', NULL, '送崔融 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53271d0c-d102-4246-9bb3-2bceeebfa579', '遊少林寺', '游少林寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["步入招提路，因之訪道林。","石龕苔蘚積，香徑白雲深。","雙樹含秋色，孤峰起夕陰。","屧廊行欲遍，回首一長吟。"]', '["步入招提路，因之訪道林。","石龕苔蘚積，香徑白云深。","雙樹含秋色，孤峰起夕陰。","屧廊行欲遍，回首一长吟。"]', '诗', 'shi', '', NULL, '遊少林寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9032f0a7-5e1b-4a5e-9170-1e66d98304ef', '崇德道中', '崇德道中', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["暖日菜心稠，晴煙麥穗抽。","客心雙去翼，歸夢一扁舟。","廢塔巢雙鶴，長波漾白鷗。","關山明月到，愴惻十年遊。"]', '["暖日菜心稠，晴煙麦穗抽。","客心雙去翼，归梦一扁舟。","廢塔巢雙鹤，长波漾白鷗。","关山明月到，愴惻十年游。"]', '诗', 'shi', '', NULL, '崇德道中 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6455fe19-27eb-4b87-afd7-b4f873e100c7', '雨', '雨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["歷歷愁心亂，迢迢獨夜長。","春帆江上雨，曉鏡鬢邊霜。","啼鳥雲山靜，落花溪水香。","家人亦念我，與汝黯相忘。"]', '["歷歷愁心亂，迢迢独夜长。","春帆江上雨，晓镜鬢邊霜。","啼鸟云山静，落花溪水香。","家人亦念我，與汝黯相忘。"]', '诗', 'shi', '', NULL, '雨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec3fc263-bbc7-4291-8bc7-2d03a1c1b8f8', '過賈誼宅', '過賈誼宅', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["一謫長沙地，三年歎逐臣。","上書憂漢室，作賦弔靈均。","舊宅秋荒草，西風客薦蘋。","淒涼回首處，不見洛陽人。"]', '["一謫长沙地，三年歎逐臣。","上书憂漢室，作賦弔靈均。","旧宅秋荒草，西风客薦蘋。","淒涼回首处，不见洛陽人。"]', '诗', 'shi', '', NULL, '過賈誼宅 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be804ea-a0ce-4aea-9e39-887f68cf31b5', '冬日有懷李賀長吉', '冬日有懷李賀长吉', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["歲晚齋居寂，情人動我思。","每因一尊酒，重和百篇詩。","月冷猨啼慘，天高鴈去遲。","夜郎流落久，何日是歸期。"]', '["歲晚斋居寂，情人动我思。","每因一尊酒，重和百篇诗。","月冷猨啼慘，天高鴈去遲。","夜郎流落久，何日是归期。"]', '诗', 'shi', '', NULL, '冬日有懷李賀長吉 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f4531a-d998-405a-a731-6aad0d5e9ea8', '送郎士元', '送郎士元', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["白髮金陵客，懷歸不暫留。","交情分兩地，行色載孤舟。","黃葉蟬吟晚，滄江鴈送秋。","何年重會此，詩酒復追游。"]', '["白髮金陵客，懷归不暫留。","交情分兩地，行色載孤舟。","黄葉蟬吟晚，滄江鴈送秋。","何年重會此，诗酒复追游。"]', '诗', 'shi', '', NULL, '送郎士元 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d6d7013-76d1-4214-882f-3a1aad5c53f0', '春江獨釣', '春江独釣', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["獨釣春江上，春江引趣長。","斷煙栖草碧，流水帶花香。","心事同沙鳥，浮生寄野航。","荷衣塵不染，何用濯滄浪。"]', '["独釣春江上，春江引趣长。","斷煙栖草碧，流水带花香。","心事同沙鸟，浮生寄野航。","荷衣塵不染，何用濯滄浪。"]', '诗', 'shi', '', NULL, '春江獨釣 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7870f171-e37e-4db8-a185-11456878bc13', '山居即事', '山居即事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["巖雲掩竹扉，去鳥帶餘暉。","地僻生涯薄，山深俗事稀。","養花分宿雨，翦葉補秋衣。","野渡逢漁子，同舟蕩月歸。"]', '["巖云掩竹扉，去鸟带餘暉。","地僻生涯薄，山深俗事稀。","養花分宿雨，翦葉補秋衣。","野渡逢漁子，同舟蕩月归。"]', '诗', 'shi', '', NULL, '山居即事 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f692193-2a80-41b5-b4bf-47176d040535', '賦得長亭柳', '賦得长亭柳', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["濯濯長亭柳，陰連灞水流。","雨搓金縷細，煙褭翠絲柔。","送客添新恨，聽鶯憶舊遊。","贈行多折取，那得到深秋。"]', '["濯濯长亭柳，陰連灞水流。","雨搓金縷細，煙褭翠絲柔。","送客添新恨，听鶯憶旧游。","贈行多折取，那得到深秋。"]', '诗', 'shi', '', NULL, '賦得長亭柳 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8a4cd3-227f-4ab1-815e-1a3cd4ab8397', '客中言懷', '客中言懷', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["白髮照烏紗，逢人只自嗟。","官閑如致仕，客久似無家。","夜雨孤燈夢，春風幾度花。","故園歸有日，詩酒老生涯。"]', '["白髮照烏紗，逢人只自嗟。","官闲如致仕，客久似無家。","夜雨孤灯梦，春风幾度花。","故园归有日，诗酒老生涯。"]', '诗', 'shi', '', NULL, '客中言懷 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa33b688-c3d1-4ad5-a22d-060ff0284ed1', '山行', '山行', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["山行分曙色，一路見人稀。","野鳥啼還歇，林花墮不飛。","雲迷棲鶴寺，水澀釣魚磯。","回首天將暝，逢僧話未歸。"]', '["山行分曙色，一路见人稀。","野鸟啼還歇，林花墮不飞。","云迷棲鹤寺，水澀釣鱼磯。","回首天將暝，逢僧話未归。"]', '诗', 'shi', '', NULL, '山行 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c428e4-35ed-46b6-baa2-557fe2465458', '春日訪山人', '春日訪山人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["遠訪山中客，分泉謾煮茶。","相攜林下坐，共惜鬢邊華。","歸路逢殘雨，沿溪見落花。","候門童子問，遊樂到誰家。"]', '["远訪山中客，分泉謾煮茶。","相携林下坐，共惜鬢邊华。","归路逢殘雨，沿溪见落花。","候门童子问，游乐到誰家。"]', '诗', 'shi', '', NULL, '春日訪山人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18e44fa-1116-482b-b2b6-8924c2a93f6f', '臥病', '臥病', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["門掩青山臥，莓苔積雨深。","病多知藥性，客久見人心。","衆鳥趨林健，孤蟬抱葉吟。","滄洲詩社散，無夢盍朋簪。"]', '["门掩青山臥，莓苔積雨深。","病多知藥性，客久见人心。","衆鸟趨林健，孤蟬抱葉吟。","滄洲诗社散，無梦盍朋簪。"]', '诗', 'shi', '', NULL, '臥病 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4882d2c6-162e-4d85-981d-33248c715568', '贈月溪羽士', '贈月溪羽士', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["月明溪水上，誰識步虛聲。","夜靜金波冷，風微玉練平。","自知塵夢遠，一洗道心清。","更弄瑤笙罷，秋空鶴又鳴。"]', '["月明溪水上，誰識步虛声。","夜静金波冷，风微玉練平。","自知塵梦远，一洗道心清。","更弄瑤笙罷，秋空鹤又鳴。"]', '诗', 'shi', '', NULL, '贈月溪羽士 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620d8028-e841-4433-b452-79da14a217b1', '贈行脚僧', '贈行脚僧', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["補衲隨緣住，難違塵外蹤。","木杯能渡水，鐵鉢肯降龍。","到處棲雲榻，何年臥雪峰。","知師歸日近，應偃舊房松。"]', '["補衲隨緣住，难違塵外蹤。","木杯能渡水，鐵鉢肯降龙。","到处棲云榻，何年臥雪峰。","知師归日近，應偃旧房松。"]', '诗', 'shi', '', NULL, '贈行脚僧 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af70ca68-0b8e-4066-a608-d3b99d5be866', '重遊長真寺', '重游长真寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["同到長真寺，青山四面同。","鳥啼花竹暗，人散戶庭空。","蒲潤千年雨，松門午夜風。","舊遊悲往日，回首各西東。"]', '["同到长真寺，青山四面同。","鸟啼花竹暗，人散戶庭空。","蒲潤千年雨，松门午夜风。","旧游悲往日，回首各西东。"]', '诗', 'shi', '', NULL, '重遊長真寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d66100e5-9fac-4ff9-8da7-43726dfc54d9', '晚望', '晚望', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["山氣碧氤氳，深林帶夕曛。","人歸孤嶂晚，犬吠隔溪雲。","杉竹何年種，煙塵此地分。","桃源寧異此，猶恐世間聞。"]', '["山氣碧氤氳，深林带夕曛。","人归孤嶂晚，犬吠隔溪云。","杉竹何年種，煙塵此地分。","桃源寧異此，猶恐世间闻。"]', '诗', 'shi', '', NULL, '晚望 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0e9034-1e1e-404a-99de-123ede62a56e', '寄贈翠巖奉上人', '寄贈翠巖奉上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["蘭若倚西岡，年深松桂長。","似聞葛洪井，還近贊公房。","挂衲雲林靜，翻經石榻涼。","下方一回首，煙露日蒼蒼。"]', '["蘭若倚西岡，年深松桂长。","似闻葛洪井，還近贊公房。","挂衲云林静，翻經石榻涼。","下方一回首，煙露日蒼蒼。"]', '诗', 'shi', '', NULL, '寄贈翠巖奉上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3321e8d-59fb-4be6-845c-f623b00e1c1e', '過龍灣五王閣訪友人不遇', '過龙灣五王閣訪友人不遇', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["野橋秋水落，江閣暝煙微。","白日又欲午，高人猶未歸。","青林依古塔，虛館靜柴扉。","坐久思題字，翻憐柿葉稀。"]', '["野橋秋水落，江閣暝煙微。","白日又欲午，高人猶未归。","青林依古塔，虛館静柴扉。","坐久思題字，翻怜柿葉稀。"]', '诗', 'shi', '', NULL, '過龍灣五王閣訪友人不遇 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75e3e5f-b328-44e8-8294-5f1b1a5e1c0c', '與友人過山寺', '與友人過山寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["共有春山興，幽尋此日同。","談詩訪靈徹，入社愧陶公。","竹暗閉房雨，茶香別院風。","誰知塵境外，路與白雲通。"]', '["共有春山兴，幽尋此日同。","談诗訪靈徹，入社愧陶公。","竹暗閉房雨，茶香別院风。","誰知塵境外，路與白云通。"]', '诗', 'shi', '', NULL, '與友人過山寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad19dbe-d1cc-45ca-bfd2-bf5e13a4d2ba', '賦得古井送王明府', '賦得古井送王明府', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["古井庇幽亭，涓涓一竇明。","仙源通海水，靈液孕山精。","久旱寧同涸，長年秪自清。","欲彰貞白操，酌獻使君行。"]', '["古井庇幽亭，涓涓一竇明。","仙源通海水，靈液孕山精。","久旱寧同涸，长年秪自清。","欲彰貞白操，酌獻使君行。"]', '诗', 'shi', '', NULL, '賦得古井送王明府 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f02dc7-f833-49d8-a67d-1b2f6684150e', '送耿十三湋復往遼海', '送耿十三湋复往遼海', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["仗劍萬里去，孤城遼海東。","旌旗愁落日，鼓角壯悲風。","野迥邊塵息，烽消戍壘空。","轅門正休暇，投策拜元戎。"]', '["仗劍万里去，孤城遼海东。","旌旗愁落日，鼓角壯悲风。","野迥邊塵息，烽消戍壘空。","轅门正休暇，投策拜元戎。"]', '诗', 'shi', '', NULL, '送耿十三湋復往遼海 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b2dd5f-2f9f-4d33-a641-6ba7d7493b59', '寄禪師寺華上人次韻三首 一', '寄禪師寺华上人次韻三首 一', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["百年渾是客，白髮總盈顛。","佛國三秋別，雲臺五色連。","朝盤香積飯，夜甕落花泉。","遙憶談玄地，月高人未眠。"]', '["百年渾是客，白髮總盈顛。","佛国三秋別，云台五色連。","朝盤香積飯，夜甕落花泉。","遙憶談玄地，月高人未眠。"]', '诗', 'shi', '', NULL, '寄禪師寺華上人次韻三首 一 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569d13a9-3432-4c46-8008-3abf484a41ba', '寄禪師寺華上人次韻三首 二', '寄禪師寺华上人次韻三首 二', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["禪心如落葉，不逐曉風顛。","猊坐翻蕭瑟，臯比喜接連。","芙蓉開紫霧，湘玉映清泉。","白晝談經罷，閑從石上眠。"]', '["禪心如落葉，不逐晓风顛。","猊坐翻蕭瑟，臯比喜接連。","芙蓉开紫霧，湘玉映清泉。","白晝談經罷，闲從石上眠。"]', '诗', 'shi', '', NULL, '寄禪師寺華上人次韻三首 二 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d1fa84-153c-4a45-95da-f90cb66f36a5', '寄禪師寺華上人次韻三首 三', '寄禪師寺华上人次韻三首 三', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["德士名難避，風流學濟顛。","禮羅加璧至，薦鶚與雲連。","塵世休飛錫，松林且枕泉。","近聞離講席，聽雨半山眠。"]', '["德士名难避，风流学濟顛。","禮羅加璧至，薦鶚與云連。","塵世休飞錫，松林且枕泉。","近闻離講席，听雨半山眠。"]', '诗', 'shi', '', NULL, '寄禪師寺華上人次韻三首 三 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40170491-a095-4f94-aad8-d556180cb33b', '獨坐', '独坐', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["白髮懷閩嶠，丹心戀薊門。","官閑勝道院，宅遠類荒村。","二月霜花薄，羣山雨氣昏。","東菑春事及，好向野人論。"]', '["白髮懷閩嶠，丹心戀薊门。","官闲勝道院，宅远類荒村。","二月霜花薄，羣山雨氣昏。","东菑春事及，好向野人論。"]', '诗', 'shi', '', NULL, '獨坐 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46f4cc6a-a027-4a06-84a9-56395fb8f130', '李大夫見贈因之有呈', '李大夫见贈因之有呈', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["何言訪衰疾，旌斾重淹留。","謝禮誠難荅，裁詩豈易酬。","江清寒照動，山迥野雲秋。","一醉龍沙上，終歡勝舊遊。"]', '["何言訪衰疾，旌斾重淹留。","謝禮誠难荅，裁诗豈易酬。","江清寒照动，山迥野云秋。","一醉龙沙上，終歡勝旧游。"]', '诗', 'shi', '', NULL, '李大夫見贈因之有呈 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea8e448-8578-44f3-8040-0c108cf016ff', '長沙送梁副端歸京', '长沙送梁副端归京', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["奏書歸闕下，祖帳出湘東。","滿座他鄉別，何年此會同。","藉芳憐岸草，聞笛怨江風。","且莫乘流去，心期在醉中。"]', '["奏书归闕下，祖帳出湘东。","满座他乡別，何年此會同。","藉芳怜岸草，闻笛怨江风。","且莫乘流去，心期在醉中。"]', '诗', 'shi', '', NULL, '長沙送梁副端歸京 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429399f8-4683-45ff-9a0d-6e5267513bb2', '和尉遲侍郎夏杪聞蟬', '和尉遲侍郎夏杪闻蟬', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["楚人方苦熱，柱史獨聞蟬。","晴日暮江上，驚風一葉前。","蕩搖清管雜，幽咽野風傳。","旅舍聞君聽，無由更晝眠。"]', '["楚人方苦熱，柱史独闻蟬。","晴日暮江上，驚风一葉前。","蕩搖清管杂，幽咽野风傳。","旅舍闻君听，無由更晝眠。"]', '诗', 'shi', '', NULL, '和尉遲侍郎夏杪聞蟬 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('923eceba-072c-4fe4-b193-6fd190839a14', '和李相公勉晦日蓬池遊宴', '和李相公勉晦日蓬池游宴', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["高會吹臺中，新年月桂空。","貂蟬臨野水，旌斾引春風。","細草縈斜岸，纖條出故叢。","微文復看獵，寧與解神同。"]', '["高會吹台中，新年月桂空。","貂蟬臨野水，旌斾引春风。","細草縈斜岸，纖條出故叢。","微文复看獵，寧與解神同。"]', '诗', 'shi', '', NULL, '和李相公勉晦日蓬池遊宴 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec91480-a38d-47e1-814e-2413278f6a6f', '彭婆館逢韋判官使還', '彭婆館逢韋判官使還', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["受辭分路遠，會府見君稀。","雨雪經年去，軒車此日歸。","暮春愁見別，久客順相依。","寂寞伊川上，楊花空自飛。"]', '["受辞分路远，會府见君稀。","雨雪經年去，軒车此日归。","暮春愁见別，久客順相依。","寂寞伊川上，楊花空自飞。"]', '诗', 'shi', '', NULL, '彭婆館逢韋判官使還 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55fb24cb-b3bd-400d-ab52-ce0d043574b9', '酬別劉九郎評事傳經同泉字', '酬別劉九郎評事傳經同泉字', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["舉袂掩離弦，枉君愁思篇。","忽驚池上鷺，下咽隴頭泉。","對牖牆陰滿，臨扉日影圓。","賴聞黃太守，章句此中傳。"]', '["舉袂掩離弦，枉君愁思篇。","忽驚池上鷺，下咽隴头泉。","对牖牆陰满，臨扉日影圓。","賴闻黄太守，章句此中傳。"]', '诗', 'shi', '', NULL, '酬別劉九郎評事傳經同泉字 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f66359-5261-40fe-aa02-0858906f0598', '漢南遇方評事', '漢南遇方評事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["移家住漢陰，不復問華簪。","貰酒宜城近，燒田夢澤深。","暮山逢鳥入，寒水見魚沈。","與物皆無累，終年愜本心。"]', '["移家住漢陰，不复问华簪。","貰酒宜城近，燒田梦澤深。","暮山逢鸟入，寒水见鱼沈。","與物皆無累，終年愜本心。"]', '诗', 'shi', '', NULL, '漢南遇方評事 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8090e457-24df-4e6c-996b-3b81bb0d82a0', '湘中懷古', '湘中懷古', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["昔人從逝水，有客弔秋風。","何意千年隔，論心一日同。","楚亭方作亂，漢律正酬功。","倏忽桑田變，讒言亦已空。"]', '["昔人從逝水，有客弔秋风。","何意千年隔，論心一日同。","楚亭方作亂，漢律正酬功。","倏忽桑田变，讒言亦已空。"]', '诗', 'shi', '', NULL, '湘中懷古 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793368a9-a932-42cc-bf9c-e959f80b45eb', '京口懷古', '京口懷古', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["大江橫萬里，古渡渺千秋。","浩浩波聲險，蒼蒼天色愁。","三方歸漢鼎，一水限吳州。","霸國今何在，清泉長自流。"]', '["大江橫万里，古渡渺千秋。","浩浩波声險，蒼蒼天色愁。","三方归漢鼎，一水限吳州。","霸国今何在，清泉长自流。"]', '诗', 'shi', '', NULL, '京口懷古 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63f90cc-4ef7-4234-b76e-2532517ff7b6', '逢友生言懷', '逢友生言懷', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["安親非避地，羈旅十餘年。","道長時流許，家貧故舊憐。","相逢今歲暮，遠別一方偏。","去住俱難說，江湖正渺然。"]', '["安親非避地，羈旅十餘年。","道长时流許，家貧故旧怜。","相逢今歲暮，远別一方偏。","去住俱难说，江湖正渺然。"]', '诗', 'shi', '', NULL, '逢友生言懷 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4d67f8-36ac-41eb-a77a-d1c8f6124b41', '長門怨', '长门怨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["自憶專房寵，曾居第一流。","移恩向他處，暫妒不容收。","夜靜管弦絕，月明宮殿秋。","空將舊時意，長望鳳皇樓。"]', '["自憶專房寵，曾居第一流。","移恩向他处，暫妒不容收。","夜静管弦絕，月明宮殿秋。","空將旧时意，长望鳳皇楼。"]', '诗', 'shi', '', NULL, '長門怨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e764d248-d37f-476d-8b21-a0e670462087', '郊園即事寄蕭侍郎', '郊园即事寄蕭侍郎', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["衰鬢辭餘秩，秋風入故園。","結茅成暖室，汲井及清源。","鄰里桑麻接，兒童笑語喧。","終朝非役役，聊寄遠人言。"]', '["衰鬢辞餘秩，秋风入故园。","結茅成暖室，汲井及清源。","鄰里桑麻接，兒童笑語喧。","終朝非役役，聊寄远人言。"]', '诗', 'shi', '', NULL, '郊園即事寄蕭侍郎 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95714d30-d40c-4390-9100-eb148b6b28c4', '贈韋評事儹', '贈韋評事儹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["與道共浮沈，人間歲月深。","是非園吏夢，憂喜塞翁心。","細草誰開徑，芳條自結陰。","由來居物外，無事可抽簪。"]', '["與道共浮沈，人间歲月深。","是非园吏梦，憂喜塞翁心。","細草誰开徑，芳條自結陰。","由来居物外，無事可抽簪。"]', '诗', 'shi', '', NULL, '贈韋評事儹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba352bc9-9eb6-4886-923f-07330f530e54', '送少微上人入蜀', '送少微上人入蜀', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["十方俱是夢，一念偶尋山。","望剎經巴寺，持瓶向蜀關。","亂猨心本定，流水性長閑。","世俗多離別，王城幾日還。"]', '["十方俱是梦，一念偶尋山。","望剎經巴寺，持瓶向蜀关。","亂猨心本定，流水性长闲。","世俗多離別，王城幾日還。"]', '诗', 'shi', '', NULL, '送少微上人入蜀 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1752fbf4-95f6-4138-989f-9c19a6bd4106', '送道虔上人遊方', '送道虔上人游方', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["律儀通外學，詩思入禪關。","煙景隨緣到，風姿與道閑。","貫花留靜室，咒水度空山。","誰識浮雲意，悠悠天地間。"]', '["律儀通外学，诗思入禪关。","煙景隨緣到，风姿與道闲。","貫花留静室，咒水度空山。","誰識浮云意，悠悠天地间。"]', '诗', 'shi', '', NULL, '送道虔上人遊方 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10413ab8-4600-43cc-956f-045ce6b1e6dd', '送嵩律師頭陁寺', '送嵩律師头陁寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["相傳五部學，更有一人成。","此日靈山去，何方半座迎。","麻衣逢雪暖，草履躡雲輕。","若見中林石，應知第四生。"]', '["相傳五部学，更有一人成。","此日靈山去，何方半座迎。","麻衣逢雪暖，草履躡云轻。","若见中林石，應知第四生。"]', '诗', 'shi', '', NULL, '送嵩律師頭陁寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f12ad26b-b20f-49cb-846d-3499b611e290', '舟中見雨', '舟中见雨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["今夜初聽雨，江南杜若青。","功名何鹵莽，兄弟總彫零。","夢遠愁蝴蝶，情深愧鶺鴒。","撫孤終日意，身世尚流萍。"]', '["今夜初听雨，江南杜若青。","功名何鹵莽，兄弟總彫零。","梦远愁蝴蝶，情深愧鶺鴒。","撫孤終日意，身世尚流萍。"]', '诗', 'shi', '', NULL, '舟中見雨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbea4caf-5ceb-43fd-8a50-843fe173c2ac', '送僧南歸', '送僧南归', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["兵塵猶澒洞，僧舍亦徵求。","師向江南去，予方轂下留。","風霜兩足白，宇宙一身浮。","歸及梅花發，題詩寄隴頭。"]', '["兵塵猶澒洞，僧舍亦徵求。","師向江南去，予方轂下留。","风霜兩足白，宇宙一身浮。","归及梅花發，題诗寄隴头。"]', '诗', 'shi', '', NULL, '送僧南歸 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd647c8-41ad-43eb-bce7-855eb14d8cc2', '江干', '江干', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["江干望不極，樓閣影繽紛。","水氣多爲雨，人煙遠是雲。","予生何濩落，客路轉辛勤。","楊柳牽愁思，和春上翠帬。"]', '["江干望不極，楼閣影繽紛。","水氣多爲雨，人煙远是云。","予生何濩落，客路轉辛勤。","楊柳牽愁思，和春上翠帬。"]', '诗', 'shi', '', NULL, '江干 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf0e38a-50c3-40f9-80a3-cd1246aa8288', '過友人隱居', '過友人隐居', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["瀟灑絕塵喧，清溪流遶門。","水聲鳴石瀨，蘿影到林軒。","地靜留眠鹿，庭虛下飲猨。","春花正夾岸，何必問桃源。"]', '["瀟灑絕塵喧，清溪流遶门。","水声鳴石瀨，蘿影到林軒。","地静留眠鹿，庭虛下饮猨。","春花正夾岸，何必问桃源。"]', '诗', 'shi', '', NULL, '過友人隱居 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('724a9196-3c47-4e7c-8870-e793ee066415', '宿天竺寺曉發羅源', '宿天竺寺晓發羅源', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["黃昏投古寺，深院一燈明。","水砌長杉列，風廊敗葉鳴。","山雲留別偈，王事速歸程。","迢遰羅源路，輕輿候曉行。"]', '["黄昏投古寺，深院一灯明。","水砌长杉列，风廊敗葉鳴。","山云留別偈，王事速归程。","迢遰羅源路，轻輿候晓行。"]', '诗', 'shi', '', NULL, '宿天竺寺曉發羅源 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baaa5dfa-6510-474c-99f9-a03c32768b4d', '留宿羅源西峰寺示輝上人', '留宿羅源西峰寺示輝上人', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["一宿西峰寺，塵煩暫覺清。","遠林生夕籟，高閣起鐘聲。","山寂僧初定，廊深火自明。","雖云殊出處，聊與說無生。"]', '["一宿西峰寺，塵煩暫覺清。","远林生夕籟，高閣起鐘声。","山寂僧初定，廊深火自明。","雖云殊出处，聊與说無生。"]', '诗', 'shi', '', NULL, '留宿羅源西峰寺示輝上人 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f1624e-7ad1-4ca1-b946-6254b905f1a2', '題橫山寺', '題橫山寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["偶入橫山寺，湖山景最幽。","露涵松翠濕，風湧浪花浮。","老衲供茶盌，斜陽送客舟。","自緣歸思促，不得更遲留。"]', '["偶入橫山寺，湖山景最幽。","露涵松翠濕，风湧浪花浮。","老衲供茶盌，斜陽送客舟。","自緣归思促，不得更遲留。"]', '诗', 'shi', '', NULL, '題橫山寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e5262b-b22a-4cc5-b251-46d7a8d4cb89', '泛舟', '泛舟', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["風軟扁舟穩，行依綠水堤。","孤尊秋露滑，短櫂晚煙迷。","夜靜月初上，江空天更低。","飄飄信流去，悞過子猷溪。"]', '["风軟扁舟穩，行依綠水堤。","孤尊秋露滑，短櫂晚煙迷。","夜静月初上，江空天更低。","飄飄信流去，悞過子猷溪。"]', '诗', 'shi', '', NULL, '泛舟 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86791562-7f76-43b0-b239-598d641fadd3', '宿靈巖寺', '宿靈巖寺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["馬疲盤道峻，投宿入招提。","雨急山溪漲，雲迷嶺樹低。","涼風來殿角，赤日下天西。","偃腹虛簷外，林空鳥恣啼。"]', '["马疲盤道峻，投宿入招提。","雨急山溪漲，云迷嶺樹低。","涼风来殿角，赤日下天西。","偃腹虛簷外，林空鸟恣啼。"]', '诗', 'shi', '', NULL, '宿靈巖寺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d105844-3175-4e39-90ba-bb869891646e', '江上別劉駕', '江上別劉駕', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["天涯芳草遍，江路又逢春。","海月留人醉，山花笑客貧。","離杯傾祖帳，征騎逐行塵。","回首風流地，登臨少一人。"]', '["天涯芳草遍，江路又逢春。","海月留人醉，山花笑客貧。","離杯傾祖帳，征騎逐行塵。","回首风流地，登臨少一人。"]', '诗', 'shi', '', NULL, '江上別劉駕 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102ba9a8-65ac-4347-baf5-21fef20bcc65', '南軒', '南軒', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["野居何處是，軒外一橫塘。","座納薰風細，簾垂白日長。","面山如對畫，臨水坐流觴。","更愛閑花木，欣欣得向陽。"]', '["野居何处是，軒外一橫塘。","座納薰风細，簾垂白日长。","面山如对畫，臨水坐流觴。","更愛闲花木，欣欣得向陽。"]', '诗', 'shi', '', NULL, '南軒 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f878d7c0-7f8b-4deb-bebb-d450bb7ac331', '泊鴈', '泊鴈', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["泊鴈鳴深渚，收霞落晚川。","柝隨風斂陣，樓映月低弦。","漠漠汀帆轉，幽幽岸火然。","壑危通細路，溝曲繞平田。"]', '["泊鴈鳴深渚，收霞落晚川。","柝隨风斂陣，楼映月低弦。","漠漠汀帆轉，幽幽岸火然。","壑危通細路，溝曲繞平田。"]', '诗', 'shi', '', NULL, '泊鴈 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8f776f-0c85-48a6-8565-da85a2ab2123', '巡諸州漸次空靈戍', '巡諸州漸次空靈戍', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["寒盡鴻先至，春回客未歸。","蚤知名是病，不敢繡爲衣。","霧積川原暗，山多郡縣稀。","明朝下湘岸，更逐鷓鴣飛。"]', '["寒尽鴻先至，春回客未归。","蚤知名是病，不敢繡爲衣。","霧積川原暗，山多郡縣稀。","明朝下湘岸，更逐鷓鴣飞。"]', '诗', 'shi', '', NULL, '巡諸州漸次空靈戍 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d071b0f6-bdaa-42be-96df-ab00f8186a52', '潭州使院書情寄江夏賀蘭副端', '潭州使院书情寄江夏賀蘭副端', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["雲雨一蕭散，悠悠關復河。","俱從汎舟役，近隔洞庭波。","楚水去不盡，秋風今又過。","無因得相見，却恨寄書多。"]', '["云雨一蕭散，悠悠关复河。","俱從汎舟役，近隔洞庭波。","楚水去不尽，秋风今又過。","無因得相见，却恨寄书多。"]', '诗', 'shi', '', NULL, '潭州使院書情寄江夏賀蘭副端 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8284ada-18a4-46ad-8a47-c2b0c02204ff', '過柳州', '過柳州', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["地盡江南戍，山分桂北林。","火雲三月合，石路九疑深。","暗谷隨風過，危橋共鳥尋。","羈魂愁似絕，不復待猨吟。"]', '["地尽江南戍，山分桂北林。","火云三月合，石路九疑深。","暗谷隨风過，危橋共鸟尋。","羈魂愁似絕，不复待猨吟。"]', '诗', 'shi', '', NULL, '過柳州 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a76081-ee79-4913-b0c4-b2163366db31', '經巴東嶺', '經巴东嶺', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["巴山不可上，徒馭亦裴回。","舊棧歌難度，朝雲濕未開。","瀑泉飛雪雨，驚獸走風雷。","此去無停候，征人幾日回。"]', '["巴山不可上，徒馭亦裴回。","旧棧歌难度，朝云濕未开。","瀑泉飞雪雨，驚獸走风雷。","此去無停候，征人幾日回。"]', '诗', 'shi', '', NULL, '經巴東嶺 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b725ab1b-8c34-4b5a-84e4-b675f8b69ebe', '過申州', '過申州', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["萬人曾戰死，幾處見休兵。","井邑初安堵，兒童未長成。","涼風吹古木，野火入殘營。","牢落千餘里，山空水復清。"]', '["万人曾戰死，幾处见休兵。","井邑初安堵，兒童未长成。","涼风吹古木，野火入殘營。","牢落千餘里，山空水复清。"]', '诗', 'shi', '', NULL, '過申州 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cdc9bb-3c88-4415-afac-2b4e58aff020', '次下牢韻', '次下牢韻', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["獨立荒亭上，蕭蕭對晚風。","天高吳塞闊，日落楚山空。","猨叫三聲斷，江流一水通。","前程千萬里，一夕宿巴東。"]', '["独立荒亭上，蕭蕭对晚风。","天高吳塞闊，日落楚山空。","猨叫三声斷，江流一水通。","前程千万里，一夕宿巴东。"]', '诗', 'shi', '', NULL, '次下牢韻 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be93ebfd-afa5-4786-b428-079e7fb904e2', '潘處士宅會別', '潘处士宅會別', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["相邀寒影晚，惜別故山空。","鄰里疎林在，池塘野水通。","十年難遇後，一醉幾人同。","復此悲行子，蕭蕭逐轉蓬。"]', '["相邀寒影晚，惜別故山空。","鄰里疎林在，池塘野水通。","十年难遇後，一醉幾人同。","复此悲行子，蕭蕭逐轉蓬。"]', '诗', 'shi', '', NULL, '潘處士宅會別 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba70934d-2cd2-4c17-93d9-9fdddfc57807', '暮春沐髮晦日書懷寄韋功曹渢李錄事從訓王少府純', '暮春沐髮晦日书懷寄韋功曹渢李錄事從訓王少府純', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["朝沐敞南闈，盤跚待日晞。","持梳髮更落，覽鏡意多違。","吾友見嘗少，春風去不歸。","登高取一醉，猶可及芳菲。"]', '["朝沐敞南闈，盤跚待日晞。","持梳髮更落，覽镜意多違。","吾友见嘗少，春风去不归。","登高取一醉，猶可及芳菲。"]', '诗', 'shi', '', NULL, '暮春沐髮晦日書懷寄韋功曹渢李錄事從訓王少府純 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6de6b7e8-1416-4973-9c8e-1fb8583fe9ea', '長安早春贈萬評事', '长安早春贈万評事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["春風歸戚里，曉日上花枝。","清管新鶯發，重門細柳垂。","經過千騎客，調笑五陵兒。","何事靈臺客，狂歌自不知。"]', '["春风归戚里，晓日上花枝。","清管新鶯發，重门細柳垂。","經過千騎客，調笑五陵兒。","何事靈台客，狂歌自不知。"]', '诗', 'shi', '', NULL, '長安早春贈萬評事 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de25722d-0e68-4f4b-9848-c00c6fd235b8', '留別宋處士', '留別宋处士', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["留歡方繼燭，此會豈他人。","鄉里遊從舊，兒童內外親。","夜深愁不醉，老去別何頻。","莫折園中柳，相看惜暮春。"]', '["留歡方繼燭，此會豈他人。","乡里游從旧，兒童內外親。","夜深愁不醉，老去別何頻。","莫折园中柳，相看惜暮春。"]', '诗', 'shi', '', NULL, '留別宋處士 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46932f6d-eead-473e-baa5-f4964c35256f', '留別道州李使君圻', '留別道州李使君圻', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["瀧路下丹徼，郵童揮畫橈。","山回千騎隱，雲斷兩鄉遙。","漁滬擁寒溜，畬田落遠燒。","維舟更相憶，惆悵坐空宵。"]', '["瀧路下丹徼，郵童揮畫橈。","山回千騎隐，云斷兩乡遙。","漁滬擁寒溜，畬田落远燒。","維舟更相憶，惆悵坐空宵。"]', '诗', 'shi', '', NULL, '留別道州李使君圻 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb3dbb9b-a1f3-4d72-9cff-32e7dc1c9394', '將遊東都留別包諫議', '將游东都留別包諫議', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["衰客慙墨綬，素舸逐秋風。","雲雨恩難報，江湖意已終。","縣當仙洞口，路出故園東。","唯有新離恨，長留夢寐中。"]', '["衰客慙墨綬，素舸逐秋风。","云雨恩难報，江湖意已終。","縣當仙洞口，路出故园东。","唯有新離恨，长留梦寐中。"]', '诗', 'shi', '', NULL, '將遊東都留別包諫議 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e970ba00-44ec-487e-b91d-af402def0099', '灞岸別友', '灞岸別友', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["車馬去遲遲，離言未盡時。","看花一醉別，會面幾年期。","樵路高山館，漁洲楚帝祠。","南登回首處，猶得望京師。"]', '["车马去遲遲，離言未尽时。","看花一醉別，會面幾年期。","樵路高山館，漁洲楚帝祠。","南登回首处，猶得望京師。"]', '诗', 'shi', '', NULL, '灞岸別友 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e6a54ca-94ec-4d07-841e-117036eb2c4d', '臨川從事還別崔法曹', '臨川從事還別崔法曹', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["謬官辭獲免，濫獄會平反。","遠與故人別，龍鍾望所言。","陰天寒不雨，古木夜多猨。","老病北歸去，餘年學灌園。"]', '["謬官辞獲免，濫獄會平反。","远與故人別，龙鍾望所言。","陰天寒不雨，古木夜多猨。","老病北归去，餘年学灌园。"]', '诗', 'shi', '', NULL, '臨川從事還別崔法曹 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cab2b12-b5aa-4633-a0b0-5a7d30b33b4c', '海上別薛舟', '海上別薛舟', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["行旅悲搖落，風波厭別離。","客程秋草遠，心事故人知。","暮鳥翻江岸，征徒起路岐。","自應無定所，還似欲相隨。"]', '["行旅悲搖落，风波厭別離。","客程秋草远，心事故人知。","暮鸟翻江岸，征徒起路岐。","自應無定所，還似欲相隨。"]', '诗', 'shi', '', NULL, '海上別薛舟 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e641d940-1046-4717-a1eb-e7eff336bc3b', '婺州路別錄事', '婺州路別錄事', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["府中相見少，江上獨行遙。","會日起離恨，新年別舊僚。","春雲猶伴雪，寒渚未通潮。","回首羣山暝，思君轉寂寥。"]', '["府中相见少，江上独行遙。","會日起離恨，新年別旧僚。","春云猶伴雪，寒渚未通潮。","回首羣山暝，思君轉寂寥。"]', '诗', 'shi', '', NULL, '婺州路別錄事 戴叔倫 shi');
